!***********************************************************************
!                                                                      *
      subroutine init_anatal
!                                                                      *
!     create by S. Hashimoto on 2019/07/29                             *
!     initialize for anatally variables                                *
!                                                                      *
!***********************************************************************

       use anatallymod
       use sumtallymod

       implicit none

!-----------------------------------------------------------------------

       include 'param.inc'

!-----------------------------------------------------------------------

       integer   i

!>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
!    allocated variable arrays
!>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

       if( itlmax > 0 ) then
        allocate (  nanatalRead(itlmax) )

        allocate( manatally  (itlmax))
        allocate(ianataldchain(itlmax))
        allocate( tallyfolder(itlmax))
        allocate(ltallyfolder(itlmax))
        allocate( tallyfile  (itlmax))
        allocate(ltallyfile  (itlmax))

        allocate( resc2ANATAL(itlmax))
        allocate( resc3ANATAL(itlmax))

        allocate(  cx_txt(itlmax))
        allocate( lcx_txt(itlmax))
        allocate(  cy_txt(itlmax))
        allocate( lcy_txt(itlmax))
        allocate(  cz_txt(itlmax))
        allocate( lcz_txt(itlmax))
       end if

!>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
!    initilized variable arrays
!>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

 1000  continue
       do i = 1, itlmax
        nanatalRead(i) = 0
        manatally  (i) = 0
        ianataldchain(i) = 0

        tallyfolder(i) = ' '
       ltallyfolder(i) = 0
        tallyfile  (i) = ' '
       ltallyfile  (i) = 0

         nfile     (i) = 0
         sumWR     (i) = 0.0d0

         sfile     (i) = ' '
        lsfile     (i) = 0

         sumfactor (i) = 0.0d0

         sumang    (i) = ' '
        lsumang    (i) = 0


        resc2ANATAL(i) = 0.0d0
        resc3ANATAL(i) = 0.0d0
       end do

!-----------------------------------------------------------------------

 9999  continue
       return

      end subroutine init_anatal
!***********************************************************************


************************************************************************
*                                                                      *
      subroutine read_anatal(jsn,jsi,dsin,idsi,ill,ilf,
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)
*                                                                      *
*       read [anatally] section of input files                         *
*                                                                      *
************************************************************************

      use anatallymod
      use sumtallymod

      implicit real*8 (a-h,o-z)

      include 'err.inc'

*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

!-----------------------------------------------------------------------

       character tname*12
       data      tname /'anatally end'/

       integer   isc            ! output unit number for scrach file

       integer   nanat
       integer   i

*-----------------------------------------------------------------------

      common /canat/  ianat

*-----------------------------------------------------------------------

      ierr  = 0

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140 continue

      call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &     jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

      if( ierr .ne. 0 ) return
      if( jpn  .eq. 3 ) return

      if( iskip .ne. 0 ) goto 140

*-----------------------------------------------------------------------
*     end of anatally section
*-----------------------------------------------------------------------

      if( i1 .le. 5 .and. chlw(i1:i1) .eq. '[' ) then

         jpn = 1
         return

      end if

!-----------------------------------------------------------------------
!     the number of analyzing tallies
!-----------------------------------------------------------------------

      ianat = ianat + 1
      ianataldchaint = 0

!-----------------------------------------------------------------------
!        anatally sub section
!-----------------------------------------------------------------------

      if ( chlw(i1:i1+13) .eq. 'anatally start' ) then ! check just "anatally start", S.H. 2021.1.8

!-----------------------------------------------------------------------

         call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &        jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

         if ( chlw(i1:i1+12) .eq. 'ianataldchain' ) then
            ic = inumc(chlw,i1+1,i3,'=') + 1
            ic = jnumc(chlw,ic,i3)
            if( ic .gt. i3 ) goto 9000
            icl = inumc(chlw,ic,i3,';') - 1
            call onum(chlw,ic,icl,cvvv,ierr)
            if( ierr .ne. 0 ) goto 9000
            ianataldchaint = nint( cvvv )
            backspace(jsi,err=146)
            ill(jsn) = ill(jsn) - 1
 146        continue
            backspace(jsi,err=147)
            ill(jsn) = ill(jsn) - 1
 147        continue
            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &           jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
         else
            backspace(jsi,err=148)
            ill(jsn) = ill(jsn) - 1
 148        continue
            backspace(jsi,err=149)
            ill(jsn) = ill(jsn) - 1
 149        continue
            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &           jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
         end if

!-----------------------------------------------------------------------
!        other than t-dchain
!-----------------------------------------------------------------------

       if ( ianataldchaint .eq. 0 ) then

*-----------------------------------------------------------------------

       jpn  = 0

       isc = 152
       if( ianat == 1 ) then
        open(isc,form='unformatted',status='scratch')
       end if

       write(isc) chlw       ! anatally start
       write(isc) jsn        ! include level
       write(isc) dsin(jsn)  ! input file name
       write(isc) idsi(jsn)  ! length of input file name
       write(isc) ill(jsn)   ! input file lines
       write(isc) ilf(jsn)   ! final line to read

!-----------------------------------------------------------------------
!     read one line from jsi
!-----------------------------------------------------------------------

  100  continue

       call anatal_readlt(isc,jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &            jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

       if( ierr .ne. 0 ) go to 9000
       if( iskip /= 0 ) then
        write(isc) chin
        goto 100
       end if
       if( jpn == 3 ) then        ! q:
        write(isc) 'q:'
        goto 9000
       else if( jpn == 1 ) then        ! qp:
        write(isc) 'qp:'
        goto 9000
       end if

!-----------------------------------------------------------------------
!     end of the section (error)
!-----------------------------------------------------------------------

       if( chlw(i1:i1) .eq. '[' ) then
        m_err = 'Not found anatally end'
        ErrCha = ''
        ErrID = 'L:257/R:read_anatal/F:anatally.f'
        l_err = ill(jsn)
        k_err = jsn
        ierr = 1
        goto 9000
       end if

       write(isc) chin
       if ( chlw(i1:i3-5) .ne. tname ) go to 100    ! end of anatally sub section?

!-----------------------------------------------------------------------
!        t-dchain
!-----------------------------------------------------------------------

       else

!-----------------------------------------------------------------------

       jpn  = 0

       isc = 152
       isct= isc+1
       if( ianat == 1 ) then
        open(isc,form='unformatted',status='scratch')
       end if
       open(isct,form='unformatted',status='scratch',action='readwrite')
       write(isct) chlw       ! anatally start
       write(isct) jsn        ! include level
       write(isct) dsin(jsn)  ! input file name
       write(isct) idsi(jsn)  ! length of input file name
       write(isct) ill(jsn)   ! input file lines
       write(isct) ilf(jsn)   ! final line to read

!-----------------------------------------------------------------------
!     read one line from jsi
!-----------------------------------------------------------------------

 101   continue

       call anatal_readlt(isc,jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &            jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

       if( ierr .ne. 0 ) go to 9000
       if( iskip /= 0 ) then
        write(isc) chin
        goto 101
       end if
       if( jpn == 3 ) then        ! q:
        write(isc) 'q:'
        goto 9000
       else if( jpn == 1 ) then        ! qp:
        write(isc) 'qp:'
        goto 9000
       end if

!-----------------------------------------------------------------------
!     end of the section (error)
!-----------------------------------------------------------------------

       if( chlw(i1:i1) .eq. '[' ) then
        m_err = 'Not found anatally end'
        ErrCha = ''
        ErrID = 'L:319/R:read_anatal/F:anatally.f'
        l_err = ill(jsn)
        k_err = jsn
        ierr = 1
        goto 9000
       end if

       write(isct) chin
       if ( chlw(i1:i3-5) .ne. tname ) go to 101    ! end of anatally sub section?

!-----------------------------------------------------------------------
!     temp. scrach file ===> scrach file
!-----------------------------------------------------------------------

       endfile(isct)

       do i=1, 3               ! t-yield / t-track / t-dchain
        rewind (isct)

        do
         read(isct,end=999) chin
         call chlngt(chin,200,i1,i2)
         chlw = chin
         call chcaps(chlw,i1,i2,i3,'#!$')
         if ( chlw(i1:i1+13) .eq. 'anatally start' ) then
          read(isct) jsn        ! include level
          read(isct) dsin(jsn)  ! input file name
          read(isct) idsi(jsn)  ! length of input file name
          read(isct) ill(jsn)   ! input file lines
          read(isct) ilf(jsn)   ! final line to read

          write(isc) chlw
          write(isc) jsn        ! include level
          write(isc) dsin(jsn)  ! input file name
          write(isc) idsi(jsn)  ! length of input file name
          write(isc) ill(jsn)   ! input file lines
          write(isc) ilf(jsn)   ! final line to read

         else if ( chlw == 'incinc' .or.
     &             chlw == 'incdec' ) then
          read(isct) jsn        ! include level
          read(isct) dsin(jsn)  ! input file name
          read(isct) idsi(jsn)  ! length of input file name
          read(isct) ill(jsn)   ! input file lines
          read(isct) ilf(jsn)   ! final line to read

          write(isc) chlw
          write(isc) jsn        ! include level
          write(isc) dsin(jsn)  ! input file name
          write(isc) idsi(jsn)  ! length of input file name
          write(isc) ill(jsn)   ! input file lines
          write(isc) ilf(jsn)   ! final line to read

         else
          write(isc) chin
         end if
        end do
  999   continue

       end do

!-----------------------------------------------------------------------

       close(isct)
       end if

!-----------------------------------------------------------------------

 9000  continue

       if( ierr .ne. 0 ) return
       if( jpn == 3 ) return   ! 'q:'
       if( jpn == 1 ) return   ! end of the section
       go to 140
      end if

*-----------------------------------------------------------------------

      goto 140

*-----------------------------------------------------------------------

      end
!***********************************************************************


!***********************************************************************
!                                                                      *
      subroutine set_anatal(io,jo,ierr)
!                                                                      *
!     read anatally sub section data from scrach file                  *
!     create by T.Miura on 2014/11/30                                  *
!     modified by T.Miura on 2015/07/31 (multiple tally inputs)        *
!                            2022/06/30 anatally sub-section           *
!                                       (icntl=17 mode)                *
!                                                                      *
!***********************************************************************

       use anatallymod
       use sumtallymod

       implicit none

!-----------------------------------------------------------------------

       include 'param.inc'
       include 'err.inc'

       integer   mh
       integer   mxcval
       integer   icolm
       integer   ichrl
       integer   inig
       integer   mc
       integer   numtic
       integer   ipsm
       integer   nr
       integer   nc
       double precision r0max
       double precision r1max
       double precision r2max
       double precision r3max ! S.H. xorshift (2020.2.6)
       double precision r9max
       double precision r9min
       double precision pi
       integer   jol
       integer   jil
       integer   jhc
       integer   jhl
       integer   jer
       integer   jps
       integer   jab
       integer   jht
       integer   jhs
       integer   jwt
       integer   jhm
       integer   jha
       integer   jhy
       integer   jhb
       integer   jhd
       integer   jhp
       integer   jhq
       integer   jhr

       include 'angel01.inc'

!-----------------------------------------------------------------------

       integer   io
       integer   jo

!-----------------------------------------------------------------------

       integer   jsn
       character dsin(0:9)*200
       integer   idsi(0:9)
       integer   ill (0:9)
       integer   ilf (0:9)
       integer   jpn
       character chin*200
       character chlw*200
       character chcm*200
       integer   i1, i2, i3, i4, i5
       integer   iskip
       integer   ierr           ! return code (=0:normal retrun)

       integer   itnmw         ! tally number - 1
       integer   iditnmw        ! for do-loop

       integer   ianatn        ! count of "anatally start", (tally number-1)

!-----------------------------------------------------------------------

       integer   itnm
       integer   ital
       integer   itals
       integer   italm

       common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)

!-----------------------------------------------------------------------

       integer   itfln
       integer   itfll
       character ctfln*100

       common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)

!-----------------------------------------------------------------------

       integer   icntl
       integer   inucr

       common /tcntl/  icntl, inucr

!-----------------------------------------------------------------------

       character m_err*200
       integer   l_err, k_err
       common /error/ m_err, l_err, k_err

!-----------------------------------------------------------------------

       double precision cval
       double precision aval

       common /rval1/ cval(mxcval), aval(mxcval)

!-----------------------------------------------------------------------

       integer, parameter :: icsu = 11
       integer lschn(0:icsu+1), ischn(0:icsu+1)
       character schan(0:icsu+1)*13

       integer i
       integer irtal
       integer j

       data ( schan(i), i = 0, icsu+1 )              /'anatallystart',
     &'manatally    ','nfile        ','sfile        ','sumfactor    ',
     &'angel        ','tallyfolder  ','tallyfile    ','x-txt        ',
     &'y-txt        ','z-tzt        ','ianataldchain','anatallyend  '/

       data ( lschn(i), i = 0, icsu+1 ) /                  13,
     &            9,            5,            5,            9,
     &            5,           11,            9,            5,
     &            5,            5,            7,           11/

       character tname*8
       data      tname /'Anatally'/

       integer   isc            ! input unit number for scrach file
       integer   ipm
       integer   ic
       integer   ic2
       integer   icl
       integer   il
       integer   icf
       integer   ict
       character chlc*200
       double precision cvvv

       integer infile          ! file counter for work
       integer nfilew          ! for work (nfile)
       integer nfiletmp
       character cnfile*3
       integer iorder, jcvf

!-----------------------------------------------------------------------

       integer    inumc, jnumc
       external   inumc, jnumc

!-----------------------------------------------------------------------

       integer isetcvalue ! S.H. 2021.10.5
       integer nfiledum,iorderdum,ioanat ! S.H. 2021.10.5

!-----------------------------------------------------------------------
       ianatn = 0
       if ( icntl==17 ) goto 8 ! not check the anatally subsection in the tally section

       return   ! no anatally sub section


    8  continue
       ierr = 0
       isetcvalue = 0 ! S.H. 2021.10.5

       jsn  = 0
       jpn  = 0
       ilf(jsn) = 10000000

       m_err = ' Error !!'
       ErrCha = ''
       ErrID = 'L:594/R:set_anatal/F:anatally.f'
       l_err = 1
       k_err = 0

       dsin(k_err) = 'Error Line'
       idsi(k_err) = 12
!-----------------------------------------------------------------------
       isc = 152
       endfile(isc)                 !Writes the file end, corresponding to the 'q:' & 'qp:' command
       rewind(isc)

       ischn(0)      = 0            ! count of anatally start
       ischn(icsu+1) = 0            ! count of anatally end

       nfilew        = 0            ! max. number of tally files

    1  continue                     ! next anatally sub-section
       read(isc,end=99) chin        ! anatally start
       call chlngt(chin,200,i1,i2)
       chlw = chin
       call chcaps(chlw,i1,i2,i3,'#!$')
       if( chlw(i1:i1+13) .eq. 'anatally start' ) then ! check just "anatally start", S.H. 2021.1.8
        read(isc) jsn        ! include level
        read(isc) dsin(jsn)  ! input file name
        read(isc) idsi(jsn)  ! length of input file name
        read(isc) ill(jsn)   ! input file lines
        read(isc) ilf(jsn)   ! final line to read
        ischn(0) = ischn(0) + 1
       end if

       do i = 1, icsu
        ischn(i) = 0
       end do

!=======================================================================
!<<<<< pre read (get allocate array size) >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
!=======================================================================

   10  continue

       call anatal_readl(jsn,isc,dsin,idsi,ill,ilf,'#!$',
     &                   jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

       if( ierr .ne. 0 ) goto 9000
       if( chlw(i1:i1+1) .eq. 'q:' ) goto 99
       if( chlw(i1:i1+2) .eq. 'qp:' ) goto 99
       if( jpn  .eq. 3 ) goto 99      ! scratch file end

       if( iskip .ne. 0 ) goto 10

       if( chlw(i1:i1+11) .eq. 'anatally end' ) then ! check just "anatally end", S.H. 2021.1.8
        ischn(icsu+1) = ischn(icsu+1) + 1
        if( ischn(0) == ischn(icsu+1) ) then
         goto 1     ! next anatally sub sction data
        else
         goto 901   ! anatally start/end is not paired
        end if

       else if( chlw .eq. 'incinc' ) then
        read(isc) jsn        ! include level
        read(isc) dsin(jsn)  ! input file name
        read(isc) idsi(jsn)  ! length of input file name
        read(isc) ill(jsn)   ! input file lines
        read(isc) ilf(jsn)   ! final line to read
        goto 10              ! next Line

       else if( chlw .eq. 'incdec' ) then
        read(isc) jsn        ! include level
        read(isc) dsin(jsn)  ! input file name
        read(isc) idsi(jsn)  ! length of input file name
        read(isc) ill(jsn)   ! input file lines
        read(isc) ilf(jsn)   ! final line to read
        goto 10              ! next Line

       else if( chlw(i1:i1+3) .eq. 'set:' ) then
        write(io,'(/" *** Warning : set: definition in"
     &             " anatally subsection is ignored."/)')
        write(io,*) dsin(jsn)(1:idsi(jsn)),ill(jsn),':'

        ErrCha = ''
        MsgID = 'L:674/R:set_anatal/F:anatally.f'
        call ErrWrite(MsgID, ErrCha)
        write(jo,'(/" *** Warning : set: definition in"
     &             " anatally subsection is ignored."/)')
        write(jo,*) dsin(jsn)(1:idsi(jsn)),ill(jsn),':'
        goto 10              ! next Line

       end if

   15  continue
       if( ierr .ne. 0 ) goto 9000
       if( jpn  .eq. 3 ) goto 99      ! scratch file end

!-----------------------------------------------------------------------
!        identify the parameters
!-----------------------------------------------------------------------

       icl = i1
   20  continue
       chlc = chlw
       call chcomp(chlc,icl,i3,i5)
       do i = 1, icsu
        il = icl + lschn(i) - 1
        if( chlc(icl:il) .eq. schan(i)(1:lschn(i)) ) goto 30
       end do

       goto 987

!-----------------------------------------------------------------------
!        read value of parameters
!-----------------------------------------------------------------------

   30  continue

       ipm = i
       ischn( ipm ) = ischn( ipm ) + 1

       ic = inumc(chlw,il+1,i3,'=') + 1
       ic = jnumc(chlw,ic,i3)

       if( ic .gt. i3 ) goto 997

       icl = inumc(chlw,ic,i3,';') - 1

!-----------------------------------------------------------------------
!      manatally
!-----------------------------------------------------------------------

       if( ipm == 1 ) then
        call onum(chlw,ic,icl,cvvv,ierr)
        if( ierr .ne. 0 ) goto 997

        icl = jnumc(chlw,icl+2,i3)
        if( icl .le. i3 ) goto 15

!-----------------------------------------------------------------------
!      nfile, file name and weight rate
!-----------------------------------------------------------------------

       else if( ipm == 2 ) then
        call onum(chlw,ic,icl,cvvv,ierr)
        if( ierr .ne. 0 ) goto 997

        if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

        nfiletmp = nint( cvvv )
        if( nfiletmp <= 0 ) then             ! nfile <= 0
         goto 951
        else if( nfiletmp > nfilew ) then
         nfilew = nfiletmp                   ! Max nfile
        end if

!-----------------------------------------------------------------------
   50   continue
        infile = 0

        ic = i3+1                       ! set the value to read next line

        do i=1, nfiletmp

   52     call anatal_readl(jsn,isc,dsin,idsi,ill,ilf,'#!$',
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
          if( ierr .ne. 0 ) goto 9000
          if( jpn  .eq. 3 ) goto 979
          if( iskip .ne. 0 ) goto 52
          if( chlw .eq. 'incinc' ) then
           read(isc) jsn      ! include level
           read(isc) dsin(jsn)  ! input file name
           read(isc) idsi(jsn)  ! length of input file name
           read(isc) ill(jsn)   ! input file lines
           read(isc) ilf(jsn)   ! final line to read
           goto 52              ! next Line

          else if( chlw .eq. 'incdec' ) then
           read(isc) jsn      ! include level
           read(isc) dsin(jsn)  ! input file name
           read(isc) idsi(jsn)  ! length of input file name
           read(isc) ill(jsn)   ! input file lines
           read(isc) ilf(jsn)   ! final line to read
           goto 52              ! next Line

          else if( chlw(i1:i1+3) .eq. 'set:' ) then
           write(io,'(/" *** Warning : set: definition in"
     &                 " anatally subsection is ignored."/)')
           write(io,*) dsin(jsn)(1:idsi(jsn)),ill(jsn),':'

           ErrCha = ''
           MsgID = 'L:781/R:set_anatal/F:anatally.f'
           call ErrWrite(MsgID, ErrCha)
           write(jo,'(/" *** Warning : set: definition in"
     &                " anatally subsection is ignored."/)')
           write(jo,*) dsin(jsn)(1:idsi(jsn)),ill(jsn),':'
           goto 52              ! next Line

          end if
          ic = i1


        end do

!-----------------------------------------------------------------------
!      sfile
!-----------------------------------------------------------------------

       else if( ipm == 3 ) then
        icf = min( inumc(chlw,ic,icl,' ') - 1, icl )

        icl = jnumc(chlw,icl+2,i3)
        if( icl .le. i3 ) goto 15

!-----------------------------------------------------------------------
!      sumfactor
!-----------------------------------------------------------------------

       else if( ipm == 4 ) then
        call onum(chlw,ic,icl,cvvv,ierr)
        if( ierr .ne. 0 ) goto 997

        icl = jnumc(chlw,icl+2,i3)
        if( icl .le. i3 ) goto 15

!-----------------------------------------------------------------------
!      angel parameter
!-----------------------------------------------------------------------

       else if( ipm == 5 ) then
        ict = min( ic + 199, i2 )

!-----------------------------------------------------------------------
!      tallyfolder
!-----------------------------------------------------------------------

       else if( ipm == 6 ) then
        icf = min( inumc(chlw,ic,icl,' ') - 1, icl )

        icl = jnumc(chlw,icl+2,i3)
        if( icl .le. i3 ) goto 15

!-----------------------------------------------------------------------
!      tallyfile
!-----------------------------------------------------------------------

       else if( ipm == 7 ) then
        icf = min( inumc(chlw,ic,icl,' ') - 1, icl )

        icl = jnumc(chlw,icl+2,i3)
        if( icl .le. i3 ) goto 15

*-----------------------------------------------------------------------
*        x,y,z-txt
*-----------------------------------------------------------------------

       else if( ipm .eq. 8 ) then
          ict = min( ic + 199, i2 )

       else if( ipm .eq. 9 ) then
          ict = min( ic + 199, i2 )

       else if( ipm .eq. 10 ) then
          ict = min( ic + 199, i2 )

*-----------------------------------------------------------------------
*        ianataldchain
*-----------------------------------------------------------------------

       else if( ipm == 11 ) then
        icf = min( inumc(chlw,ic,icl,' ') - 1, icl )

        icl = jnumc(chlw,icl+2,i3)
        if( icl .le. i3 ) goto 15

*-----------------------------------------------------------------------

       else
       end if

       go to 10   ! read next line

!=======================================================================

!>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
!    allocate and initilized variable arrays
!>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>

   99  continue
       if ( icntl /= 17 ) return   ! Not anatally calculation
       if( ischn(0) /= ischn(icsu+1) ) then
        goto 901   ! anatally start/end is not paired
       end if

       rewind(isc)

       ianatn = 0

       if( nfilew > 0 ) then
        allocate (  tallyfname(nfilew,itlmax) )
        allocate ( ltallyfname(nfilew,itlmax) )
        allocate (  weightRate(nfilew,itlmax) )
       else
        goto 951
       end if

         tallyfname(1:nfilew,1:itlmax) = ' '
        ltallyfname(1:nfilew,1:itlmax) = 0
         weightRate(1:nfilew,1:itlmax) = 0.0d0

       ischn(0)      = 0
       ischn(icsu+1) = 0

       do i = 1, itnm
          ital(i) = 0           ! reset ital
          nanatalRead(i) = 0    ! reset nanatalRead
       end do
       itnmw = -1

   98  continue                      ! next anatally sub-section
       read(isc,end=800) chin        ! anatally start
       call chlngt(chin,200,i1,i2)
       chlw = chin
       call chcaps(chlw,i1,i2,i3,'#!$')
       if( chlw(i1:i1+13) .eq. 'anatally start' ) then ! check just "anatally start", S.H. 2021.1.8
        read(isc) jsn        ! include level
        read(isc) dsin(jsn)  ! input file name
        read(isc) idsi(jsn)  ! length of input file name
        read(isc) ill(jsn)   ! input file lines
        read(isc) ilf(jsn)   ! final line to read
        ischn(0) = ischn(0) + 1
        itnmw = itnmw + 1    ! anatally number - 1
        nanatalRead(itnmw+1) = 1

       end if

       do i = 1, icsu
        ischn(i) = 0
       end do

!=======================================================================
!<<<<< Production read >>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>>
!=======================================================================
!      set default or initial value
!-----------------------------------------------------------------------

       manatally  (itnmw+1) = 1       ! default value
       ianataldchain(itnmw+1) = 0
        tallyfolder(itnmw+1) = ' '
       ltallyfolder(itnmw+1) = 0
        tallyfile (itnmw+1) = ' '
       ltallyfile (itnmw+1) = 0
        nfile     (itnmw+1) = 0
        sumWR     (itnmw+1) = 0.0d0
        sfile     (itnmw+1) = ' '
       lsfile     (itnmw+1) = 0
       sumfactor  (itnmw+1) = 1.0d0   ! default value
        sumang    (itnmw+1) = ' '
       lsumang    (itnmw+1) = 0

       sumWR      (itnmw+1) = 0.0d0   ! Sum of the weight rates

        cx_txt    (itnmw+1) = ' '
       lcx_txt    (itnmw+1) = 0
        cy_txt    (itnmw+1) = ' '
       lcy_txt    (itnmw+1) = 0
        cz_txt    (itnmw+1) = ' '
       lcz_txt    (itnmw+1) = 0

!-----------------------------------------------------------------------
  100  continue

       call anatal_readl(jsn,isc,dsin,idsi,ill,ilf,'#!$',
     &                   jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
       if( ierr .ne. 0 ) goto 9000
       if( chlw(i1:i1+1) .eq. 'q:' ) goto 800
       if( chlw(i1:i1+2) .eq. 'qp:' ) goto 800
       if( jpn  .eq. 3 ) goto 800              ! go to parameters check

       if( iskip .ne. 0 ) goto 100

       if( chlw(i1:i3-5) .eq. 'anatally end' ) then ! "anatally end  nnn"
        ischn(icsu+1) = ischn(icsu+1) + 1
        if( ischn(0) == ischn(icsu+1) ) then
         goto 98    ! next anatally sub sction data
        else
         goto 901   ! anatally start/end is not paired
        end if

       else if( chlw .eq. 'incinc' ) then
        read(isc) jsn        ! include level
        read(isc) dsin(jsn)  ! input file name
        read(isc) idsi(jsn)  ! length of input file name
        read(isc) ill(jsn)   ! input file lines
        read(isc) ilf(jsn)   ! final line to read
        goto 100             ! next Line

       else if( chlw .eq. 'incdec' ) then
        read(isc) jsn        ! include level
        read(isc) dsin(jsn)  ! input file name
        read(isc) idsi(jsn)  ! length of input file name
        read(isc) ill(jsn)   ! input file lines
        read(isc) ilf(jsn)   ! final line to read
        goto 100             ! next Line
       else if( chlw(i1:i1+3) .eq. 'set:' ) then
        goto 100             ! next Line

       end if

  150  continue
       if( ierr .ne. 0 ) goto 9000
       if( jpn  .eq. 3 ) goto 800              ! go to parameters check

!-----------------------------------------------------------------------
!        identify the parameters
!-----------------------------------------------------------------------

       icl = i1
  200  continue
       chlc = chlw
       call chcomp(chlc,icl,i3,i5)
       do i = 1, icsu
        il = icl + lschn(i) - 1
        if( chlc(icl:il) .eq. schan(i)(1:lschn(i)) ) goto 300
       end do

       goto 987

!-----------------------------------------------------------------------
!        read value of parameters
!-----------------------------------------------------------------------

  300  continue

       ipm = i
       ischn( ipm ) = ischn( ipm ) + 1

       ic = inumc(chlw,il+1,i3,'=') + 1
       ic = jnumc(chlw,ic,i3)

       if( ic .gt. i3 ) goto 997

       icl = inumc(chlw,ic,i3,';') - 1

!-----------------------------------------------------------------------
!      manatally
!-----------------------------------------------------------------------

       if( ipm == 1 ) then
        call onum(chlw,ic,icl,cvvv,ierr)
        if( ierr .ne. 0 ) goto 997
        manatally(itnmw+1) = nint( cvvv )
        if(manatally(itnmw+1) < 0 .or. manatally(itnmw+1) > 2) goto 931

        if ( manatally(itnmw+1) .eq. 2 ) isetcvalue= 1 ! S.H. 2021.10.5

        icl = jnumc(chlw,icl+2,i3)
        if( icl .le. i3 ) goto 150

!-----------------------------------------------------------------------
!      nfile, file name and weight rate
!-----------------------------------------------------------------------

       else if( ipm == 2 ) then
        call onum(chlw,ic,icl,cvvv,ierr)
        if( ierr .ne. 0 ) goto 997

        if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

        nfile(itnmw+1) = nint( cvvv )
        if( nfile(itnmw+1) <= 0 .or. nfile(itnmw+1) > nfilew ) goto 952

!-----------------------------------------------------------------------
  500   continue
        infile = 0

        ic = i3+1                       ! set the value to read next line

        do i=1, nfile(itnmw+1)

  520     call anatal_readl(jsn,isc,dsin,idsi,ill,ilf,'#!$',
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
          if( ierr .ne. 0 ) goto 9000
          if( jpn  .eq. 3 ) goto 979
          if( iskip .ne. 0 ) goto 520
          if( chlw .eq. 'incinc' ) then
           read(isc) jsn      ! include level
           read(isc) dsin(jsn) ! input file name
           read(isc) idsi(jsn)  ! length of input file name
           read(isc) ill(jsn)   ! input file lines
           read(isc) ilf(jsn)   ! final line to read
           goto 520             ! next Line

          else if( chlw .eq. 'incdec' ) then
           read(isc) jsn      ! include level
           read(isc) dsin(jsn)  ! input file name
           read(isc) idsi(jsn)  ! length of input file name
           read(isc) ill(jsn)   ! input file lines
           read(isc) ilf(jsn)   ! final line to read
           goto 520             ! next Line
          else if( chlw(i1:i1+3) .eq. 'set:' ) then
           goto 520             ! next Line
          end if
          ic = i1

         ic = jnumc(chlw,ic,i3)                           ! file name start col
         icf = min( inumc(chlw,ic,i3,' ') - 1, i3 )
         infile = infile + 1
         ltallyfname(infile,itnmw+1) = icf - ic + 1             ! character length
         tallyfname (infile,itnmw+1)(1:icf-ic+1) = chin(ic:icf) ! tally file name(s)
         if ( ltallyfname(infile,itnmw+1) < 1 ) goto 957

!.......................................................................
!     Rename (input) restart file name
!.......................................................................

        if ( ianataldchain(itnmw+1) .eq. 1 ) then

         ! for [T-Yield] tally
         if ( ital(itnmw+1) ==  3 .and.
     &        ital(itnmw+3) == 16 ) then        ! t-yield, t-dchain
          j = index(tallyfname(infile,itnmw+1), ".", back=.true.)
          if ( j /= 0 ) then
           j = j - 1
          else
           j = ltallyfname(infile,itnmw+1)
          end if
           tallyfname(infile,itnmw+1) =
     &     tallyfname(infile,itnmw+1)(1:j) // '.dyld'
          ltallyfname(infile,itnmw+1) = j + 5

         ! for [T-Track] tally
         else if ( ital(itnmw+1) ==  1 .and.
     &             ital(itnmw+2) == 16 ) then   ! t-track, t-dchain
          j = index(tallyfname(infile,itnmw+1), ".", back=.true.)
          if ( j /= 0 ) then
           j = j - 1
          else
           j = ltallyfname(infile,itnmw+1)
          end if
           tallyfname(infile,itnmw+1) =
     &     tallyfname(infile,itnmw+1)(1:j) // '.dtrk'
          ltallyfname(infile,itnmw+1) = j + 5

         ! for [T-Track] tally
         else if ( ital(itnmw+1) == 16 ) then   ! t-dchain
          j = index(tallyfname(infile,itnmw+1), ".", back=.true.)
          if ( j /= 0 ) then
           j = j - 1
          else
           j = ltallyfname(infile,itnmw+1)
          end if
           tallyfname(infile,itnmw+1) =
     &     tallyfname(infile,itnmw+1)(1:j) // '.dout'
          ltallyfname(infile,itnmw+1) = j + 5

         end if

        end if

        end do

!-----------------------------------------------------------------------
!      sfile
!-----------------------------------------------------------------------

       else if( ipm == 3 ) then
        icf = min( inumc(chlw,ic,icl,' ') - 1, icl )
        lsfile(itnmw+1)             = icf - ic + 1
         sfile(itnmw+1)(1:icf-ic+1) = chin(ic:icf)
        if ( lsfile(itnmw+1) < 1 ) goto 958

        if ( itnmw+1 .gt. 1 ) then
         do iditnmw = 0, itnmw-1
          if ( sfile(itnmw+1)(1:lsfile(itnmw+1))
     &           .eq. sfile(iditnmw+1)(1:lsfile(iditnmw+1)) ) goto 960
         end do
        end if

!.......................................................................
!     Rename (output) restart file name
!.......................................................................

       if ( ianataldchain(itnmw+1) .eq. 1 ) then

        ! for [T-Yield] tally
        if ( ital(itnmw+1) ==  3 .and.
     &       ital(itnmw+3) == 16 ) then        ! t-yield, t-dchain
         j = index(sfile(itnmw+1), ".", back=.true.)
         if ( j /= 0 ) then
          j = j - 1
         else
          j = lsfile(itnmw+1)
         end if
          sfile(itnmw+1) = sfile(itnmw+1)(1:j) // '.dyld'
         lsfile(itnmw+1) = j + 5

        ! for [T-Track] tally
        else if ( ital(itnmw+1) ==  1 .and.
     &            ital(itnmw+2) == 16 ) then   ! t-track, t-dchain
         j = index(sfile(itnmw+1), ".", back=.true.)
         if ( j /= 0 ) then
          j = j - 1
         else
          j = lsfile(itnmw+1)
         end if
          sfile(itnmw+1) = sfile(itnmw+1)(1:j) // '.dtrk'
         lsfile(itnmw+1) = j + 5

        end if

       end if

        icl = jnumc(chlw,icl+2,i3)
        if( icl .le. i3 ) goto 150

!-----------------------------------------------------------------------
!      sumfactor
!-----------------------------------------------------------------------

       else if( ipm == 4 ) then
        call onum(chlw,ic,icl,cvvv,ierr)
        if( ierr .ne. 0 ) goto 997
        sumfactor(itnmw+1) = cvvv
        if ( sumfactor(itnmw+1) <= 0.0d0 ) goto 956

        icl = jnumc(chlw,icl+2,i3)
        if( icl .le. i3 ) goto 150

!-----------------------------------------------------------------------
!      angel parameter
!-----------------------------------------------------------------------

       else if( ipm == 5 ) then
        ict = min( ic + 199, i2 )
         sumang(itnmw+1)(1:ict-ic+1) = chin(ic:ict)
        lsumang(itnmw+1) = ict - ic + 1
        if ( lsumang(itnmw+1) < 1 ) goto 959

!-----------------------------------------------------------------------
!      tallyfolder
!-----------------------------------------------------------------------

       else if( ipm == 6 ) then
        icf = min( inumc(chlw,ic,icl,' ') - 1, icl )
        ltallyfolder(itnmw+1)             = icf - ic + 1
         tallyfolder(itnmw+1)(1:icf-ic+1) = chin(ic:icf)
        if ( ltallyfolder(itnmw+1) < 1 ) goto 958

        if ( itnmw+1 .gt. 1 ) then
         do iditnmw = 0, itnmw-1
          if ( tallyfolder(itnmw+1)(1:ltallyfolder(itnmw+1))
     & .eq. tallyfolder(iditnmw+1)(1:ltallyfolder(iditnmw+1)) ) goto 960
         end do
        end if

!-----------------------------------------------------------------------
!      tallyfile
!-----------------------------------------------------------------------

       else if( ipm == 7 ) then
        icf = min( inumc(chlw,ic,icl,' ') - 1, icl )
        ltallyfile(itnmw+1)             = icf - ic + 1
         tallyfile(itnmw+1)(1:icf-ic+1) = chin(ic:icf)
        if ( ltallyfile(itnmw+1) < 1 ) goto 958

        if ( itnmw+1 .gt. 1 ) then
         do iditnmw = 0, itnmw-1
          if ( tallyfile(itnmw+1)(1:ltallyfile(itnmw+1))
     &     .eq. tallyfile(iditnmw+1)(1:ltallyfile(iditnmw+1)) ) goto 960
         end do
        end if

*-----------------------------------------------------------------------
*        x-txt
*-----------------------------------------------------------------------

       else if( ipm .eq. 8 ) then
        ict = min( ic + 199, i2 )
         cx_txt(itnmw+1)(1:ict-ic+1) = chin(ic:ict)
        lcx_txt(itnmw+1) = ict - ic + 1
        if ( lcx_txt(itnmw+1) < 1 ) goto 961

*-----------------------------------------------------------------------
*        y-txt
*-----------------------------------------------------------------------

       else if( ipm .eq. 9 ) then
        ict = min( ic + 199, i2 )
         cy_txt(itnmw+1)(1:ict-ic+1) = chin(ic:ict)
        lcy_txt(itnmw+1) = ict - ic + 1
        if ( lcy_txt(itnmw+1) < 1 ) goto 962

*-----------------------------------------------------------------------
*        z-txt
*-----------------------------------------------------------------------

       else if( ipm .eq. 10 ) then
        ict = min( ic + 199, i2 )
         cz_txt(itnmw+1)(1:ict-ic+1) = chin(ic:ict)
        lcz_txt(itnmw+1) = ict - ic + 1
        if ( lcz_txt(itnmw+1) < 1 ) goto 963


*-----------------------------------------------------------------------
*        ianataldchain
*-----------------------------------------------------------------------

       else if( ipm == 11 ) then
        call onum(chlw,ic,icl,cvvv,ierr)
        if( ierr .ne. 0 ) goto 997
        ianataldchain(itnmw+1) = nint( cvvv )

        icl = jnumc(chlw,icl+2,i3)
        if( icl .le. i3 ) goto 150

*-----------------------------------------------------------------------

        if ( ital(itnmw+1).eq.0 .and. ital(itnmw+2).eq.0
     &       .and. ital(itnmw+3).eq.0 ) then
           ital(itnmw+1) = 3
           ital(itnmw+2) = 1
           ital(itnmw+3) = 16
        end if

*-----------------------------------------------------------------------

       else
       end if

       go to 100   ! read next line

!-----------------------------------------------------------------------
!     check
!-----------------------------------------------------------------------

  800  continue
       if( ischn(0) /= ischn(icsu+1) ) then
        goto 901   ! anatally start/end is not paired
       end if

!-----------------------------------------------------------------------


!-----------------------------------------------------------------------

!-----------------------------------------------------------------------
! single anatally (Turn off the following if block, if multiple tally version)

c to use anatally option without input of manatally (D=1)
!-----------------------------------------------------------------------
       if ( icntl==17 ) itnm = itnmw+1 ! change tallys count (icntl=17 mode)

       do irtal=1, itnm

        if ( itfln(irtal).gt.0 ) then
c to use anatally option in the case a usual tally name is defined.

        else
         if ( icntl.ne.17 ) then
          m_err = 'File is not defined in this tally '
          ErrCha = ''
          ErrID = 'L:1352/R:set_anatal/F:anatally.f'
          goto 999
         end if

        end if

        if( nanatalRead(irtal) > 0 ) then   ! used anatally function

         ! input tally files
         if( nfile(irtal) <= 0 ) then
          write(m_err,'(a,i3,a)')
     &     'Number of nfiles is little equal 0 in ',irtal,
     &     ' th tally section.'
          ErrCha = ''
          ErrID = 'L:1366/R:set_anatal/F:anatally.f'
          goto 999
         end if

         ! When using the weighted average
         if ( manatally(irtal) == 2 ) then
          ! Sum of the weight rates
          sumWR(irtal) = 0.0d0
          do i = 1, nfile(irtal)
            sumWR(irtal) = sumWR(irtal) + weightRate(i,irtal)
          end do
         end if

         ! output tally file name
         if( lsfile(irtal) < 1 ) then
          write(m_err,'(a,i3,a)')
     &     'anatally output file name is undefined. ',irtal,
     &     ' th tally section'
          ErrCha = ''
          ErrID = 'L:1385/R:set_anatal/F:anatally.f'
          goto 999
         end if

        end if

       end do

!-----------------------------------------------------------------------

       if ( isetcvalue .eq. 1 ) ! S.H. 2021.10.5
     &      call make_varfile(nfiledum,iorder,ierr,ioanat)

!-----------------------------------------------------------------------

 9000  continue
       close(isc)
       return

!-----------------------------------------------------------------------
!     errors
!-----------------------------------------------------------------------

  901  m_err = 'anatally start/end is not paired in '//tname
       ErrCha = ''
       ErrID = 'L:1410/R:set_anatal/F:anatally.f'
       goto 999

  921  m_err = 'anatally subsection ID is not found in '//tname
       ErrCha = ''
       ErrID = 'L:1415/R:set_anatal/F:anatally.f'
       goto 999

  931  m_err = 'manatally can only be set to 0, 1, or 2 in '//tname
       ErrCha = ''
       ErrID = 'L:1420/R:set_anatal/F:anatally.f'
       goto 999

  951  m_err = 'Number of nfiles is little equal 0 in '//tname
       ErrCha = ''
       ErrID = 'L:1425/R:set_anatal/F:anatally.f'
       goto 999

  952  m_err = 'nfiles is inconsistent in '//tname
       ErrCha = ''
       ErrID = 'L:1430/R:set_anatal/F:anatally.f'
       goto 999

  955  m_err = 'weightRate is inconsistent in '//tname
       ErrCha = ''
       ErrID = 'L:1435/R:set_anatal/F:anatally.f'
       goto 999

  956  m_err = 'Sumfactor is inconsistent in  '//tname
       ErrCha = ''
       ErrID = 'L:1440/R:set_anatal/F:anatally.f'
       goto 999

  957  m_err = 'Inappropriate tally file name in '//tname
       ErrCha = ''
       ErrID = 'L:1445/R:set_anatal/F:anatally.f'
       goto 999

  958  m_err = 'Inappropriate sfile name in '//tname
       ErrCha = ''
       ErrID = 'L:1450/R:set_anatal/F:anatally.f'
       goto 999

  960  m_err = 'the same sfile name is used in '//tname
       ErrCha = ''
       ErrID = 'L:1455/R:set_anatal/F:anatally.f'
       goto 999

  959  m_err = 'Inappropriate ANGEL parameter in '//tname
       ErrCha = ''
       ErrID = 'L:1460/R:set_anatal/F:anatally.f'
       goto 999

 961   m_err = 'Description of x-txt is wrong in '//tname
       ErrCha = ''
       ErrID = 'L:1465/R:set_anatal/F:anatally.f'
       goto 999

 962   m_err = 'Description of y-txt is wrong in '//tname
       ErrCha = ''
       ErrID = 'L:1470/R:set_anatal/F:anatally.f'
       goto 999

 963   m_err = 'Description of z-txt is wrong in '//tname
       ErrCha = ''
       ErrID = 'L:1475/R:set_anatal/F:anatally.f'
       goto 999

  979  m_err = 'Description of parameter is wrong in '//tname
       ErrCha = ''
       ErrID = 'L:1480/R:set_anatal/F:anatally.f'
       goto 999

  987  m_err = 'Unknown parameter is found in '//tname
       ErrCha = ''
       ErrID = 'L:1485/R:set_anatal/F:anatally.f'
       goto 999

  989  m_err = 'Double definition of the parameter is found in '//tname
       ErrCha = ''
       ErrID = 'L:1490/R:set_anatal/F:anatally.f'
       goto 999

  993  m_err = 'In this line, [ ; ] cannot be used.'
       ErrCha = ''
       ErrID = 'L:1495/R:set_anatal/F:anatally.f'
       goto 999

  994  m_err = 'In this line, continuation line format cannot used.'
       ErrCha = ''
       ErrID = 'L:1500/R:set_anatal/F:anatally.f'
       goto 999

  997  m_err = 'Description of parameter is wrong in '//tname
       ErrCha = ''
       ErrID = 'L:1505/R:set_anatal/F:anatally.f'
       goto 999

!-----------------------------------------------------------------------

  999  continue
       l_err = ill(jsn)
       k_err = jsn
       ierr  = 1

*-----------------------------------------------------------------------

 9999  continue
       close(isc)

       ErrCha = ''
       MsgID = 'L:1521/R:set_anatal/F:anatally.f'
       call ErrWrite(MsgID, ErrCha)
       write(jo,'(/" ***** Error in Anatally Subsection *****"/)')
       write(jo,*) dsin(k_err)(1:idsi(k_err)),l_err,':'
       write(io,'(/" ***** Error in Anatally Subsection *****"/)')
       write(io,*) dsin(k_err)(1:idsi(k_err)),l_err,':'

       icf = 200

       do 910 i = 200, 1, -1

        if( m_err(i:i) .ne. ' ' ) goto 911

 910   continue

 911   icf = i

       call ErrWrite(ErrID, ErrCha)
       write(jo,'(" error = ",200A1/)') ( m_err(i:i), i=1,icf )
       write(io,'(" error = ",200A1/)') ( m_err(i:i), i=1,icf )

       return

      end subroutine set_anatal


!***********************************************************************
!                                                                      *
      subroutine anatal_set_tal(io,jo,ivers,ierr)
!                                                                      *
!     read tally information from tally file.                          *
!     called : main                                                    *
!     calls  : anatal_ttrack, anatal_tdeposit,                         *
!              anatal_tpoint, anatal_tsed,     anatal_tlet             *
!              anatal_tcross, anatal_tyield,                           *
!              anatal_tstar,  anatal_ttime,    anatal_tdpa             *
!              anatal_tprodct,anatal_tprodct                           *
!     modified by  T.Miura on 2022/05/31                               *
!                                                                      *
!***********************************************************************

      use anatallymod
      use sumtallymod
      use partmod ! frtati 2021/10/05
      use moddas_mesh
      use moddas_region
      use TDCHAINMOD, only: itdc,talldcinit !FURUTA20200522

!-----------------------------------------------------------------------

      implicit real*8 (a-h,o-z)

      include 'param.inc'
      include 'param01.inc' ! frtati 2021/10/05
      include 'err.inc'

*-----------------------------------------------------------------------

      common /paraj/  mstz(300), parz(300)
      common /stat / istdev, irestart, ireschk ! S.H. 2023.4.3

*-----------------------------------------------------------------------

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)
      common /tall02/ itrgn(itlmax), itrgm(itlmax), itreg(itlmax)
      common /tall25/ itrnv(itlmax), itriv(itlmax), itrrv(itlmax)

!     t-cross tally bin
      common /tall13/ itrcn(itlmax), itrcr(itlmax), itrca(itlmax)
      common /tall26/ itrcs(itlmax), itrcc(itlmax), itrss(itlmax)

!     r-type
      common /tall03/ itrty(itlmax), itrnm(itlmax), itrrg(itlmax),
     &                rtrmi(itlmax), rtrma(itlmax), rtrdl(itlmax)
!     x-type
      common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &                rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)
!     y-type
      common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &                rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)
!     z-type
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)
!     e-type
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)

!     r/z-type
      common /tall08/ rtrx0(itlmax), rtry0(itlmax)

      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall19/ itsmn(itlmax), itstm(itlmax)
!     t-type
      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                rttmi(itlmax), rttma(itlmax), rttdl(itlmax)

!     a-type
      common /tall23/ itaty(itlmax), itanm(itlmax), itarg(itlmax),
     &                rtami(itlmax), rtama(itlmax), rtadl(itlmax)

      common /tall59/ irfll(itlmax), crfln(itlmax), itrff(itlmax)
      character crfln*100
      character irfile*100

      common /tall62/ itpon(itlmax), rtpon(itlmax,20,4)

c$$$      dimension idas(1)
      dimension idas(mdas*2) !2025.2.26 S.H. temporary for fbounds-check
      equivalence ( das, idas )

*-----------------------------------------------------------------------

      common /res03/ lextrf(itlmax)
      logical lextrf

      character csumfile*200
      integer isjsn, isidsi

*-----------------------------------------------------------------------
      character m_err*200
      common /error/ m_err, l_err, k_err
*-----------------------------------------------------------------------
      character chin*200, chlw*200, chcm*200

      character dsin(0:9)*200
      dimension idsi(0:9)
      dimension ill (0:9), ilf(0:9)

*-----------------------------------------------------------------------

      integer   ntf   ! Number of tallyfname (tally file name)

      dimension stpon(20,4)

*-----------------------------------------------------------------------
      ianatn = itnm   ! Number of <anatally start/end> pairs

      do m=1, ianatn
         if( nanatalRead(m) > 0 ) goto 8   ! check anatally sub section
      end do
      return   ! no anatally sub section

    8 continue


      do m = 1, ianatn   ! tally section(s)

         if( nanatalRead(m) .lt. 1 ) cycle   ! check anatally sub section

*-----------------------------------------------------------------------

         lextrf(:)    = .false.

         inoprm = 0

*-----------------------------------------------------------------------
* read each restart files
*-----------------------------------------------------------------------

         jsn     = 0
         jsi     = 32
         idsi(:) = 0
         ill(:)  = 1
         ilf(:)  = 10000000

         ierr = 0

         irtmsh = 0   ! mesh type at first tally file
         ietp   = 0   ! e-type at first tally file
         edel   = 0.0
         emin   = 0.0
         emax   = 0.0
         ietp2  = 0
         ittp   = 0   ! t-type at first tally file
         iatp   = 0   ! a-type at first tally file
         adel   = 0.0
         amin   = 0.0
         amax   = 0.0

*-----------------------------------------------------------------------
* check the tally is restartable
*-----------------------------------------------------------------------


*-----------------------------------------------------------------------
* read restart prameters in read resfile
*-----------------------------------------------------------------------
         if ( irfll(m) .eq. 0 ) then
            irfll(m) = itfll(m,1)
            crfln(m)(1:) = ctfln(m,1)(1:itfll(m,1))
         end if

!-----------------------------------------------------------------------

         itnm = m - 1        ! reset tally address

         do ntf = 1, nfile(m)   ! tally file(s)

            idsi(jsn) = ltallyfname(ntf,m)

            dsin(jsn)(1:idsi(jsn)) = tallyfname(ntf,m)(1:idsi(jsn))

            isidsi = idsi(jsn)
            csumfile(1:isidsi) = dsin(jsn)(1:idsi(jsn))

            open(jsi,
     &         file=dsin(jsn)(1:idsi(jsn)), status='old', action='read',
     &         form='formatted', iostat=ierr)

            if( ierr .ne. 0 ) then
               goto 100
            end if

************************************************************************
*                                                                      *
*     start of read header from tally file                             *
*                                                                      *
************************************************************************
            jpn  = 0
*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140       continue

            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

            if( ierr .ne. 0 ) goto 999
            if( jpn .eq. 3 ) then
               inoprm = inoprm + 1   ! no restart parameter
               close(jsi)
               goto 100
            end if
            if( iskip .ne. 0 ) goto 140

  240       continue

*-----------------------------------------------------------------------
*        [t-track]
*-----------------------------------------------------------------------

            if( chcm(i1:i1+ 8) .eq. '[t-track]' ) then

               if( chcm(i1+9:i1+11) .eq. 'off' ) then

                  jpn = 2
                  goto 140

               end if

               call anatal_ttrack(jsn,jsi,dsin,idsi,ill,ilf,
     &                            jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)

               if( ierr .ne. 0 ) goto 999
               ital(itnm) = 1

*-----------------------------------------------------------------------
*        [t-deposit]
*-----------------------------------------------------------------------

            else if( chcm(i1:i1+ 10) .eq. '[t-deposit]' ) then

               if( chcm(i1+11:i1+13) .eq. 'off' ) then

                  jpn = 2
                  goto 140

               end if

               call anatal_tdeposit(jsn,jsi,dsin,idsi,ill,ilf,
     &                              jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)

               if( ierr .ne. 0 ) goto 999
               ital(itnm) = 13

*-----------------------------------------------------------------------
*        [t-point]
*-----------------------------------------------------------------------

            else if( chcm(i1:i1+ 8) .eq. '[t-point]' ) then

               if( chcm(i1+9:i1+11) .eq. 'off' ) then

                  jpn = 2
                  goto 140

               end if

               call anatal_tpoint(jsn,jsi,dsin,idsi,ill,ilf,
     &                            jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)

               if( ierr .ne. 0 ) goto 999
               ital(itnm) = 17

*-----------------------------------------------------------------------
*        [t-sed]
*-----------------------------------------------------------------------

            else if( chcm(i1:i1+ 6) .eq. '[t-sed]' ) then

               if( chcm(i1+7:i1+9) .eq. 'off' ) then

                  jpn = 2
                  goto 140

               end if

               call anatal_tsed(jsn,jsi,dsin,idsi,ill,ilf,
     &                          jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)

               if( ierr .ne. 0 ) goto 999
               ital(itnm) = 15

*-----------------------------------------------------------------------
*        [t-let]
*-----------------------------------------------------------------------

            else if( chcm(i1:i1+ 6) .eq. '[t-let]' ) then

               if( chcm(i1+7:i1+9) .eq. 'off' ) then

                  jpn = 2
                  goto 140

               end if

               call anatal_tlet(jsn,jsi,dsin,idsi,ill,ilf,
     &                          jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)

               if( ierr .ne. 0 ) goto 999
               ital(itnm) = 12

*-----------------------------------------------------------------------
*        [t-cross]
*-----------------------------------------------------------------------

            else if( chcm(i1:i1+ 8) .eq. '[t-cross]' ) then

               if( chcm(i1+9:i1+11) .eq. 'off' ) then

                  jpn = 2
                  goto 140

               end if

               call anatal_tcross(jsn,jsi,dsin,idsi,ill,ilf,
     &                            jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)

               if( ierr .ne. 0 ) goto 999
               ital(itnm) = 2

*-----------------------------------------------------------------------
*        [t-yield]
*-----------------------------------------------------------------------

            else if( chcm(i1:i1+ 8) .eq. '[t-yield]' ) then

               if( chcm(i1+9:i1+11) .eq. 'off' ) then

                  jpn = 2
                  goto 140

               end if

               call anatal_tyield(jsn,jsi,dsin,idsi,ill,ilf,
     &                            jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)

               if( ierr .ne. 0 ) goto 999
               ital(itnm) = 3

*-----------------------------------------------------------------------
*        [t-star]
*-----------------------------------------------------------------------

            else if( chcm(i1:i1+ 7) .eq. '[t-star]' ) then

               if( chcm(i1+8:i1+10) .eq. 'off' ) then

                  jpn = 2
                  goto 140

               end if

               itnam=1  ! T.Sato 2018/2/15, [t-star] or [t-interact]

               call anatal_tstar(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,itnam,ierr)

               if( ierr .ne. 0 ) goto 999
               ital(itnm) = 5

*-----------------------------------------------------------------------
*        [t-interact] ! Equivalent to [t-star], T.Sato 2018/2/15
*-----------------------------------------------------------------------

            else if( chcm(i1:i1+11) .eq. '[t-interact]' ) then

               if( chcm(i1+12:i1+14) .eq. 'off' ) then

                  jpn = 2
                  goto 140

               end if

               itnam=2  ! T.Sato 2018/2/15, [t-star] or [t-interact]

               call anatal_tstar(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,itnam,ierr)

               if( ierr .ne. 0 ) goto 999
               ital(itnm) = 5

*-----------------------------------------------------------------------
*        [t-time]
*-----------------------------------------------------------------------

            else if( chcm(i1:i1+ 7) .eq. '[t-time]' ) then

               if( chcm(i1+8:i1+10) .eq. 'off' ) then

                  jpn = 2
                  goto 140

               end if

               call anatal_ttime(jsn,jsi,dsin,idsi,ill,ilf,
     &                           jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)

               if( ierr .ne. 0 ) goto 999
               ital(itnm) = 6

*-----------------------------------------------------------------------
*        [t-dpa]
*-----------------------------------------------------------------------

            else if( chcm(i1:i1+ 6) .eq. '[t-dpa]' ) then

               if( chcm(i1+7:i1+9) .eq. 'off' ) then

                  jpn = 2
                  goto 140

               end if

               call anatal_tdpa(jsn,jsi,dsin,idsi,ill,ilf,
     &                          jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)

               if( ierr .ne. 0 ) goto 999
               ital(itnm) = 7

*-----------------------------------------------------------------------
*        [t-product]
*-----------------------------------------------------------------------

            else if( chcm(i1:i1+ 10) .eq. '[t-product]' ) then

               if( chcm(i1+11:i1+13) .eq. 'off' ) then

                  jpn = 2
                  goto 140

               end if

               call anatal_tprodct(jsn,jsi,dsin,idsi,ill,ilf,
     &                             jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)

               if( ierr .ne. 0 ) goto 999
               ital(itnm) = 8

*-----------------------------------------------------------------------
*        [t-dchain]
*-----------------------------------------------------------------------

            else if( chcm(i1:i1+ 9) .eq. '[t-dchain]' ) then

               if( chcm(i1+10:i1+12) .eq. 'off' ) then

                  jpn = 2
                  goto 140

               end if


               if(itdc.eq.0) then
                call talldcinit(itlmax) !FURUTA20200522
                if(mstz(35).ne.1) then
                 write(ErrCha,'("Warning: jmout is set to 1 ",
     &           "because [t-dchain] is defined")')
                 ErrID = 'L:2014/R:anatal_set_tal/F:anatally.f'
                 call ErrWrite(ErrID,ErrCha)
                 mstz(35)=1 ! jmout should be 1 when [t-dchain] is defined
                endif
               endif

               call anatal_tdchain(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)

                  if( ierr .ne. 0 ) goto 999
               ital(itnm) = 16

*-----------------------------------------------------------------------
*        else
*-----------------------------------------------------------------------

            else

               if( i1 .le. 5 .and. chlw(i1:i1) .eq. '[' ) goto 997

                  goto 140

            end if

*-----------------------------------------------------------------------

            close(jsi)

            if( jpn .eq.3 ) then
               inoprm = inoprm + 1   ! no restart parameter
               goto 100
            else if( ierr .eq. 0 ) then
              lextrf(m) = .true.
            else
              inoprm = inoprm + 1
            end if

*-----------------------------------------------------------------------
* check mesh & bin prameters in read resfile
*-----------------------------------------------------------------------

c$$$            if ( ireschk .eq. 1 ) return ! S.H. 2023.4.3
            if ( ireschk .eq. 1 ) exit

            ! saving mesh & bin info. ( ntf = 1 )
            if( ntf .eq. 1 ) then
               italnm = ital(itnm)         ! tally number
               irtmsh = itmsh(itnm)

               if(italnm.eq.17) then       ! t-point tally
                  itpnt = itpon(itnm)      ! 1:point 2:ring
                  do i=1, irtmsh
                     stpon(i,1) = rtpon(itnm,i,1)
                     stpon(i,2) = rtpon(itnm,i,2)
                     stpon(i,3) = rtpon(itnm,i,3)
                     stpon(i,4) = rtpon(itnm,i,4)
                  end do

               else if(italnm.eq.2 .and.
     &                 irtmsh.eq.1) then   ! t-cross tally(reg mesh)
                  ntcn = itrcn(itnm)       ! count of regions
                  ntcr = itrcr(itnm)       ! idas base address
                  mtcr = itrcs(itnm)       ! count of idas vars
                  ktcr = itrca(itnm)       ! das base address

               else if(irtmsh.eq.1) then   ! reg mesh
                  ntrn = itrgn(itnm)
                  mtrn = itrgm(itnm)
                  nvol = itrnv(itnm)
                  if( ntrn .gt. 0 ) then
                     ndsm   = itreg(itnm)
                     itrsmn = itsmn(itnm)
                  end if
                  if( nvol .gt. 0 ) then
                     ivl    = itriv(itnm)
                     irvl   = itrrv(itnm)
                     itrsmn = itsmn(itnm)
                  end if

               else if(irtmsh.eq.2) then   ! r-z mesh
                  rzx0  = rtrx0(itnm)
                  rzy0  = rtry0(itnm)

                  ! r-type
                  irtp  = itrty(itnm)
                  inr   = itrnm(itnm)
                  if(irtp.eq.1) then
                     istrg = itrrg(itnm)
                  else
                     rdel  = rtrdl(itnm)
                     rmin  = rtrmi(itnm)
                     rmax  = rtrma(itnm)
                  end if

                  ! z-type
                  iztp  = itzty(itnm)
                  inz   = itznm(itnm)
                  if(iztp.eq.1) then
                     istzg = itzrg(itnm)
                  else
                     zdel  = rtzdl(itnm)
                     zmin  = rtzmi(itnm)
                     zmax  = rtzma(itnm)
                  end if
                  itrsmn = itsmn(itnm)

               else if(irtmsh.eq.3) then   ! xyz mesh
                  ! x-type
                  ixtp  = itxty(itnm)
                  inx   = itxnm(itnm)
                  if(ixtp.eq.1) then
                     istxg = itxrg(itnm)
                  else
                     xdel  = rtxdl(itnm)
                     xmin  = rtxmi(itnm)
                     xmax  = rtxma(itnm)
                  end if


                  ! y-type
                  iytp  = ityty(itnm)
                  iny   = itynm(itnm)
                  if(iytp.eq.1) then
                     istyg = ityrg(itnm)
                  else
                     ydel  = rtydl(itnm)
                     ymin  = rtymi(itnm)
                     ymax  = rtyma(itnm)
                  end if


                  ! z-type
                  iztp  = itzty(itnm)
                  inz   = itznm(itnm)
                  if(iztp.eq.1) then
                     istzg = itzrg(itnm)
                  else
                     zdel  = rtzdl(itnm)
                     zmin  = rtzmi(itnm)
                     zmax  = rtzma(itnm)
                  end if
                  itrsmn = itsmn(itnm)

               else if(irtmsh.eq.4) then   ! tet mesh
                  ireg   = itrgm(itnm)
                  itrrnv = itrnv(itnm)
               end if
               itrsmn = itsmn(itnm)

               ! e-type
               ietp = itety(itnm)
               if( ietp .ne. 0 ) then
                  ine    = itenm(itnm)
                  if(ietp.eq.1) then
                     isteg  = iterg(itnm)
                  else
                     edel   = rtedl(itnm)
                     emin   = rtemi(itnm)
                     emax   = rtema(itnm)
                  end if
                  itrsmn = itsmn(itnm)
               end if

               ! t-type
               ittp   = ittty(itnm)
               if( ittp .ne. 0 ) then
                  int    = ittnm(itnm)
                  if(ittp.eq.1) then
                     isttg  = ittrg(itnm)
                  else
                     tdel   = rttdl(itnm)
                     tmin   = rttmi(itnm)
                     tmax   = rttma(itnm)
                  end if
                  itrsmn = itsmn(itnm)
               end if

               ! a-type
               iatp = itaty(itnm)
               if( iatp .ne. 0 ) then
                  ina  = itanm(itnm)
                  if(iatp.eq.1) then
                     istag = itarg(itnm)
                  else
                     adel = rtadl(itnm)
                     amin = rtami(itnm)
                     amax = rtama(itnm)
                  end if
                  itrsmn = itsmn(itnm)
               end if

               ! l-type


            ! check mesh & bin info. ( ntf > 1 )
            else
               ierr = 0
               if(itmsh(itnm).ne.irtmsh) ierr = 1

               if(italnm.eq.17) then       ! t-point tally
                  if(itpon(itnm).ne.itpnt) ierr = 1
                  do i=1, irtmsh
                     if(rtpon(itnm,i,1).ne.stpon(i,1)) ierr = 1
                     if(rtpon(itnm,i,2).ne.stpon(i,2)) ierr = 1
                     if(rtpon(itnm,i,3).ne.stpon(i,3)) ierr = 1
                     if(rtpon(itnm,i,4).ne.stpon(i,4)) ierr = 1
                  end do

               else if(italnm.eq.2 .and.
     &                 irtmsh.eq.1) then   ! t-cross tally(reg mesh)
                  if(itrcn(itnm).ne.ntcn) ierr = 1
                  do i=1, ntcn
                     if( das_itrca(itrca(itnm)-1+i) .ne.
     &                   das_itrca(ktcr-1+i) ) ierr=1
                  end do

               else if(irtmsh.eq.1) then   ! reg mesh
                  if(itrgn(itnm).ne.ntrn) ierr = 1
                  if(itrgm(itnm).ne.mtrn) ierr = 1
                  if(itrnv(itnm).ne.nvol) ierr = 1
                  if( ntrn .gt. 0 ) then
                  end if
                  if( nvol .gt. 0 ) then
                     do k=1, nvol
                        if(idas(itriv(itnm)+k-1).ne.idas(ivl +k-1))
     &                                            ierr = 1
                        if( das(itrrv(itnm)+k-1).ne. das(irvl+k-1))
     &                                            ierr = 1
                     end do
                  end if

               else if(irtmsh.eq.2) then   ! r-z mesh
                  ! r-type
                  if(rtrx0(itnm).ne.rzx0 ) ierr = 2
                  if(rtry0(itnm).ne.rzy0 ) ierr = 2

                  if(itrty(itnm).ne.irtp ) ierr = 2
                  if(itrnm(itnm).ne.inr  ) ierr = 2
                  if(irtp.eq.1) then
                     do i=1,inr+1
                        if( das_itrrg(itrrg(itnm)-1+i) .ne.
     &                      das_itrrg(istrg-1+i) ) ierr=2
                     end do
                  else
                     if(rtrdl(itnm).ne.rdel ) ierr = 2
                     if(rtrmi(itnm).ne.rmin ) ierr = 2
                     if(rtrma(itnm).ne.rmax ) ierr = 2
                  end if

                  ! z-type
                  if(itzty(itnm).ne.iztp ) ierr = 2
                  if(itznm(itnm).ne.inz  ) ierr = 2
                  if(iztp.eq.1) then
                     do i=1,inz+1
                        if( das_itzrg(itzrg(itnm)-1+i) .ne.
     &                      das_itzrg(istzg-1+i) ) ierr=2
                     end do
                  else
                     if(rtzdl(itnm).ne.zdel ) ierr = 2
                     if(rtzmi(itnm).ne.zmin ) ierr = 2
                     if(rtzma(itnm).ne.zmax ) ierr = 2
                  end if

               else if(irtmsh.eq.3) then   ! xyz mesh
                  ! x-type
                  if(itxty(itnm).ne.ixtp ) ierr = 3
                  if(itxnm(itnm).ne.inx  ) ierr = 3
                  if(ixtp.eq.1) then
                     do i=1,inx+1
                        if( das_itxrg(itxrg(itnm)-1+i) .ne.
     &                      das_itxrg(istxg-1+i) ) ierr=3
                     end do
                  else
                     if(rtxdl(itnm).ne.xdel ) ierr = 3
                     if(rtxmi(itnm).ne.xmin ) ierr = 3
                     if(rtxma(itnm).ne.xmax ) ierr = 3
                  end if

                  ! y-type
                  if(ityty(itnm).ne.iytp ) ierr = 3
                  if(itynm(itnm).ne.iny  ) ierr = 3
                  if(iytp.eq.1) then
                     do i=1,iny+1
                        if( das_ityrg(ityrg(itnm)-1+i) .ne.
     &                      das_ityrg(istyg-1+i) ) ierr=3
                     end do
                  else
                     if(rtydl(itnm).ne.ydel ) ierr = 3
                     if(rtymi(itnm).ne.ymin ) ierr = 3
                     if(rtyma(itnm).ne.ymax ) ierr = 3
                  end if

                  ! z-type
                  if(itzty(itnm).ne.iztp ) ierr = 3
                  if(itznm(itnm).ne.inz  ) ierr = 3
                  if(iztp.eq.1) then
                     do i=1,inz+1
                        if( das_itzrg(itzrg(itnm)-1+i) .ne.
     &                      das_itzrg(istzg-1+i) ) ierr=3
                     end do
                  else
                     if(rtzdl(itnm).ne.zdel ) ierr = 3
                     if(rtzmi(itnm).ne.zmin ) ierr = 3
                     if(rtzma(itnm).ne.zmax ) ierr = 3
                  end if

               else if(irtmsh.eq.4) then   ! tet mesh
                   if(itrgm(itnm).ne.ireg) ierr = 4
                   if(itrnv(itnm).ne.itrrnv) ierr = 4

               end if



               ! check bin info.
               if( ietp .ne. 0 ) then   ! e-type
                  if(itety(itnm).ne.ietp ) ierr = 5
                  if(itenm(itnm).ne.ine  ) ierr = 5
                  if(ietp.eq.1) then
                     do i=1,ine+1
                        if( das_iterg(iterg(itnm)-1+i) .ne.
     &                      das_iterg(isteg-1+i) ) ierr=3
                     end do
                  else
                     if(rtedl(itnm).ne.edel ) ierr = 5
                     if(rtemi(itnm).ne.emin ) ierr = 5
                     if(rtema(itnm).ne.emax ) ierr = 5
                  end if
               end if

               if( ittp .ne. 0 ) then   ! t-type
                  if(ittty(itnm).ne.ittp ) ierr = 7
                  if(ittnm(itnm).ne.int  ) ierr = 7
                  if(ittp.eq.1) then
                     do i=1,int+1
                        if( das_ittrg(ittrg(itnm)-1+i) .ne.
     &                      das_ittrg(isttg-1+i) ) ierr=3
                     end do
                  else
                     if(rttdl(itnm).ne.tdel ) ierr = 7
                     if(rttmi(itnm).ne.tmin ) ierr = 7
                     if(rttma(itnm).ne.tmax ) ierr = 7
                  end if
               end if

               if( iatp .ne. 0 ) then   ! a-type
                  if(itaty(itnm).ne.iatp ) ierr = 12
                  if(itanm(itnm).ne.ina  ) ierr = 12
                  if(iatp.eq.1) then
                     do i=1,ina+1
                        if( das_itarg(itarg(itnm)-1+i) .ne.
     &                      das_itarg(istag-1+i) ) ierr=3
                     end do
                  else
                     if(rtadl(itnm).ne.adel ) ierr = 12
                     if(rtami(itnm).ne.amin ) ierr = 12
                     if(rtama(itnm).ne.amax ) ierr = 12
                  end if
               end if



               if( ierr .ne. 0 ) then
                  ErrCha = ''
                  MsgID = 'L:2378/R:anatal_set_tal/F:anatally.f'
                  call ErrWrite(MsgID, ErrCha)
                  write(jo,'(/"Error: an inconsistent bin is found"
     &                       ," in tally file for anatally.")')
                  write(io,'(/"Error: an inconsistent bin is found "
     &                       ,"in tally file for anatally.")')
                  if(ierr.eq.5) then
                     write(jo,'(9x,a8,i2,a4,a)')
     &                      'e-type= ',ietp,' in ',csumfile(1:isidsi)
                     write(io,'(9x,a8,i2,a4,a)')
     &                      'e-type= ',ietp,' in ',csumfile(1:isidsi)
                  else if(ierr.eq.7) then
                     write(jo,'(9x,a8,i2,a4,a)')
     &                      't-type= ',ittp,' in ',csumfile(1:isidsi)
                     write(io,'(9x,a8,i2,a4,a)')
     &                      't-type= ',ittp,' in ',csumfile(1:isidsi)
                  else if(ierr.eq.12) then
                     write(jo,'(9x,a8,i2,a4,a)')
     &                      'a-type= ',iatp,' in ',csumfile(1:isidsi)
                     write(io,'(9x,a8,i2,a4,a)')
     &                      'a-type= ',iatp,' in ',csumfile(1:isidsi)
                  else if(ierr.eq.-1) then
                     write(jo,'(9x,i3,i2,a4,a)')
     &                      'tally = ',ital(m),' in ',csumfile(1:isidsi)
                     write(io,'(9x,i3,i2,a4,a)')
     &                      'tally = ',ital(m),' in ',csumfile(1:isidsi)
                  end if
                  return
               end if

            end if


         end do   ! ntf=1,nfile(m)

  100    continue

         ierr = 0

*-----------------------------------------------------------------------
* check exit restart prameters in read resfile
*-----------------------------------------------------------------------

c$$$         if( inoprm .gt. 0 ) then
c$$$            !! no restart parameter in read reifles
c$$$            ErrCha = ''
c$$$            MsgID = 'L:2664/R:anatal_set_tal/F:anatally.f'
c$$$            call ErrWrite(MsgID, ErrCha)
c$$$            write(jo,
c$$$     &        '("Error: Some restart file have no restart parameter.")')
c$$$            ierr = 1
c$$$            return
c$$$         end if


      end do   ! m=1, ianatn


      itnm = ianatn ! Number of <anatally start/end> pairs (tally count)

      return
*-----------------------------------------------------------------------

  997 continue

      m_err = 'Unknown section name'
      ErrCha = ''
      ErrID = 'L:2445/R:anatal_set_tal/F:anatally.f'
      l_err = ill(jsn)
      k_err = jsn

*-----------------------------------------------------------------------

  999 continue
      close(jsi)

      write(*,'(/" ***** Error Message from Tally File *****"/)')
      write(*,*) dsin(k_err)(1:idsi(k_err)),l_err,':'

      icf = 200

      do 910 i = 200, 1, -1

         if( m_err(i:i) .ne. ' ' ) goto 911

  910 continue

  911 icf = i

      call ErrWrite(ErrID, ErrCha)
      write(*,'(" error = ",200A1/)') ( m_err(i:i), i=1,icf )

      ierr = 1

      end subroutine anatal_set_tal


!***********************************************************************
!                                                                      *
      subroutine anatal_readlt(isc,jsn,jsi,dsin,idsi,ill,ilf,cmmt,
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
!                                                                      *
!     read lines of input files (text file)                            *
!     original routine is readl in utl3.f                              *
!     Change the file closing process and infl processing              *
!         of the original code.                                        *
!                                                                      *
!***********************************************************************

      implicit real*8 (a-h,o-z)

*-----------------------------------------------------------------------

      include 'angel01.inc'
      include 'err.inc'

*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200
      character chins*200, chlws*200, chcms*200
      parameter ( icolms = 200 )

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

      character yen*1

      character*(*) cmmt

      integer   isc            ! output unit number for scrach file

*-----------------------------------------------------------------------

            yen  = char(92)
            isql = 0
            i3s  = 1
            i4s  = 1

*-----------------------------------------------------------------------

            ierr = 0

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140       ill(jsn) = ill(jsn) + 1

*-----------------------------------------------------------------------

            read(jsi,'(a200)', iostat=ios ) chin
            if( ios .eq. -1 ) goto 251

*-----------------------------------------------------------------------

  240       continue

               if( ill(jsn) .le. ilf(jsn) ) goto 250

*-----------------------------------------------------------------------
*           close files
*-----------------------------------------------------------------------

  251       continue

                  call closef(jsi,jsn)

               write(isc) 'incdec'   ! "incdec" key word
               write(isc) jsn        ! include level
               write(isc) dsin(jsn)  ! input file name
               write(isc) idsi(jsn)  ! length of input file name
               write(isc) ill(jsn)   ! input file lines
               write(isc) ilf(jsn)   ! final line to read

               if( jsn .le. 0 ) then

                  jpn = 3
                  return

               else if( jsn .gt. 0 ) then

                  goto 140

               end if

*-----------------------------------------------------------------------
*        one line edit
*-----------------------------------------------------------------------

  250    continue

                  call chlngt(chin,200,i1,i2)

                  chlw = chin
                  call chcaps(chlw,i1,i2,i3,cmmt)

                  chcm = chlw
                  call chcomp(chcm,i1,i3,i4)

                  k = i1

*-----------------------------------------------------------------------
*        comment line
*        normal line  iskip = 0
*        blank line   iskip = 1
*        comment line iskip = 2
*             ( comment character or 'c ' within 5 column )
*-----------------------------------------------------------------------

            if( i1 .eq. 0 .and. i2 .eq. 0 ) then

               iskip = 1
               return

            else if( index(cmmt,chin(i1:i1)) .ne. 0 ) then

               iskip = 2
               return

            else if( chlw(i1:i1+1) .eq. 'c ' .and. i1 .le. 5  ) then

               iskip = 2
               return

            else

               iskip = 0

            end if

*-----------------------------------------------------------------------
*        sequential line
*-----------------------------------------------------------------------

            if( chlw(i3:i3) .eq. yen ) then

               isql = isql + 1

  150          continue

               if( i3s + i3 - i1 + 1 .gt. 200 ) goto 998

               chin(i3:i3) = ' '
               chlw(i3:i3) = ' '
               chcm(i4:i4) = ' '

               chins(i3s:i3s+i3-i1) = chin(i1:i3)
               chlws(i3s:i3s+i3-i1) = chlw(i1:i3)
               chcms(i4s:i4s+i4-i1) = chlw(i1:i4)

               i3s = i3s + i3 - i1 + 1
               i4s = i4s + i4 - i1 + 1

                  ill(jsn) = ill(jsn) + 1

                  read(jsi,'(a200)', iostat = ios ) chin
                  if( ios .eq. -1 ) goto 999

                  if( ill(jsn) .gt. ilf(jsn) ) goto 999

                  call chlngt(chin,200,i1,i2)

                  chlw = chin
                  call chcaps(chlw,i1,i2,i3,cmmt)

                  chcm = chlw
                  call chcomp(chcm,i1,i3,i4)

                  if( chlw(i3:i3) .eq. yen ) goto 150

               if( i3s + i3 - i1 + 1 .gt. 200 ) goto 998

               chins(i3s:i3s+i3-i1) = chin(i1:i3)
               chlws(i3s:i3s+i3-i1) = chlw(i1:i3)
               chcms(i4s:i4s+i4-i1) = chlw(i1:i4)

               i3s = i3s + i3 - i1 + 1
               i4s = i4s + i4 - i1 + 1

            end if

            if( isql .gt. 0  ) then

               i1 = 1
               i2 = i3s - 1
               i3 = i3s - 1
               i4 = i4s - 1

               chin(i1:i3) = chins(i1:i3)
               chlw(i1:i3) = chlws(i1:i3)
               chcm(i1:i4) = chcms(i1:i4)

               k = i1

            end if

*-----------------------------------------------------------------------
*        infl: {filename} [1-15]  ; include file
*-----------------------------------------------------------------------

            if( jpn .ne. 2. and. chlw(i1:i1+4) .eq. 'infl:' ) then

                  k = k + 4

c  *** T.Sato 2014/2/20, avoid error when -, [, or ] are used in the comment
               do iii=i3+1,i2
                chin(iii:iii)=' '
               enddo
c  *****************************

               call inclf(jsn,jsi,dsin,chin,k,200,ill,ilf,idsi,ierr)

               write(isc) 'incinc'   ! "incinc" key word
               write(isc) jsn        ! include level
               write(isc) dsin(jsn)  ! input file name
               write(isc) idsi(jsn)  ! length of input file name
               write(isc) ill(jsn)   ! input file lines
               write(isc) ilf(jsn)   ! final line to read

                  if( ierr .ne. 0 ) return

                  goto 140

            end if

*-----------------------------------------------------------------------
*       stop reading or stop reading the sections
*-----------------------------------------------------------------------

            if( jpn .le. 1 ) then

               if( chlw(i1:i1+1) .eq. 'q:' ) then

                  jsn0 = jsn

                  do j = jsn0, 1, -1

                     call closef(jsi,jsn)

                  end do

                  jpn = 3
                  return

               else if( chlw(i1:i1+2) .eq. 'qp:' ) then

                  jpn = 2
                  goto 140

               end if

            end if

*-----------------------------------------------------------------------
*       skip lines under qp: up to [sections]
*-----------------------------------------------------------------------

         if( jpn .eq. 2 ) then

            if( i1 .gt. 5 .or. chlw(i1:i1) .ne. '[' ) goto 140

            jpn = 1

         end if

*-----------------------------------------------------------------------

      return

*-----------------------------------------------------------------------

  998 continue

         m_err ='Sequential line includes too many characters: max(200)'
         ErrCha = ''
         ErrID = 'L:2760/R:anatal_readlt/F:anatally.f'
         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1
         return

*-----------------------------------------------------------------------

  999 continue

         m_err = 'Sequential line meets the end of file.'
         ErrCha = ''
         ErrID = 'L:2772/R:anatal_readlt/F:anatally.f'
         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1
         return

*-----------------------------------------------------------------------

      end subroutine anatal_readlt
!***********************************************************************


!***********************************************************************
!                                                                      *
      subroutine anatal_readl(jsn,jsi,dsin,idsi,ill,ilf,cmmt,
     &                        jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
!                                                                      *
!     read lines of input files(anatally sub-section data, binary file)*
!     original routine is readl in utl3.f                              *
!                                                                      *
!***********************************************************************

      implicit real*8 (a-h,o-z)

*-----------------------------------------------------------------------

      include 'angel01.inc'
      include 'err.inc'

*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200
      character chins*200, chlws*200, chcms*200
      parameter ( icolms = 200 )

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

      character yen*1

      character*(*) cmmt

*-----------------------------------------------------------------------

            yen  = char(92)
            isql = 0
            i3s  = 1
            i4s  = 1

*-----------------------------------------------------------------------

            ierr = 0

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140       ill(jsn) = ill(jsn) + 1
*-----------------------------------------------------------------------

            do iii=1,200
               chin(iii:iii)=' '
            enddo
            read(jsi, iostat=ios ) chin
            if( ios .eq. -1 ) then

               jpn = 3
               return

            end if

*-----------------------------------------------------------------------

  240       continue

               if( ill(jsn) .le. ilf(jsn) ) goto 250

*-----------------------------------------------------------------------
*        one line edit
*-----------------------------------------------------------------------

  250    continue

                  call chlngt(chin,200,i1,i2)

                  chlw = chin
                  call chcaps(chlw,i1,i2,i3,cmmt)

                  chcm = chlw
                  call chcomp(chcm,i1,i3,i4)

                  k = i1

*-----------------------------------------------------------------------
*        comment line
*        normal line  iskip = 0
*        blank line   iskip = 1
*        comment line iskip = 2
*             ( comment character or 'c ' within 5 column )
*-----------------------------------------------------------------------

            if( i1 .eq. 0 .and. i2 .eq. 0 ) then

               iskip = 1
               return

            else if( index(cmmt,chin(i1:i1)) .ne. 0 ) then

               iskip = 2
               return

            else if( chlw(i1:i1+1) .eq. 'c ' .and. i1 .le. 5  ) then

               iskip = 2
               return

            else

               iskip = 0

            end if

*-----------------------------------------------------------------------
*        sequential line
*-----------------------------------------------------------------------

            if( chlw(i3:i3) .eq. yen ) then

               isql = isql + 1

  150          continue

               if( i3s + i3 - i1 + 1 .gt. 200 ) goto 998

               chin(i3:i3) = ' '
               chlw(i3:i3) = ' '
               chcm(i4:i4) = ' '

               chins(i3s:i3s+i3-i1) = chin(i1:i3)
               chlws(i3s:i3s+i3-i1) = chlw(i1:i3)
               chcms(i4s:i4s+i4-i1) = chlw(i1:i4)

               i3s = i3s + i3 - i1 + 1
               i4s = i4s + i4 - i1 + 1

                  ill(jsn) = ill(jsn) + 1

                  read(jsi, iostat = ios ) chin
                  if( ios .eq. -1 ) goto 999

                  if( ill(jsn) .gt. ilf(jsn) ) goto 999

                  call chlngt(chin,200,i1,i2)

                  chlw = chin
                  call chcaps(chlw,i1,i2,i3,cmmt)

                  chcm = chlw
                  call chcomp(chcm,i1,i3,i4)

                  if( chlw(i3:i3) .eq. yen ) goto 150

               if( i3s + i3 - i1 + 1 .gt. 200 ) goto 998

               chins(i3s:i3s+i3-i1) = chin(i1:i3)
               chlws(i3s:i3s+i3-i1) = chlw(i1:i3)
               chcms(i4s:i4s+i4-i1) = chlw(i1:i4)

               i3s = i3s + i3 - i1 + 1
               i4s = i4s + i4 - i1 + 1

            end if

            if( isql .gt. 0  ) then

               i1 = 1
               i2 = i3s - 1
               i3 = i3s - 1
               i4 = i4s - 1

               chin(i1:i3) = chins(i1:i3)
               chlw(i1:i3) = chlws(i1:i3)
               chcm(i1:i4) = chcms(i1:i4)

               k = i1

            end if

*-----------------------------------------------------------------------
*       stop reading or stop reading the sections
*-----------------------------------------------------------------------

            if( jpn .le. 1 ) then

               if( chlw(i1:i1+1) .eq. 'q:' ) then

                     jpn = 3
                     return

               else if( chlw(i1:i1+2) .eq. 'qp:' ) then

                     jpn = 2
                     return

               end if

            end if

*-----------------------------------------------------------------------

      return

*-----------------------------------------------------------------------

  998 continue

         m_err ='Sequential line includes too many characters: max(200)'
         ErrCha = ''
         ErrID = 'L:2997/R:anatal_readl/F:anatally.f'
         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1
         return

*-----------------------------------------------------------------------

  999 continue

         m_err = 'Sequential line meets the end of file.'
         ErrCha = ''
         ErrID = 'L:3009/R:anatal_readl/F:anatally.f'
         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1
         return

*-----------------------------------------------------------------------

      end subroutine anatal_readl
!***********************************************************************


!***********************************************************************
!                                                                      *
      subroutine anatal_echo(iot)
!                                                                      *
!     echo anatally sub section data                                   *
!     create by S.Hashimoto on 2019/8/1                                *
!                                                                      *
!***********************************************************************

      use anatallymod
      use sumtallymod

      implicit none

!-----------------------------------------------------------------------
      include 'param.inc'

      integer   itnm
      integer   ital
      integer   itals
      integer   italm

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)
*-----------------------------------------------------------------------

      integer iot, m, maxltf, infile, k, icm, ic, n
      character ch200*400
      character ch100*400

*-----------------------------------------------------------------------

      write(iot,'(/"[ anatally ]")')

      do m = 1, itnm                            ! loop for number of tallys
       if ( nanatalRead(m) > 0 ) then           ! anattaly data
        write(iot,'("anatally start",i5)') m

        write(iot,'("manatally =",i5,11x,
     &" # (D=1) anatally option, 1:uncertainties, 2:dependence")')
     &     manatally(m)

        write(iot,'("    nfile =",i5,11x,
     &" # number of tally files")')
     &     nfile(m)

        do n=1, nfile(m)
         ic = 12
         if ( n == 1 ) then
          ch200(1:ic) = 'tallyfile = '
         else
          ch200(1:ic) = '            '
         end if
         ch200(ic+1:ic+ltallyfname(n,m)) =
     &                  tallyfname(n,m)(1:ltallyfname(n,m))
         icm = ic+ltallyfname(n,m)
         write(iot,'(200a1)') (ch200(k:k),k=1,icm)
        end do


        icm = 41
        ch100(1:icm) = ' # file name of output by anatally option'
        do k = 1, 27
         ch200(k:k) = ' '
        end do
        ic = 12
        ch200(1:ic) = '    sfile = '
        ch200(ic+1:ic+lsfile(m)) = sfile(m)(1:lsfile(m))
        if ( ic+lsfile(m) .le. 27 ) then
         ch200(27+1:27+icm) = ch100(1:icm)
         icm = 27+icm
        else
         ch200(ic+lsfile(m)+1:ic+lsfile(m)+icm) = ch100(1:icm)
         icm = ic+lsfile(m)+icm
        end if
        write(iot,'(200a1)') (ch200(k:k),k=1,icm)

        write(iot,'("sumfactor =",1p1e12.5,4x,
     &" # (D=1.0) normalization factor for anatally")') sumfactor(m)

        if ( lsumang(m) > 0 ) then
         write(iot,'("angel = ",a)') sumang(m)(1:lsumang(m))
        end if

        write(iot,'("anatally end",i5)') m

       end if
      end do   ! loop for number of tallys

*-----------------------------------------------------------------------

      return

      end subroutine anatal_echo
!***********************************************************************


!***********************************************************************
!                                                                      *
      subroutine anatally(io,jo,ivers,ierr)
!                                                                      *
!     create by S.Hashimoto on 2019/7/31                               *
!                                                                      *
!***********************************************************************
       use GGBANKMOD
       use TALMOD,   only : tr0
       use anatallymod
       use sumtallymod
       use TDCHAINMOD, only : pdchreg2
       use partmod, only: itpan, itpat, jtpat ! frtati 2021/10/05

       implicit real*8 (a-h,o-z)

!-----------------------------------------------------------------------

       include 'param.inc'
       include 'angel01.inc'
       include 'err.inc'

!-----------------------------------------------------------------------

c     integer mxcval  ! T.Sato 2021/01/30, save original cval because it will be changed in usranatal.f
      double precision cval,aval,cvalanatal,avalanatal
      common /rval1/ cval(mxcval), aval(mxcval)
      common /rvalanatal/ cvalanatal(mxcval), avalanatal(mxcval)

       integer   itnm
       integer   ital
       integer   itals
       integer   italm
       common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)

       integer itxty
       integer itxnm
       integer itxrg
       double precision rtxmi
       double precision rtxma
       double precision rtxdl
       common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &                 rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)

       integer ityty
       integer itynm
       integer ityrg
       double precision rtymi
       double precision rtyma
       double precision rtydl
       common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &                 rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)

       integer itzty
       integer itznm
       integer itzrg
       double precision rtzmi
       double precision rtzma
       double precision rtzdl
       common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                 rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)

       integer itety
       integer itenm
       integer iterg
       double precision rtemi
       double precision rtema
       double precision rtedl
       common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                 rtemi(itlmax), rtema(itlmax), rtedl(itlmax)

cfrtati 2021/10/05 moved to partmod

       integer   itfln
       integer   itfll
       character ctfln*100
       common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)

       integer ittty
       integer ittnm
       integer ittrg
       double precision rttmi
       double precision rttma
       double precision rttdl
       common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                 rttmi(itlmax), rttma(itlmax), rttdl(itlmax)

       integer itaty
       integer itanm
       integer itarg
       double precision rtami
       double precision rtama
       double precision rtadl
       common /tall23/ itaty(itlmax), itanm(itlmax), itarg(itlmax),
     &                 rtami(itlmax), rtama(itlmax), rtadl(itlmax)

       integer itmcn
       integer itmtn
       integer itmtt
       common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)

       integer itmlp
       integer itmln
       integer itmst
       integer itmli
       double precision rtmme
       integer itmnt
       integer itmpn
       integer itmpt
       common /tall45/ itmlp(itlmax), itmln(itlmax,6), itmst(itlmax),
     &               itmli(itlmax,6), rtmme(itlmax,6), itmnt(itlmax,6),
     &               itmpn(itlmax,6), itmpt(itlmax,6,6,2)

!-----------------------------------------------------------------------

       integer   itanl
       character itang*200
       common /tall15/ itanl(itlmax), itang(itlmax)

!-----------------------------------------------------------------------

       integer, intent(in)   :: io             !
       integer, intent(in)   :: jo             !
       integer, intent(inout):: ivers          !
       integer, intent(out)  :: ierr           ! return code (=0:normal retrun)

       integer :: i,m
       integer :: iax
       integer :: ncol

!-----------------------------------------------------------------------

       integer           ntf
       integer           np
       integer           ne
       integer           nt
       integer           nx
       integer           ny
       integer           nz
       integer           nm

       integer           na

!-----------------------------------------------------------------------
       ierr = 0

       do i=1,mxcval  ! T.Sato 2021/01/30, save original value
        cvalanatal(i)=cval(i)
        avalanatal(i)=aval(i)
       enddo

       do m=1, itnm
        if( nanatalRead(m) > 0 ) goto 8   ! check anatally sub section
       end do
       return   ! no anatally sub section

    8  continue

       call ALLOCATE_ANATAL

       do m=1, itnm

        if( nanatalRead(m) .lt. 1 ) cycle   ! check anatally sub section
        if( ital(m) == 16 )         cycle   ! t-dchain

        ntf = 1

!-----------------------------------------------------------------------
!        read tally file.
!-----------------------------------------------------------------------

        call anatal_read_resfiles(m,io,jo,ivers,ntf,ierr)
        if ( ierr /= 0 ) goto 9999
        call anatal_read_talls(m,io,ntf,ierr)
        if ( ierr /= 0 ) goto 9999

!-----------------------------------------------------------------------

         call anatal_calc_anova(m,ntf,ierr) ! integration


        if ( ierr /= 0 ) goto 9999

        if( nfile(m) > 1 ) then
         do ntf=2, nfile(m)
          call anatal_read_resfiles(m,io,jo,ivers,ntf,ierr)
          if ( ierr /= 0 ) goto 9999
          call anatal_read_talls(m,io,ntf,ierr)
          if ( ierr /= 0 ) goto 9999

           call anatal_calc_anova(m,ntf,ierr) ! integration

          if ( ierr /= 0 ) goto 9999
         end do   ! ntf(2-nfile) loop end
        end if

       end do   ! m(tally) loop end

       call COPY_ANATAL

!-----------------------------------------------------------------------

       call ALLOCATE_GGBANK
       call INIT_GGBANK

!-----------------------------------------------------------------------
!        write tally file.
!-----------------------------------------------------------------------

       do m=1, itnm
        if( nanatalRead(m) .lt. 1 ) cycle   ! check anatally sub section
        if( ital(m) > 0 ) then
         itfln(m)     = 1                    ! Number of files
         do iax=1, itfln(m)
          itfll(m,iax) = lsfile(m)                  ! file name length
          ctfln(m,iax) =  sfile(m)(1:lsfile(m))     ! file name
         end do
        end if

        ! add to the ANGEL parameter
        if ( itanl(m)+lsumang(m)+1 <= len(itang(m)) ) then
         if ( itanl(m) >= 1 ) then
          itang(m) = itang(m)(1:itanl(m)) // ' ' //
     &              sumang(m)(1:lsumang(m))
          itanl(m) = itanl(m)+lsumang(m)+1
         else
          itang(m) = sumang(m)(1:lsumang(m))
          itanl(m) =  itanl(m)+lsumang(m)
         end if
        else

         ErrCha = ''
         ErrID = 'L:3349/R:anatally/F:anatally.f' !E85_001_001
         call ErrWrite(ErrID,ErrCha)

         write(*,'(/" ***** Error in Anatally Subsection *****"/)')
         write(*,'(" error = ",i3, "-th tally",
     &           " of angel parameter, it could not be added.")') m
         ierr = 1
         go to 9999
        end if
       end do

        ncol = 3
        call anatal_out(ncol)

!.......................................................................
!      t-dchain tally
!.......................................................................

       do m=1, itnm
        if( nanatalRead(m) .lt. 1 ) cycle   ! check anatally sub section
        if( ital (m) == 16 .and.
     &       ( itals(m) == 38 .or. itals(m) == 39
     &       .or. itals(m) == 40 .or. itals(m) == 54 ) ) then ! t-dchain
         call pdchreg2(m)
        end if
       end do

       call DEALLOCATE_GGBANK
       call DEALLOCATE_ANATAL

!-----------------------------------------------------------------------

 9999  continue
       return

      end subroutine anatally
!***********************************************************************


!***********************************************************************
!                                                                      *
      subroutine anatal_read_resfiles(m,io,jo,ivers,ntf,ierr)
!                                                                      *
!     original routine is read_resfiles in restart.f                   *
!     modified by  T.Miura on 2014/11/30                               *
!                                                                      *
!***********************************************************************

        use anatallymod
        use sumtallymod

!-----------------------------------------------------------------------

        implicit real*8 (a-h,o-z)

        include 'param.inc'
        include 'err.inc'

*-----------------------------------------------------------------------

        common /cparm/  maxbch,maxcas
        common /restart/ resc2(itlmax), resc3(itlmax)
        common /stat / istdev, irestart, ireschk
        common /paraj/  mstz(300), parz(300)

*-----------------------------------------------------------------------

        common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)

        common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
        character ctfln*100

        common /tall59/ irfll(itlmax), crfln(itlmax), itrff(itlmax)
        character crfln*100

*-----------------------------------------------------------------------

        common /res01/ istdevres,maxcasres,rijklstres,irdrf
        common /res02/ crdrfln, irdrfll
        character crdrfln*100

        common /res03/ lextrf(itlmax)
        logical lextrf

        common /res04/ lrijkeqrf
        logical lrijkeqrf

        dimension iristdev(itlmax)
        dimension irmaxcas(itlmax)
        dimension rrijklst(itlmax)

        common /sumtal01/ isistdev, ismaxcas, rsijklst
        integer   :: isistdev(itlmax), ismaxcas(itlmax)
        dimension rsijklst(itlmax)
        character csumfile*200
        integer isjsn, isidsi

*-----------------------------------------------------------------------

        character dsin(0:9)*200
        dimension idsi(0:9)
        dimension ill(0:9), ilf(0:9)

*-----------------------------------------------------------------------

        integer   ntf   ! Number of tallyfname (tally file name)

*-----------------------------------------------------------------------

        iristdev(:) = -1
        irmaxcas(:) = maxcas
        rrijklst(:)  = 0.d0

        lextrf(:)    = .false.

        inoprm = 0

*-----------------------------------------------------------------------
* read each restart files
*-----------------------------------------------------------------------

          jsn     = 0
          jsi     = 32
          idsi(:) = 0
          ill(:)  = 1
          ilf(:)  = 10000000

          ierr = 0

*-----------------------------------------------------------------------
* check the tally is restartable
*-----------------------------------------------------------------------

          if ( .not. any( ital(m) .eq.
     &      (/ 1, 2, 3, 4, 5, 6, 7, 8, 12, 13, 14, 15, 17,
     &         18, 21 /) ) ) then

            goto 100

          end if

*-----------------------------------------------------------------------
* read restart prameters in read resfile
*-----------------------------------------------------------------------

          if ( irfll(m) .eq. 0 ) then
            irfll(m) = itfll(m,1)
            crfln(m)(1:) = ctfln(m,1)(1:itfll(m,1))
          end if


          idsi(jsn) = ltallyfname(ntf,m)

          dsin(jsn)(1:idsi(jsn)) = tallyfname(ntf,m)(1:idsi(jsn))

          isidsi = idsi(jsn)
          csumfile(1:isidsi) = dsin(jsn)(1:idsi(jsn))

          open(jsi,
     &         file=dsin(jsn)(1:idsi(jsn)), status='old', action='read',
     &         form='formatted', iostat=ierr)

          if( ierr .eq. 0 ) then

            call rrestart(jsn,jsi,dsin,idsi,ill,ilf,
     &                    iristdev(m), resc2(m), resc3(m),
     &                    irmaxcas(m), rrijklst(m),
     &                    ierr)

            close(jsi)

            if( ierr .eq. 0 ) then
              lextrf(m) = .true.
            else
              inoprm = inoprm + 1
            end if

          else

            resc2(m) = 0.d0
            resc3(m) = 0.d0

          end if

  100   continue

        ierr = 0

*-----------------------------------------------------------------------
* check exit restart prameters in read resfile
*-----------------------------------------------------------------------

        if( inoprm .gt. 0 ) then
          !! no restart parameter in read reifles
          ErrCha = ''
          MsgID = 'L:3544/R:anatal_read_resfiles/F:anatally.f'
          call ErrWrite(MsgID, ErrCha)
          write(jo,
     &      '("Error: Some restart file have no restart parameter.")')
          ierr = 1
          return
        end if

*-----------------------------------------------------------------------
* check exit restart files
*-----------------------------------------------------------------------

        if ( .not. any( lextrf(1:itnm) ) ) then
          !! all restart files are not found
          ErrCha = ''
          MsgID = 'L:3559/R:anatal_read_resfiles/F:anatally.f'
          call ErrWrite(MsgID, ErrCha)
          write(jo,'("Error: Tally file(s) written in anatally ",
     &             "subsection do not exist.")')
          ierr = 1
          return
        end if

*-----------------------------------------------------------------------
* tall number of primery restart file
*-----------------------------------------------------------------------

        irdrf = 0
          if ( lextrf(m) ) then
            irdrf = m
            go to 1000
          end if
 1000     continue


*-----------------------------------------------------------------------
* check all read istdev values are same in one tally
*-----------------------------------------------------------------------

          if ( manatally(m) .eq. 1 ) then
           if ( ntf .gt. 1 ) then
            if ( isistdev(m) .ne. iristdev(m) ) then
             ErrCha = ''
             MsgID = 'L:3587/R:anatal_read_resfiles/F:anatally.f'
             call ErrWrite(MsgID, ErrCha)
             write(jo,'(/"Error: an inconsistent istdev is found "
     &                 ,"in tally file for anatally.")')
             write(jo,'(9x,a8,i2,a4,a)')
     &            'istdev= ',iristdev(m),' in ',csumfile(1:isidsi)
             write(io,'(/"Error: an inconsistent istdev is found "
     &                 ,"in tally file for anatally.")')
             write(io,'(9x,a8,i2,a4,a)')
     &            'istdev= ',iristdev(m),' in ',csumfile(1:isidsi)
             ierr = 1
             return
            end if
           end if
          end if
          isistdev(m) = iristdev(m)

*-----------------------------------------------------------------------
* check all read maxcas values are same
*-----------------------------------------------------------------------

          if ( manatally(m) .eq. 1 ) then
           if ( ntf .gt. 1 ) then
            if ( ismaxcas(m) .ne. irmaxcas(m) ) then
             ErrCha = ''
             MsgID = 'L:3612/R:anatal_read_resfiles/F:anatally.f'
             call ErrWrite(MsgID, ErrCha)
             write(jo,'(/"Error: an inconsistent maxcas is found "
     &                 ,"in tally file for anatally.")')
             write(jo,'(9x,a8,i11,a4,a)')
     &            'maxcas= ',irmaxcas(m),' in ',csumfile(1:isidsi)
             write(io,'(/"Error: an inconsistent maxcas is found "
     &                 ,"in tally file for anatally.")')
             write(io,'(9x,a8,i11,a4,a)')
     &            'maxcas= ',irmaxcas(m),' in ',csumfile(1:isidsi)
             ierr = 1
             return
            end if
           end if
          end if
          ismaxcas(m) = irmaxcas(m)



          rsijklst(m) = rrijklst(m)

      end subroutine anatal_read_resfiles
!***********************************************************************


!***********************************************************************
!                                                                      *
      subroutine anatal_read_talls(m,io,ntf,ierr)
!                                                                      *
!     original routine is read_talls in restart.f                      *
!     modified by  T.Miura on 2014/11/30                               *
!                                                                      *
!***********************************************************************

        use GGBANKMOD
        use anatallymod
        use sumtallymod

        implicit real*8 (a-h,o-z)

        include 'param.inc'

*-----------------------------------------------------------------------

        common /cparm/  maxbch,maxcas
        common /restart/ resc2(itlmax), resc3(itlmax)
        common /stat / istdev, irestart, ireschk

*-----------------------------------------------------------------------

        common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)

        common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
        character ctfln*100

        common /tall59/ irfll(itlmax), crfln(itlmax), itrff(itlmax)
        character crfln*100

*-----------------------------------------------------------------------

        character dsin(0:9)*200
        dimension idsi(0:9)
        dimension ill(0:9), ilf(0:9)

*-----------------------------------------------------------------------

        integer   ntf   ! Number of tallyfname (tally file name)

*-----------------------------------------------------------------------

        ierr    = 0

        call ALLOCATE_GGBANK
        call INIT_GGBANK

*-----------------------------------------------------------------------
* read each tally files
*-----------------------------------------------------------------------

         if( nanatalRead(m) == 0 ) return     ! skipped, next do loop

        do 800 iax = 1, 1

*-----------------------------------------------------------------------
*         [t-track]
*-----------------------------------------------------------------------

          if ( ital(m) .eq. 1 ) then

            call sumtal_read_ttrack(m,iax,ntf,ierr)
            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-adjoint]
*-----------------------------------------------------------------------

          else if ( ital(m) .eq. 19 ) then

            call sumtal_read_tadjnt(m,iax,ntf,ierr)
            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-cross]
*-----------------------------------------------------------------------

          else if ( ital(m) .eq. 2 ) then

            call sumtal_read_tcross(m,iax,ntf,ierr)
            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-yield]
*-----------------------------------------------------------------------

          else if ( ital(m) .eq. 3 ) then

            call sumtal_read_tyield(m,iax,ntf,ierr)
            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-heat]
*-----------------------------------------------------------------------

          else if ( ital(m) .eq. 4 ) then

            call sumtal_read_theat(m,iax,ntf,ierr)
            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-star]
*-----------------------------------------------------------------------

          else if ( ital(m) .eq. 5 ) then

            call sumtal_read_tstar(m,iax,ntf,ierr)
            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-time]
*-----------------------------------------------------------------------

          else if ( ital(m) .eq. 6 ) then

            call sumtal_read_ttime(m,iax,ntf,ierr)
            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-dpa]
*-----------------------------------------------------------------------

          else if ( ital(m) .eq. 7 ) then

            call sumtal_read_tdpa(m,iax,ntf,ierr)
            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-product]
*-----------------------------------------------------------------------

          else if ( ital(m) .eq. 8 ) then

            call sumtal_read_tproduct(m,iax,ntf,ierr)
            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-let]
*-----------------------------------------------------------------------

          else if ( ital(m) .eq. 12 ) then

            call sumtal_read_tlet(m,iax,ntf,ierr)
            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-deposit]
*-----------------------------------------------------------------------

          else if ( ital(m) .eq. 13 ) then

            call sumtal_read_tdeposit(m,iax,ntf,ierr)
            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-deposit2]
*-----------------------------------------------------------------------

          else if ( ital(m) .eq. 14 ) then

            call sumtal_read_tdeposit2(m,iax,ntf,ierr)
            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-sed]
*-----------------------------------------------------------------------

          else if ( ital(m) .eq. 15 ) then

            call sumtal_read_tsed(m,iax,ntf,ierr)
            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-point]
*-----------------------------------------------------------------------
          else if ( ital(m) .eq. 17 ) then

            call sumtal_read_tpoint(m,iax,ntf,ierr)

            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-wwg]
*-----------------------------------------------------------------------
          else if ( ital(m) .eq. 18 ) then

            call sumtal_read_twwg(m,iax,ntf,ierr)

            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
*         [t-volume]
*-----------------------------------------------------------------------
          else if ( ital(m) .eq. 21 ) then

            call sumtal_read_tvlm(m,iax,ntf,ierr)

            if( ierr .ne. 0 ) then
              goto 900
            end if

*-----------------------------------------------------------------------
          end if

 800    continue

        call trans_trRES2tr0()

 900    continue
        call DEALLOCATE_GGBANK

      end subroutine anatal_read_talls
!***********************************************************************


!***********************************************************************
!                                                                      *
      subroutine anatal_open_resfile(m,noe,ntf,
     &                               jsn,jsi,dsin,idsi,ill,ilf,
     &                               newtall,ierr)
!                                                                      *
!  subroutine open resfiles *.out, *_err.out.                          *
!                                                                      *
!     original routine is open_resfile in resutl.f                     *
!                                                                      *
!***********************************************************************

        use anatallymod
        use sumtallymod

        implicit double precision (a-h,o-z)

*-----------------------------------------------------------------------

        include 'param.inc'
        include 'err.inc'

*-----------------------------------------------------------------------

        common /tall59/ irfll(itlmax), crfln(itlmax), itrff(itlmax)
        character crfln*100

*-----------------------------------------------------------------------

        integer   ntf   ! Number of tallyfname (tally file name)

*-----------------------------------------------------------------------

        character dsin(0:9,2)*200
        dimension idsi(0:9,2)
        dimension ill(0:9,2), ilf(0:9,2)
        dimension jsn(2), jsi(2)
        dimension ierrs(2)

*-----------------------------------------------------------------------

        ierr = 0
        newtall = 0

*-----------------------------------------------------------------------
*   open restart file
*-----------------------------------------------------------------------

        do ioe = 1, noe

          jsn(ioe)    = 0
          jsi(ioe)    = 31 + ioe
          idsi(:,ioe) = 0
          ill(:,ioe)  = 1
          ilf(:,ioe)  = 10000000
          ierrs(ioe)  = 0

          jsni = jsn(ioe)
          jsii = jsi(ioe)

          if ( ioe .eq. 1 ) then
            idsi(jsni,ioe) = ltallyfname(ntf,m)
            dsin(jsni,ioe)(1:idsi(jsni,ioe))
     &                     = tallyfname(ntf,m)(1:idsi(jsni,ioe))
          else
            idsi(jsni,ioe) = ltallyfname(ntf,m) + 4
            call mk_2derrfn(tallyfname(ntf,m),dsin(jsni,ioe),
     &                     ltallyfname(ntf,m))
          end if

          open(jsii,
     &         file=dsin(jsni,ioe)(1:idsi(jsni,ioe)),
     &         status='old', action='read', form='formatted',
     &         iostat=ierrs(ioe))

        end do

*-----------------------------------------------------------------------
*   check dose restart file exit
*-----------------------------------------------------------------------

        if( all(ierrs(1:noe) .ne. 0) .and. itrff(m) .eq. 0 ) then
          !! it's newly tally
          ierr = 0
          newtall = 1
          goto 900
        end if

        if( noe .eq. 1 .and. ierrs(1) .ne. 0 .and. itrff(m) .ne. 0 )then
          ierr = 1
       write(ErrCha,'("Error: resfile = ", a, " does not exist.")')
     &          dsin(jsn(1),1)(1:idsi(jsn(1),1))
       ErrID = 'L:3977/R:anatal_open_resfile/F:anatally.f' !E85_002_001
       call ErrWrite(ErrID,ErrCha)

       write(ErrCha,'("If you want to create new tally",
     &              " in the restart calculation,",
     &              " you should not specify resfile parameter.")')
       ErrID = 'L:3983/R:anatal_open_resfile/F:anatally.f'
       call ErrWrite(ErrID,ErrCha)

          goto 900
        end if

        if( noe .eq. 2 .and. any(ierrs(1:noe) .ne. 0 ) ) then
          ierr = 1
      write(ErrCha,'("Error: Both ", a," and ", a," should exist",
     &              " when you want to restart the calculation.")')
     &          dsin(jsn(1),1)(1:idsi(jsn(1),1)),
     &          dsin(jsn(2),2)(1:idsi(jsn(2),2))
       ErrID = 'L:3995/R:anatal_open_resfile/F:anatally.f' !E85_003_001
       call ErrWrite(ErrID,ErrCha)

          goto 900
        end if

*-----------------------------------------------------------------------
  900   continue

        return

      end subroutine anatal_open_resfile
!***********************************************************************


!***********************************************************************
!                                                                      *
      subroutine anatal_calc_anova(m,ntf,ierr)
!                                                                      *
!***********************************************************************

      use TALMOD,   only : tr0
      use RESTALMOD,   only : irestalm
      use anatallymod
      use sumtallymod
      use partmod, only: itpan, itpat, jtpat ! frtati 2021/10/05

      implicit none

!-----------------------------------------------------------------------

      include 'param.inc'

!-----------------------------------------------------------------------

      integer itnm
      integer ital
      integer itals
      integer italm
      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)

      integer itmsh
      integer itunt
      integer itspc
      integer itout
      integer ittwo
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &     itout(itlmax), ittwo(itlmax)

      integer itrgn
      integer itrgm
      integer itreg
      common /tall02/ itrgn(itlmax), itrgm(itlmax), itreg(itlmax)

      integer itrty
      integer itrnm
      integer itrrg
      double precision rtrmi
      double precision rtrma
      double precision rtrdl
      common /tall03/ itrty(itlmax), itrnm(itlmax), itrrg(itlmax),
     &     rtrmi(itlmax), rtrma(itlmax), rtrdl(itlmax)

      integer itxty
      integer itxnm
      integer itxrg
      double precision rtxmi
      double precision rtxma
      double precision rtxdl
      common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &     rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)

      integer ityty
      integer itynm
      integer ityrg
      double precision rtymi
      double precision rtyma
      double precision rtydl
      common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &     rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)

      integer itzty
      integer itznm
      integer itzrg
      double precision rtzmi
      double precision rtzma
      double precision rtzdl
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &     rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)

      integer itety
      integer itenm
      integer iterg
      double precision rtemi
      double precision rtema
      double precision rtedl
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &     rtemi(itlmax), rtema(itlmax), rtedl(itlmax)

cfrtati 2021/10/05 moved to partmod

      integer itman
      integer itmat
      integer itmct
      integer itnun
      integer itnuc
      integer itndz
      integer itndn
      integer itnkz
      integer itnkn
      common /tall12/ itman(itlmax), itmat(itlmax), itmct(itlmax),
     &                itnun(itlmax), itnuc(itlmax),
     &                itndz(itlmax), itndn(itlmax),
     &                itnkz(itlmax), itnkn(itlmax)

      integer itrcn
      integer itrcr
      integer itrca
      common /tall13/ itrcn(itlmax), itrcr(itlmax), itrca(itlmax)

      integer itndy
      common /tall17/ itndy(itlmax)

      integer ittty
      integer ittnm
      integer ittrg
      double precision rttmi
      double precision rttma
      double precision rttdl
      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &     rttmi(itlmax), rttma(itlmax), rttdl(itlmax)

      integer itaty
      integer itanm
      integer itarg
      double precision rtami
      double precision rtama
      double precision rtadl
      common /tall23/ itaty(itlmax), itanm(itlmax), itarg(itlmax),
     &                rtami(itlmax), rtama(itlmax), rtadl(itlmax)

      integer itmlp
      integer itmln
      integer itmst
      integer itmli
      double precision rtmme
      integer itmnt
      integer itmpn
      integer itmpt
      common /tall45/ itmlp(itlmax), itmln(itlmax,6), itmst(itlmax),
     &     itmli(itlmax,6), rtmme(itlmax,6), itmnt(itlmax,6),
     &     itmpn(itlmax,6), itmpt(itlmax,6,6,2)

      integer itety2
      integer itenm2
      integer iterg2
      double precision rtemi2
      double precision rtema2
      double precision rtedl2
      common /tall56/ itety2(itlmax), itenm2(itlmax), iterg2(itlmax),
     &                rtemi2(itlmax), rtema2(itlmax), rtedl2(itlmax)

      integer itactnm
      integer itactrg
      integer itactmax
      common /tall72/ itactnm(itlmax), itactrg(itlmax), itactmax(itlmax)

      common /tall83/ itnzn(itlmax), itndm(itlmax)
      integer :: mm, itnzn, itndm

!-----------------------------------------------------------------------

       integer, intent(out)  :: ierr           ! return code (=0:normal retrun)

       integer :: m

!-----------------------------------------------------------------------

       integer           ntf
       integer           np
       integer           ne, nei
       integer           nt
       integer           nx
       integer           ny
       integer           nz
       integer           nr
       integer           nact      ! S.Abe 2018/02/15
       integer           nm
       integer           na
       integer           nd
       integer           mn
       integer           mz
       integer           ne1, ne2
       integer           idasz

!-----------------------------------------------------------------------

       ierr = 0

!-----------------------------------------------------------------------

*-----------------------------------------------------------------------
*         [t-track]
*-----------------------------------------------------------------------

      if ( ital(m) .eq. 1 ) then

* region mesh
       if( itmsh(m) .eq. 1 ) then

        np = itpan(m)
        nr = itrgn(m)
        ne = itenm(m)
        nm = itmst(m)
        nt = ittnm(m)

        call anatal_calc_anova_tracreg(m,ntf,
     &       np,ne,nt,nr,nm,
     &       sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &       resc2SUMTAL(m),resc3SUMTAL(m),
     &       ierr)              ! anova

* r-z mesh
       else if ( itmsh(m) .eq. 2 ) then

        np = itpan(m)
        nr = itrnm(m)
        nz = itznm(m)
        ne = itenm(m)
        nm = itmst(m)
        nt = ittnm(m)
        na = itanm(m)

        call anatal_calc_anova_tracrz(m,ntf,
     &       np,ne,nt,na,nr,nz,nm,
     &       sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &       resc2SUMTAL(m),resc3SUMTAL(m),
     &       ierr)              ! anova

* xyz mesh
       else if ( itmsh(m) .eq. 3 ) then

        np = itpan(m)
        nx = itxnm(m)
        ny = itynm(m)
        nz = itznm(m)
        ne = itenm(m)
        nm = itmst(m)
        nt = ittnm(m)

        call anatal_calc_anova_tracxyz(m,ntf,
     &       np,ne,nt,nx,ny,nz,nm,
     &       sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &       resc2SUMTAL(m),resc3SUMTAL(m),
     &       ierr)              ! anova

* tetra mesh !FURUTA20190110
       else if( itmsh(m) .eq. 4 ) then
! mesh=tet can be treated same as mesh=reg
        np = itpan(m)
        nr = itrgn(m)
        ne = itenm(m)
        nm = itmst(m)
        nt = ittnm(m)

        call anatal_calc_anova_tracreg(m,ntf,
     &       np,ne,nt,nr,nm,
     &       sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &       resc2SUMTAL(m),resc3SUMTAL(m),
     &       ierr)              ! anova

       end if

*-----------------------------------------------------------------------
*         [t-cross]
*-----------------------------------------------------------------------
      else if ( ital(m) .eq. 2 ) then

* region mesh
       if( itmsh(m) .eq. 1 ) then

        np = itpan(m)
        ne = itenm(m)
        nt = ittnm(m)
        na = itanm(m)
        nr = itrcn(m)
        nm = itmst(m)

        call anatal_calc_anova_crsreg(m,ntf,
     &                              np,ne,nt,na,nr,nm,
     &                              sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                              resc2ANATAL(m),resc3ANATAL(m),
     &                              ierr)

* r-z mesh
       else if ( itmsh(m) .eq. 2 ) then

        np = itpan(m)
        ne = itenm(m)
        na = itanm(m)
        nt = ittnm(m)
        nr = itrnm(m)
        nz = itznm(m)
        nm = itmst(m)

        idasz = itenm(m) * itpan(m) * 2
     &        * ( itrnm(m) + 1 ) * itznm(m)
     &        * itanm(m)
     &        * ittnm(m)

        call anatal_calc_anova_crsrz(m,ntf,
     &                             np,ne,na,nt,nr,nz,nm,
     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m),    ! S.H. 2020.6.17
     &       tr0(irestalm(m)+idasz),tranatal(lanatalm(m)+idasz), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
     &                             ierr)

* xyz mesh
       else if ( itmsh(m) .eq. 3 ) then

        nt = ittnm(m)
        np = itpan(m)
        na = itanm(m)
        ne = itenm(m)
        ny = itynm(m)
        nx = itxnm(m)
        nz = itznm(m)
        nm = itmst(m)

        call anatal_calc_anova_crsxyz(m,ntf,
     &                             nt,np,na,ne,ny,nx,nz,nm,
     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
