        mm = itndm(m)

        call anatal_calc_anova_yieldreg(m,ntf,
     &                             mn,mz,mm,nr, ! S.H. added mm (2022.3.11)
     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
     &                             ierr)

* r-z mesh
       else if ( itmsh(m) .eq. 2 ) then

        mn = itndn(m)
        mz = itndz(m)
        nz = itznm(m)
        nr = itrnm(m)
        mm = itndm(m)

        call anatal_calc_anova_yieldrz(m,ntf,
