     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
     &                             ierr)

* xyz mesh
       else if ( itmsh(m) .eq. 3 ) then

        mn = itndn(m)
        mz = itndz(m)
        nz = itznm(m)
        ny = itynm(m)
        nx = itxnm(m)
        mm = itndm(m)

        call anatal_calc_anova_yieldxyz(m,ntf,
     &                             mn,mz,mm,nz,ny,nx, ! S.H. added mm (2022.3.11)
     &                             sumfactor(m),weightRate(1,m),
