* tetra mesh !FURUTA20190121
       else if( itmsh(m) .eq. 4 ) then
! mesh=tet can be treated same as mesh=reg
        mn = itndn(m)
        mz = itndz(m)
        nr = itrgn(m)
        mm = itndm(m)

        call anatal_calc_anova_yieldreg(m,ntf,
     &                             mn,mz,mm,nr, ! S.H. added mm (2022.3.11)
     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
     &                             ierr)

       end if

*-----------------------------------------------------------------------
*         [t-star]
*-----------------------------------------------------------------------

      else if ( ital(m) .eq. 5 ) then

* region mesh
       if( itmsh(m) .eq. 1 ) then

        np = itpan(m)
        ne = itenm(m)
        nt = ittnm(m)
        nr = itrgn(m)
        nact = itactnm(m)      ! S.Abe 2018/02/15

        call anatal_calc_anova_starreg(m,ntf,
     &                             np,ne,nt,nr,nact,
     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
