      else if ( ital(m) .eq. 6 ) then

* region mesh
       if( itmsh(m) .eq. 1 ) then

        np = itpan(m)
        nt = ittnm(m)
        ne = itenm(m)
        nr = itrgn(m)

        call anatal_calc_anova_timereg(m,ntf,
     &                             np,nt,ne,nr,
     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
     &                             ierr)

* r-z mesh
       else if ( itmsh(m) .eq. 2 ) then

        np = itpan(m)
        nt = ittnm(m)
        ne = itenm(m)
        nr = itrnm(m)
        nz = itznm(m)

        call anatal_calc_anova_timerz(m,ntf,
