     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
     &                             ierr)

* xyz mesh
       else if ( itmsh(m) .eq. 3 ) then

        np = itpan(m)
        nt = ittnm(m)
        ne = itenm(m)
        nx = itxnm(m)
        ny = itynm(m)
        nz = itznm(m)

        call anatal_calc_anova_timexyz(m,ntf,
     &                             np,nt,ne,nx,ny,nz,
     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
     &                             ierr)

       end if

*-----------------------------------------------------------------------
