*-----------------------------------------------------------------------

      else if ( ital(m) .eq. 7 ) then

* region mesh
       if( itmsh(m) .eq. 1 ) then

        nd = itndy(m)
        np = itpan(m)
        nr = itrgn(m)

        call anatal_calc_anova_dpareg(m,ntf,
     &                             nd,np,nr,
     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
     &                             ierr)

* r-z mesh
       else if ( itmsh(m) .eq. 2 ) then

        nd = itndy(m)
        np = itpan(m)
        nr = itrnm(m)
        nz = itznm(m)

        call anatal_calc_anova_dparz(m,ntf,
     &                             nd,np,nr,nz,
     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
     &                             ierr)

* xyz mesh
       else if ( itmsh(m) .eq. 3 ) then

        nd = itndy(m)
        np = itpan(m)
        nx = itxnm(m)
        ny = itynm(m)
        nz = itznm(m)

        call anatal_calc_anova_dpaxyz(m,ntf,
     &                             nd,np,nx,ny,nz,
     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
     &                             ierr)

* tetra mesh !FURUTA20190121
       else if( itmsh(m) .eq. 4 ) then
! mesh=tet can be treated same as mesh=reg
        nd = itndy(m)
        np = itpan(m)
        nr = itrgn(m)

        call anatal_calc_anova_dpareg(m,ntf,
     &                             nd,np,nr,
     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
     &                             ierr)

       end if

*-----------------------------------------------------------------------
