        call anatal_calc_anova_productrz(m,ntf,
     &                             np,na,nt,ne,nr,nz,
     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
     &                             ierr)

* xyz mesh
       else if ( itmsh(m) .eq. 3 ) then

        np = itpan(m)
        na = itanm(m)
        nt = ittnm(m)
        ne = itenm(m)
        nx = itxnm(m)
        ny = itynm(m)
        nz = itznm(m)

        call anatal_calc_anova_productxyz(m,ntf,
     &                             np,na,nt,ne,nx,ny,nz,
     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
     &                             ierr)

* tetra mesh !FURUTA20190121
       else if( itmsh(m) .eq. 4 ) then
! mesh=tet can be treated same as mesh=reg
        np = itpan(m)
        na = itanm(m)
        nt = ittnm(m)
        ne = itenm(m)
        nr = itrgn(m)

        call anatal_calc_anova_productreg(m,ntf,
     &                             np,na,nt,ne,nr,
     &                             sumfactor(m),weightRate(1,m),
     &       tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &                             resc2ANATAL(m),resc3ANATAL(m),
