*-----------------------------------------------------------------------
*         [t-deposit]
*-----------------------------------------------------------------------

      else if ( ital(m) .eq. 13 ) then

       if ( itout(m).eq.1 ) then   ! output=Dose

* region mesh
        if( itmsh(m) .eq. 1 ) then

         np = itpan(m)
         nr = itrgn(m)
         ne = itenm(m)
         nt = ittnm(m)

         if( itout(m) .le. 1 ) then
           nei = 0
         else
           nei = 1
         end if

         call anatal_calc_anova_depstreg(m,ntf,
     &        np,nei,ne,nt,nr,
     &        sumfactor(m),weightRate(1,m),
     &        tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &        resc2ANATAL(m),resc3ANATAL(m),
     &        ierr)              ! anova

* r-z mesh
        else if ( itmsh(m) .eq. 2 ) then

         np = itpan(m)
         ne = itenm(m)
         nt = ittnm(m)
