         call anatal_calc_anova_depstrz(m,ntf,
     &        np,nei,ne,nt,nr,nz,
     &        sumfactor(m),weightRate(1,m),
     &        tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &        resc2ANATAL(m),resc3ANATAL(m),
     &        ierr)              ! anova

* xyz mesh
        else if ( itmsh(m) .eq. 3 ) then

         np = itpan(m)
         ne = itenm(m)
         nt = ittnm(m)
         nx = itxnm(m)
         ny = itynm(m)
         nz = itznm(m)

         if( itout(m) .le. 1 ) then
           nei = 0
         else
           nei = 1
         end if

         call anatal_calc_anova_depstxyz(m,ntf,
     &        np,nei,ne,nt,nx,ny,nz,
     &        sumfactor(m),weightRate(1,m),
     &        tr0(irestalm(m)),tranatal(lanatalm(m)),nfile(m), ! S.H. 2020.6.17
     &        resc2ANATAL(m),resc3ANATAL(m),
     &        ierr)              ! anova

* tetra mesh !FURUTA20190121
        else if( itmsh(m) .eq. 4 ) then
! mesh=tet can be treated same as mesh=reg
         np = itpan(m)
         nr = itrgn(m)
         ne = itenm(m)
         nt = ittnm(m)

