!***********************************************************************
!                                                                      *
      subroutine anova(jmax,rdata,rhist,fmval,unca,uncerr,uratio)
!                                                                      *
*-----------------------------------------------------------------------

      implicit none

*-----------------------------------------------------------------------

      integer jmax, ij
      real(8) :: rdata(2,jmax), fmval, unca, uncerr, uratio
      real(8) :: fmsa, fmserr, rhist, rthist
      real(8) :: fmvalj(jmax), variaj(jmax), uvariaj(jmax)

*-----------------------------------------------------------------------

      fmval = 0d0
      fmsa = 0d0
      fmserr = 0d0

      rthist = rhist * dble(jmax)

      do ij = 1, jmax

         fmvalj(ij) = rdata(1,ij)
         variaj(ij) = rdata(1,ij)**2 * rdata(2,ij)**2
         uvariaj(ij) = rdata(1,ij) * rdata(2,ij) * dsqrt(rhist)
         fmval = fmval + fmvalj(ij)
         fmsa = fmsa + fmvalj(ij)**2 * rhist
         fmserr = fmserr + variaj(ij) * rhist*(rhist-1)

      end do

      fmval = fmval / dble(jmax)

      fmsa = fmsa-fmval**2*rthist
      if ( fmsa .lt. 0d0 ) fmsa = 0d0
      fmsa = fmsa / dble(jmax-1)

      fmserr = fmserr / (dble(rthist)-dble(jmax))
      uncerr = dsqrt(fmserr)

      unca = ( fmsa - fmserr ) / rhist
      if ( unca .ge. 0d0 ) then
         unca = dsqrt(unca)
      else
         unca = 0d0
      end if

      if ( fmserr .gt. 0d0 ) then
         uratio = (unca/uncerr)**2
      else
         uratio = 0d0
      end if

*-----------------------------------------------------------------------

      return

      end subroutine anova
!***********************************************************************


