*-----------------------------------------------------------------------

                  itmtn(itnm) = imate
                  itmcn(itnm) = jmate

            if( imate .gt. 0 ) then

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( imate + mod(imate,2) ) / 2

            end if

*-----------------------------------------------------------------------
*        particles
*-----------------------------------------------------------------------

            itmxptt = inpat + 1
            itmxgpt = 1
            do i = 1, inpat
              if ( iptyp(i).lt.0 .and. -iptyp(i).gt.itmxgpt ) then
                itmxgpt = -iptyp(i)
              end if
            end do
            call ALLOCATE_PART_TEMP

            if( inpat .gt. 0 ) then

               do i = 1, inpat

                  itpat(itnm,i,1) = iptyp(i)
                  itpat(itnm,i,2) = ipnkf(i)
                  itpat(itnm,i,3) = ipsub(i)  ! kitamura22/03/31

                  if( itpat(itnm,i,1) .lt. 0 ) then

                     do k = 1, -itpat(itnm,i,1)

                        jtpat(itnm,i,k,1) = imtyp(i,k)
                        jtpat(itnm,i,k,2) = imnkf(i,k)

                     end do

                  end if

               end do

               if( (iout.eq.2 .and. idepo.eq.0) .or. iwgtsum.eq.1 ) then

                  ipchk = -1
                  do i = 1, inpat
                     if( iptyp(i) .eq. 20 ) then
                        ipall(itnm) = i
                        ipchk = ipchk * 0
                     endif
                  enddo

                  if( ipchk .eq. -1 ) then
                     if( iwgtsum .eq. 1 ) then
                      write(6,'(a49)') 'Warning: "all" is necessary for
     & reg = weightsum'
                     else
                      write(6,'(a96)') 'Warning: "all" is necessary for
     & part in tally [t-deposit] with output = deposit and deposit = 0'
                     endif
                     write(6,'(a54)') '         "all" is automatically
     & added the end of part'

                     itpat(itnm,inpat+1,1) = 20
                     itpat(itnm,inpat+1,2) = 0
                     itpan(itnm) = inpat + 1
                     ipall(itnm) = inpat + 1
                  else
                     itpan(itnm) = inpat
                  endif

               else

                  itpan(itnm) = inpat

               endif


            else if( inpat .eq. 0 ) then

                  itpan(itnm) = 1
                  itpat(itnm,1,1) = 20
                  itpat(itnm,1,2) = 0
                  ipall(itnm) = 1      ! S.Abe 2017/10/31

            end if

*-----------------------------------------------------------------------
*        energy mesh
*-----------------------------------------------------------------------

            if( iout .ge. 2 ) then

                  itety(itnm) = ietp
                  itenm(itnm) = ine
                  rtedl(itnm) = edel
                  rtemi(itnm) = emin
                  rtema(itnm) = emax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, ine+1, iterg, das_iterg)
                  das_iterg(iterg(itnm):iterg(itnm)+ine)
     &                     = gmsh(isteg:isteg+ine)

                  itsmn(itnm) = itsmn(itnm) + ine + 1

            else

                  itenm(itnm) = 0

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, 1, iterg, das_iterg)
                  itsmn(itnm) = itsmn(itnm) + 1
                  call moddas_reallocate_dbl(
     &                    3, icurrent_gmsh, 1, iaddress_gmsh, gmsh)
                  iaddress_gmsh(2) = iaddress_gmsh(3)
                  icurrent_gmsh = 2

            end if

*-----------------------------------------------------------------------
*        time mesh
*-----------------------------------------------------------------------

               if( ittp .ne. 0 ) then

                  ittty(itnm) = ittp
                  ittnm(itnm) = int
                  rttdl(itnm) = tdel
                  rttmi(itnm) = tmin
                  rttma(itnm) = tmax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, int+1, ittrg, das_ittrg)
                  das_ittrg(ittrg(itnm):ittrg(itnm)+int)
     &                     = gmsh(isttg:isttg+int)
                  itsmn(itnm) = itsmn(itnm) + int + 1

               else

                  ittty(itnm) = ittp
                  ittnm(itnm) = 1
                  rttdl(itnm) = 0.d0
                  rttmi(itnm) = 0.d0
                  rttma(itnm) = 0.d0

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, 2, ittrg, das_ittrg)
                  itsmn(itnm) = itsmn(itnm) + 2

                  das_ittrg(ittrg(itnm)  ) = -1.d+30
                  das_ittrg(ittrg(itnm)+1) =  1.d+30

                  call moddas_reallocate_dbl(
     &                    3, icurrent_gmsh, 2, iaddress_gmsh, gmsh)
                  gmsh(iaddress_gmsh(icurrent_gmsh)  ) = -1.d+30
                  gmsh(iaddress_gmsh(icurrent_gmsh)+1) =  1.d+30
                  iaddress_gmsh(2) = iaddress_gmsh(3)
                  icurrent_gmsh = 2

               end if

*-----------------------------------------------------------------------
*        transformation
*-----------------------------------------------------------------------

                     itmtr(itnm,1) = igkst
                     itmtr(itnm,2) = ktrs
                     itmtr(itnm,3) = idtt
                     itmtr(itnm,4) = 0

               if( igkst .gt. 1 ) then

                  do k = 1, 13

                     rtmtr(itnm,k) = vtrs(k)

                  end do

               end if

*-----------------------------------------------------------------------
*        reg echo length
*-----------------------------------------------------------------------

                  iterl(itnm) = iechrl

*-----------------------------------------------------------------------
*        unit
*-----------------------------------------------------------------------

                  itunt(itnm) = iunt

*-----------------------------------------------------------------------
*        2d-type
*-----------------------------------------------------------------------

                  ittwo(itnm) = idtyp

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

                  rtfac(itnm) = rfact

*-----------------------------------------------------------------------
*        dresol: T.Sato 2014/8/19
*-----------------------------------------------------------------------

                  rtdre(itnm) = dreso

*-----------------------------------------------------------------------
*        dfano:  T.Sato 2014/8/28
*-----------------------------------------------------------------------

                  rtdfa(itnm) = dfan

*-----------------------------------------------------------------------
*        volmat
*-----------------------------------------------------------------------

                  itvm(itnm) = matvol

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

                  iteps(itnm) = ieps

*-----------------------------------------------------------------------
*        bmpout
*-----------------------------------------------------------------------

                  itbmp(itnm) = ibmp

*-----------------------------------------------------------------------
*        vtkout
*-----------------------------------------------------------------------

                  itvtk(itnm) = ivtk

*-----------------------------------------------------------------------
*        vtkfmt
*-----------------------------------------------------------------------

                  itvtkfmt(itnm) = ivtkfmt

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

                  itres(itnm) = max( 1, ireso )

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

                  rtwid(itnm) = width

*-----------------------------------------------------------------------
*        letmat
*-----------------------------------------------------------------------

                  itlmt(itnm) = letmat

*-----------------------------------------------------------------------
*        counter
*-----------------------------------------------------------------------

               do i = 1, 9

                  itcnt(i,itnm) = icount(i)
                  itcnth(i,itnm) = icounth(i) !frtati 2021/03/05

               end do

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

                  itaxn(itnm) = inaxi

               do i = 1, inaxi

                  itaxs(itnm,i) = iaxis(i)

               end do

*-----------------------------------------------------------------------
*        stdcut
*-----------------------------------------------------------------------
                  rtstd(itnm) = stdcut

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

                  itger(itnm) = infog

*-----------------------------------------------------------------------
*        deposit option
*-----------------------------------------------------------------------

                  itdpo(itnm) = idepo

*-----------------------------------------------------------------------
*        nlatcel and nlatmem
*-----------------------------------------------------------------------

                  itnlatcel(itnm) = nlatcel

                  if( nlatcel .eq. 0 ) then
                     itnlatmem(itnm) = 1
                  else
                     itnlatmem(itnm) = nlatmem
                  endif

*-----------------------------------------------------------------------
*        foamout
*-----------------------------------------------------------------------
                  itfoam(itnm) = ifoam

*-----------------------------------------------------------------------
*        maxangel
*-----------------------------------------------------------------------
                  itmxang(itnm) = imxang

*-----------------------------------------------------------------------
*        samepage
*-----------------------------------------------------------------------
                  itpgn(itnm) = inpgi

               do i = 1, inpgi

                  itpgs(itnm,i) = ipgis(i)

               end do

*-----------------------------------------------------------------------
*        file
*-----------------------------------------------------------------------

                  itfln(itnm) = infil

               do i = 1, infil

                  itfll(itnm,i) = lfile(i)

                  ctfln(itnm,i)(1:lfile(i)) = ifile(i)(1:lfile(i))

                  do k = lfile(i) + 1, 100

                     ctfln(itnm,i)(k:k) = ' '

                  end do

               end do

*-----------------------------------------------------------------------
*        mother
*-----------------------------------------------------------------------

                  itman(itnm) = imoth
                  itmct(itnm) = jmoth

               if( imoth .gt. 0 ) then

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( imoth + mod(imoth,2) ) / 2

               end if

*-----------------------------------------------------------------------
*       restart file
*-----------------------------------------------------------------------

               call summary_param_resfile(itnm,irfflg,lrfile,irfile)

*-----------------------------------------------------------------------
*        output and dimension
*-----------------------------------------------------------------------

                  itout(itnm) = iout

*-----------------------------------------------------------------------
*     summary for anatally
*-----------------------------------------------------------------------

         if ( mstz(26) .ne. 3 ) istbat = 0 ! S.H. 2021.8.31
         if( istbat .eq. 0 ) then

                  itism(itnm) = istbat

         else if( istbat .gt. 0 ) then

            if( imesh .eq. 1 ) then
               if( ist_nm(1) .gt. 1 ) then
                  if( ist_nm(1) .gt. ntrn ) goto 967
               else if( ist_nm(1) .le. 0 ) then
                     ist_nm(1) = ntrn
                  do j = 1, ntrn
                     isd_nm(1,j) = j
                  end do
               end if
                     ist_nm(2) = 1
                     isd_nm(2,1) = 1
                     ist_nm(3) = 1
                     isd_nm(3,1) = 1
                     ist_nm(4) = 1
                     isd_nm(4,1) = 1
                     ist_nm(5) = 1
                     isd_nm(5,1) = 1
            else if( imesh .eq. 2 ) then
               if( ist_nm(4) .gt. 1 ) then
                  if( ist_nm(1) .gt. inz ) goto 967
               else if( ist_nm(4) .le. 0 ) then
                     ist_nm(4) = inz
                  do j = 1, inz
                     isd_nm(4,j) = j
                  end do
               end if
               if( ist_nm(5) .gt. 1 ) then
                  if( ist_nm(5) .gt. inr ) goto 967
               else if( ist_nm(5) .le. 0 ) then
                     ist_nm(5) = inr
                  do j = 1, inz
                     isd_nm(5,j) = j
                  end do
               end if
                     ist_nm(1) = 1
                     isd_nm(1,1) = 1
                     ist_nm(2) = 1
                     isd_nm(2,1) = 1
                     ist_nm(3) = 1
                     isd_nm(3,1) = 1
            else if( imesh .eq. 3 ) then
               if( ist_nm(2) .gt. 1 ) then
                  if( ist_nm(2) .gt. inx ) goto 967
               else if( ist_nm(2) .le. 0 ) then
                     ist_nm(2) = inx
                  do j = 1, inx
                     isd_nm(2,j) = j
                  end do
               end if
               if( ist_nm(3) .gt. 1 ) then
                  if( ist_nm(3) .gt. iny ) goto 967
               else if( ist_nm(3) .le. 0 ) then
                     ist_nm(3) = iny
                  do j = 1, iny
                     isd_nm(3,j) = j
                  end do
               end if
               if( ist_nm(4) .gt. 1 ) then
                  if( ist_nm(4) .gt. inz ) goto 967
               else if( ist_nm(4) .le. 0 ) then
                     ist_nm(4) = inz
                  do j = 1, inz
                     isd_nm(4,j) = j
                  end do
               end if
                     ist_nm(1) = 1
                     isd_nm(1,1) = 1
                     ist_nm(5) = 1
                     isd_nm(5,1) = 1
            end if

*-----------------------------------------------------------------------

               if( ist_nm(6) .gt. 1 ) then
                  if( ist_nm(6) .gt. ine ) goto 967
               else if( ist_nm(6) .le. 0 ) then
                     ist_nm(6) = ine
                  do j = 1, ine
                     isd_nm(6,j) = j
                  end do
               end if

               if( ist_nm(7) .gt. 1 ) then
                  if( ist_nm(7) .gt. ittnm(itnm) ) goto 967
               else if( ist_nm(7) .le. 0 ) then
                     ist_nm(7) = ittnm(itnm)
                  do j = 1, ittnm(itnm)
                     isd_nm(7,j) = j
                  end do
               end if

               if( ist_nm(8) .gt. 1 ) then
                  if( ist_nm(8) .gt. ina ) goto 967
               else if( ist_nm(8) .le. 0 ) then
                     ist_nm(8) = ina
                  do j = 1, ina
                     isd_nm(8,j) = j
                  end do
               end if

               if( ist_nm(9) .gt. 1 ) then
                  if( ist_nm(9) .gt. itpan(itnm) ) goto 967
               else if( ist_nm(9) .le. 0 ) then
                     ist_nm(9) = itpan(itnm)
                  do j = 1, itpan(itnm)
                     isd_nm(9,j) = j
                  end do
               end if

               if( ist_nm(10) .gt. 1 ) then
                  if( ist_nm(10) .gt. kmst(1) ) goto 967
               else if( ist_nm(10) .le. 0 ) then
                     if( kmst(1) .le. 0 ) then
                        ist_nm(10) = 1
                     else
                        ist_nm(10) = kmst(1)
                     end if
                  do j = 1, ist_nm(10)
                     isd_nm(10,j) = j
                  end do
               end if

*-----------------------------------------------------------------------

                iall = 1
            do i = 1, 10
                iall = iall * ist_nm(i)
            end do

                istbat = iall

            if( istbat .gt. kvlmax ) goto 966

*-----------------------------------------------------------------------

                jst_nm(1)  = 0
                jst_nm(2)  = jst_nm(1) + ist_nm(1)
                jst_nm(3)  = jst_nm(2) + ist_nm(2)
                jst_nm(4)  = jst_nm(3) + ist_nm(3)
                jst_nm(5)  = jst_nm(4) + ist_nm(4)
                jst_nm(6)  = jst_nm(5) + ist_nm(5)
                jst_nm(7)  = jst_nm(6) + ist_nm(6)
                jst_nm(8)  = jst_nm(7) + ist_nm(7)
                jst_nm(9)  = jst_nm(8) + ist_nm(8)
                jst_nm(10) = jst_nm(9) + ist_nm(9)
                jst_al     = jst_nm(10) + ist_nm(10)

*-----------------------------------------------------------------------

                  istbmm = ( mmmax - 1 ) * 2 + 1
                  mmmax = mmmax + ( jst_al + mod(jst_al,2) ) / 2
                  if( mmmax .gt. mdas ) goto 950

                  itstt(itnm) = istbmm
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( jst_al + mod(jst_al,2) ) / 2

                  itism(itnm) = istbat

            do i = 1, 10
                  itist(i,itnm) = ist_nm(i)
                  itjst(i,itnm) = jst_nm(i)
                  itkst(i,itnm) = kst_nm(i)
            end do

            do i = 1, 10
               do k = 1, itist(i,itnm)
                  idas( itstt(itnm) + itjst(i,itnm) + k ) = isd_nm(i,k)
               end do
            end do

         end if

*-----------------------------------------------------------------------

      return

*-----------------------------------------------------------------------
*     errors
*-----------------------------------------------------------------------

  950    write(dkam,'(i9)') mdas
         m_err = 'Total tally storage number exceeds mdas ='//dkam
         ErrCha = ''
         ErrID = 'L:13400/R:anatal_tdeposit/F:anatally.f'
         goto 999

  966    m_err = 'total # of points exceeds kvlmax in anatally.'//tname
         ErrCha = ''
         ErrID = 'L:13405/R:anatal_tdeposit/F:anatally.f'
         goto 999

  967    m_err = 'something wrong in anatally parameters.'//tname
         ErrCha = ''
         ErrID = 'L:13410/R:anatal_tdeposit/F:anatally.f'
         goto 999

  973  m_err = 'material ID used in LETMAT is not defined in [material]'
       ErrCha = ''
       ErrID = 'L:13415/R:anatal_tdeposit/F:anatally.f'
         goto 999

  976    m_err = 'dedxfnc should be 0, 1, 2'
         ErrCha = ''
         ErrID = 'L:13420/R:anatal_tdeposit/F:anatally.f'
         goto 999

  978    m_err = 'counter should be from -9999 to 9999'
         ErrCha = ''
         ErrID = 'L:13425/R:anatal_tdeposit/F:anatally.f'
         goto 999

  979    m_err = 'Description of material parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:13431/R:anatal_tdeposit/F:anatally.f'
         goto 999

  982    m_err = 'Description of mother parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:13437/R:anatal_tdeposit/F:anatally.f'
         goto 999

  983    m_err = '2D-type should be 1-7 in tally '//tname
         ErrCha = ''
         ErrID = 'L:13442/R:anatal_tdeposit/F:anatally.f'
         goto 999

  984    m_err = 'Number of particle except "all" is larger than 5 '//
     &           'in tally '//tname//' with output = deposit'
         ErrCha = ''
         ErrID = 'L:13448/R:anatal_tdeposit/F:anatally.f'
         goto 999

  985    m_err = 'Neutral particles do not deposit energy. Consider part
     & = electron positron proton nucleus, for example.'
         ErrCha = ''
         ErrID = 'L:13454/R:anatal_tdeposit/F:anatally.f'
         goto 999

  986    write(dkam,'(i5)') itlmax
         m_err = 'Total tally number exceeds itlmax = '//dkam
         ErrCha = ''
         ErrID = 'L:13460/R:anatal_tdeposit/F:anatally.f'
         goto 999

  987    m_err = 'Unknown parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:13465/R:anatal_tdeposit/F:anatally.f'
         goto 999
  988    m_err = 'Unit should be 0 - 5 in tally '//tname
         ErrCha = ''
         ErrID = 'L:13469/R:anatal_tdeposit/F:anatally.f'
         goto 999

  989    m_err = 'Double definition of the parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:13474/R:anatal_tdeposit/F:anatally.f'
         goto 999

  990    m_err = 'Too many file name in tally '//tname
         ErrCha = ''
         ErrID = 'L:13479/R:anatal_tdeposit/F:anatally.f'
         goto 999

  991    m_err = 'Too many axis in tally '//tname
         ErrCha = ''
         ErrID = 'L:13484/R:anatal_tdeposit/F:anatally.f'
         goto 999

  992    m_err = 'Unknown axis name in tally '//tname
         ErrCha = ''
         ErrID = 'L:13489/R:anatal_tdeposit/F:anatally.f'
         goto 999

  993    m_err = 'In this line, [ ; ] cannot be used.'
         ErrCha = ''
         ErrID = 'L:13494/R:anatal_tdeposit/F:anatally.f'
         goto 999

  994    m_err = 'Name of particle is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:13499/R:anatal_tdeposit/F:anatally.f'
         goto 999

cfrtati 2021/10/05 6 -> mxpart
  995    m_err = 'Number of particles is larger than mxpart in '//tname
         ErrCha = ''
         ErrID = 'L:13505/R:anatal_tdeposit/F:anatally.f'
         goto 999

  996    m_err = 'Description of mesh is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:13510/R:anatal_tdeposit/F:anatally.f'
         goto 999

  997    m_err = 'Description of parameter is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:13515/R:anatal_tdeposit/F:anatally.f'
         goto 999

  998    m_err = 'Unknown mesh parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:13520/R:anatal_tdeposit/F:anatally.f'
         goto 999

 1045    m_err = 'Too many samepage in tally '//tname
         ErrCha = ''
         ErrID = 'L:13525/R:anatal_tdeposit/F:anatally.f'
         goto 999

 1046    m_err = 'samepage should be wwg, reg,eng,t,xy,yz,zx,x,y,z'
     &           //' in tally '//tname
         ErrCha = ''
         ErrID = 'L:13531/R:anatal_tdeposit/F:anatally.f'
         goto 999

*-----------------------------------------------------------------------

  999 continue

         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1

*-----------------------------------------------------------------------

      return
      end subroutine anatal_tdeposit


************************************************************************
*                                                                      *
      subroutine anatal_tlet(jsn,jsi,dsin,idsi,ill,ilf,
     &                       jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)
*                                                                      *
*       read [t-let] section of tally files                            *
*       modified by K.Niita on 2005/08/31                              *
*                                                                      *
************************************************************************
      use sangelmod, only: itsanf
      use anatallymod, only: nanatalRead
      use partmod ! frtati 2021/10/05
      use moddas
      use moddas_mesh
      use moddas_region
      use moddas_tally

      implicit real*8 (a-h,o-z)

      parameter(icsu=43) ! nais 2023/01/06

      include 'param.inc'
      include 'param01.inc' ! frtati 2021/10/05
      include 'err.inc'

*-----------------------------------------------------------------------

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)

      common /tall02/ itrgn(itlmax), itrgm(itlmax), itreg(itlmax)
      common /tall25/ itrnv(itlmax), itriv(itlmax), itrrv(itlmax)

      common /tall03/ itrty(itlmax), itrnm(itlmax), itrrg(itlmax),
     &                rtrmi(itlmax), rtrma(itlmax), rtrdl(itlmax)
      common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &                rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)
      common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &                rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)

      common /tall08/ rtrx0(itlmax), rtry0(itlmax)

      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80

      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall19/ itsmn(itlmax), itstm(itlmax)

      common /tall21/ rtfac(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)

      common /tall28/ itgsh(itlmax)
      common /tall29/ itrsh(itlmax)
      common /tall31/ iterl(itlmax)
      common /tall34/ itvm(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall37/ itcnt(9,itlmax)

      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)

      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

      common /tall49/ itglt(itlmax)
      common /tall50/ itlmt(itlmax), ite2l(itlmax)   ! CCSE 2022.08.31

!OBINATA: for resfile
      common /tall59/ irfll(itlmax), crfln(itlmax), itrff(itlmax)
      character crfln*100
      character irfile*100

      common /tall60/ itger(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /paraj/  mstz(300), parz(300) ! S.H. 2020.2.25

      common /kmat1d/ idmn(0:kvlmax), idnm(kvmmax)

      common /tall82/ itcnth(9,itlmax)
      dimension icounth(9)

! 20230106 nais samepage
      common /tall90/ itpgn(itlmax), itpgs(itlmax,6)

      dimension idas(mdas*2)
      equivalence ( das, idas )


*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

*-----------------------------------------------------------------------

      character title*80
      character angelp*200
      character cxtxt*200
      character cytxt*200
      character cztxt*200

*-----------------------------------------------------------------------

      dimension lschn(icsu), ischn(icsu)
      character schan(icsu)*8


      data ( schan(i), i = 1, icsu ) /
     &    'mesh    ','part    ','l-type  ','unit    ','axis    ',
     &    'file    ','title   ','angel   ','2d-type ','factor  ',
     &    'x-txt   ','y-txt   ','z-txt   ','gshow   ','rshow   ',
     &    'iechrl  ','material','epsout  ','ctmin(1)','ctmax(1)',
     &    'ctmin(2)','ctmax(2)','ctmin(3)','ctmax(3)','resol   ',
     &    'width   ','trcl    ','*trcl   ','gslat   ','letmat  ',
     &    'volmat  ','resfile ','ginfo   ','stdcut  ','sangel  ',
     &    'chmin(1)','chmax(1)','chmin(2)','chmax(2)','chmin(3)',
     &    'chmax(3)','maxangel','samepage'/

      data ( lschn(i), i = 1, icsu ) /
     &     4,         4,         6,         4,         4,
     &     4,         5,         5,         7,         6,
     &     5,         5,         5,         5,         5,
     &     6,         8,         6,         8,         8,
     &     8,         8,         8,         8,         5,
     &     5,         4,         5,         5,         6,
     &     6,         7,         5,         6,         6,
     &     8,         8,         8,         8,         8,
     &     8,         8,         8/

*-----------------------------------------------------------------------

cfrtati 2021/10/05 6 -> mxpart
      dimension iptyp(mxpart), ipnkf(mxpart)
      dimension imtyp(mxpart,mxpart), imnkf(mxpart,mxpart)
      dimension jstyp(mxpart), jnkf0(mxpart)
      dimension icount(9)

      common /subtra/ isubt, ipsub(mxpart)  ! kitamura22/03/31

      dimension iaxis(6)
      character ifile(6)*100
      dimension lfile(6)

      dimension ipgis(6)   ! samepage nais 2023/01/06

*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200
      character chlc*200

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

      character dkam*9

      character tname*7
      data      tname /'[t-let]'/

      logical deqn4

      integer isumtalRead

*-----------------------------------------------------------------------

      dimension jptyp(6), jpnkf(6)
      dimension kptyp(6,6), kpnkf(6,6)
      dimension vtrs(13)

*-----------------------------------------------------------------------

            ierr  = 0

            iunt  = 1
            imate = 0
            jmate = 1
            inpat = 0
            inaxi = 0
            infil = 0
            idtyp = 3

            langel = 0
            itsanf = 0
            lxtxt  = 0
            lytxt  = 0
            lztxt  = 0
            lgshow = 0
            lrshow = 0
            iechrl = 72
            matvol = 9
            ieps   = 0
            igkst  = 0
            idtt   = 0
            ktrs   = 0
            igslt  = -1
            letmat = 0
            lrfile = 0 !OBINATA
            irfflg = 0 !OBINATA
            imxang = 0 ! frtati 2021/10/05

            icount(1) = 0
            icount(2) = 0
            icount(3) = 0
            icount(4) = -9999
            icount(5) =  9999
            icount(6) = -9999
            icount(7) =  9999
            icount(8) = -9999
            icount(9) =  9999
            icounth(1) = 0
            icounth(2) = 0
            icounth(3) = 0
            icounth(4) = -9999
            icounth(5) =  9999
            icounth(6) = -9999
            icounth(7) =  9999
            icounth(8) = -9999
            icounth(9) =  9999

            rfact = 1.0

            ireso = 1
            width = 0.5

         do i = 1, icsu

            ischn(i) = 0

         end do

            infog = 0

         inpgi = 0   ! samepage 2023/01/06

       isumtalRead = 0

            stdcut = -1.0

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140 continue

            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*.......................................................................
*        end of reading header info. (from tally file)
*.......................................................................
            if( i1 .ne. 0 ) then !20221004frtati fbounds-check
              if( mstz(1) .eq. 17 .and.
     &           chin(i1:i1+25) .eq. '#-------------------------' ) then
                 jpn = 1
                 goto 800
              end if
            end if

               if( iskip .ne. 0 ) goto 140

  150 continue

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*-----------------------------------------------------------------------
*        end of the section
*-----------------------------------------------------------------------

            if( chlw(i1:i1) .eq. '[' ) then

               jpn = 1
               goto 800

            end if

*-----------------------------------------------------------------------
*        identify the parameters
*-----------------------------------------------------------------------

            icl = i1

!-----------------------------------------------------------------------
!        sumtally sub section
!-----------------------------------------------------------------------
      if ( chlw(i1:i3) .eq. 'sumtally start' ) then
       isumtalRead = 1
       call read_sumtal(jsn,jsi,dsin,idsi,ill,ilf,
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
       if( ierr .ne. 0 ) return
       if( jpn == 3 ) goto 800   ! 'q:'
       if( jpn == 1 ) goto 800   ! end of the section
       go to 140
      end if

*-----------------------------------------------------------------------
*        anatally
*-----------------------------------------------------------------------

      if ( chlw(i1:i3) .eq. 'anatally start' ) then

         if (  mstz(1) .eq. 17 ) then
            nanatalRead(1+itnm) = 1
            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &           jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
            if ( chlw(i1:i3) .ne. 'anatally end' ) then
               ierr = 1
            end if
         else

            istbat = 1

            call stbatm(jsn,jsi,dsin,idsi,ill,ilf,
     &                  jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                  ist_nm,isd_nm,kst_nm)

            if( ierr .ne. 0 ) return
            if( jpn == 3 ) goto 800   ! 'q:'
            if( jpn == 1 ) goto 800   ! end of the section

         end if ! S.H. (2020.2.25)
            goto 140

      end if

*-----------------------------------------------------------------------

  200    continue

            chlc = chlw
            call chcomp(chlc,icl,i3,i5)

         do i = 1, icsu

            il = icl + lschn(i) - 1

            if( chlc(icl:il) .eq. schan(i)(1:lschn(i)) ) goto 100

         end do

               goto 987

*-----------------------------------------------------------------------
*        read value of parameters
*-----------------------------------------------------------------------

  100    continue

               ipm = i

               ischn( ipm ) = ischn( ipm ) + 1

            if( ipm .ne.  5 .and. ipm .ne. 6 .and.
     &          ipm .ne.  2 .and. ipm .ne. 32 .and.
     &          ischn( ipm ) .gt. 1 ) goto 989

               ic = inumc(chlw,il+1,i3,'=') + 1
               ic = jnumc(chlw,ic,i3)

               if( ic .gt. i3 ) goto 997

               icl = inumc(chlw,ic,i3,';') - 1

*-----------------------------------------------------------------------
*        mesh = region, r-z, or xyz
*-----------------------------------------------------------------------

         if( ipm .eq. 1 ) then

            if( chlw(ic:ic+2) .eq. 'reg' ) then

               imesh = 1

            else if( chlw(ic:ic+2) .eq. 'r-z' ) then

               imesh = 2

            else if( chlw(ic:ic+2) .eq. 'xyz' ) then

               imesh = 3

            else

               goto 998

            end if

            if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

            if( imesh .eq. 1 ) then

               call moddas_allocate_int(
     &                 MAX_NUM_ITREG, idas_itreg_temporary)

               ndsm = 1
               call tregion(1,jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ntrn,mtrn,ndsm,nvol,ivl,irvl,0
     &                      ,MAX_NUM_ITREG,idas_itreg_temporary)

               if( mtrn > MAX_NUM_ITREG ) then
                  write(ErrCha,'(a,a,i5,a,a,i5,a)')
     &                 'sub.tlet@tallsm2.f'
     &                    //' ?dimension over idas_itreg_temporary?'
     &                    //' mtrn > MAX_NUM_ITREG'
     &                 ,' (mtrn=',mtrn,')'
     &                 ,' (MAX_NUM_ITREG@moddas.f=',MAX_NUM_ITREG,')'
                  ErrID = 'L:13976/R:anatal_tlet/F:anatally.f'
                  call ErrWrite(ErrID,ErrCha)
               endif

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ntrn .lt. -1 ) goto 996

            else if( imesh .eq. 2 ) then

               call trzmesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      rzx0,rzy0,
     &                      irtp,inr,rmin,rmax,rdel,istrg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( irtp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            else if( imesh .eq. 3 ) then

               call txymesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ixtp,inx,xmin,xmax,xdel,istxg,
     &                      iytp,iny,ymin,ymax,ydel,istyg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ixtp .lt. 0 ) goto 996
                  if( iytp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            end if

                  goto 150

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

         else if( ipm .eq. 2 ) then

  400       continue

               ic = jnumc(chlw,ic,icl)

               if( ic .gt. icl ) then

                  icl = jnumc(chlw,icl+2,i3)

                  if( icl .le. i3 ) goto 200

                  goto 140

               end if

*-----------------------------------------------------------------------

            call rdpname(ic,icl,chlw,istyp,inkf0,jstyp,jnkf0,ierr)

               if( ierr .eq. 994 ) goto 994
               if( ierr .eq. 998 ) goto 997

*-----------------------------------------------------------------------

               inpat = inpat + 1

               if( inpat .gt. mxpart ) goto 995

                  iptyp(inpat) = istyp
                  ipnkf(inpat) = inkf0
                  ipsub(inpat) = isubt  ! kitamura22/03/31

               if( istyp .lt. 0 ) then

                  do i = 1, -istyp

                     imtyp(inpat,i) = jstyp(i)
                     imnkf(inpat,i) = jnkf0(i)

                  end do

               end if

               goto 400

*-----------------------------------------------------------------------
*        material
*-----------------------------------------------------------------------

         else if( ipm .eq. 17 ) then

            if( chlw(ic:ic+2) .eq. 'all' ) then

                  imate = 0

            else if( deqn4( chlw(ic:ic) ) ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 979

                  imate = nint( cvvv )

               if( imate .lt. 0 ) then

                  imate = -imate
                  jmate = -1

               end if

               if( imate .eq. 0 ) goto 979

                  nsmte = itmtt(itnm+1)
                  call moddas_reallocate_int(
     &                    itlmax, itnm+1, imate, itmtt, ismte)
                  if( mmmax .gt. mdas ) goto 950

  151                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                        if( ierr .ne. 0 ) return
                        if( jpn  .eq. 3 ) goto 979

                        if( iskip .ne. 0 ) goto 151

                  ic = i1

               do k = 1, imate

                  if( ic .gt. i3 ) then

  152                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                     if( ierr .ne. 0 ) return
                     if( jpn  .eq. 3 ) goto 979

                     if( iskip .ne. 0 ) goto 152

                     ic = i1

                  end if

                     ic = jnumc(chlw,ic,i3)

                     call snum(chlw,ic,i3,ic2,cvvv,ierr)

                     if( ierr .ne. 0 ) goto 979

                     matei = nint( cvvv )

                     ic = ic2

                     ismte(nsmte-1+k) = matei

               end do

            else

               goto 979

            end if

*-----------------------------------------------------------------------
*        let mesh
*-----------------------------------------------------------------------

         else if( ipm .eq. 3 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

               ietp = nint( cvvv )

               call getmsh(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     'l',ietp,ine,emin,emax,edel,isteg)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        transform
*-----------------------------------------------------------------------

         else if( ipm .eq. 27 .or. ipm .eq. 28 ) then

                  if( ipm .eq. 28 ) ktrs = 1

               call ttrans(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     ic,ktrs,igkst,idtt,vtrs)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        unit
*-----------------------------------------------------------------------

         else if( ipm .eq. 4 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               iunt = nint( cvvv )

               if( iunt .lt. 1 .or.
     &             iunt .gt. 14 ) goto 988  ! T.Sato 2017/11/21

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

         else if( ipm .eq. 5 ) then

  600       inaxi = inaxi + 1

            if( inaxi .gt. 6 ) goto 991

            if( chlw(ic:ic+2) .eq. 'let' ) then

               iaxis(inaxi) = 1
               ic =jnumc(chlw,ic+4,icl)

            else if( chlw(ic:ic+2) .eq. 'reg' ) then

               iaxis(inaxi) = 2
               ic =jnumc(chlw,ic+4,icl)

            else if( chlw(ic:ic+1) .eq. 'xy' .or.
     &               chlw(ic:ic+1) .eq. 'yx' ) then

               iaxis(inaxi) = 7
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic+1) .eq. 'yz' .or.
     &               chlw(ic:ic+1) .eq. 'zy' ) then

               iaxis(inaxi) = 8
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic+1) .eq. 'zx' .or.
     &               chlw(ic:ic+1) .eq. 'xz' ) then

               iaxis(inaxi) = 9
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic+1) .eq. 'rz' .or.
     &               chlw(ic:ic+1) .eq. 'zr' ) then

               iaxis(inaxi) = 10
               ic =jnumc(chlw,ic+3,icl)

            else if( chlw(ic:ic) .eq. 'x' ) then

               iaxis(inaxi) = 3
               ic =jnumc(chlw,ic+2,icl)

            else if( chlw(ic:ic) .eq. 'y' ) then

               iaxis(inaxi) = 4
               ic =jnumc(chlw,ic+2,icl)

            else if( chlw(ic:ic) .eq. 'z' ) then

               iaxis(inaxi) = 5
               ic =jnumc(chlw,ic+2,icl)

            else if( chlw(ic:ic) .eq. 'r' ) then

               iaxis(inaxi) = 6
               ic =jnumc(chlw,ic+2,icl)

            else

               goto 992

            end if

               if( ic .le. icl ) goto 600

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        file name
*-----------------------------------------------------------------------

         else if( ipm .eq. 6 ) then

  700          infil = infil + 1

               if( infil .gt. 6 ) goto 990

               icf = min( inumc(chlw,ic,icl,' ') - 1, icl )

               lfile(infil) = icf - ic + 1
               ifile(infil)(1:icf-ic+1) = chin(ic:icf)

               ic = jnumc(chlw,icf+2,icl)

               if( ic .le. icl ) goto 700

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        restart file name
*-----------------------------------------------------------------------
         else if( ipm .eq. 32 ) then

               call found_param_resfile(itnm,
     &                                  irfflg,ic,icl,chlw,chin,
     &                                  lrfile, irfile)

*-----------------------------------------------------------------------
*        title
*-----------------------------------------------------------------------

         else if( ipm .eq. 7 ) then

               ict = min( ic + 79, i2 )

               title = chin(ic:ict)

               titll = ict - ic + 1

*-----------------------------------------------------------------------
*        angel parameters
*-----------------------------------------------------------------------

         else if( ipm .eq. 8 ) then

               ict = min( ic + 199, i2 )

               angelp = chin(ic:ict)

               langel = ict - ic + 1

!-----------------------------------------------------------------------
!        sangel parameters
!-----------------------------------------------------------------------

         else if( ipm .eq. 35 ) then

            itsanf = itsanf + 1

            call read_sangel(jsn,jsi,dsin,idsi,ill,ilf,
     &                       jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr
     &                      ,ic ,icl ,tname)
            if( ierr .ne. 0 ) return

*-----------------------------------------------------------------------
*        x-txt
*-----------------------------------------------------------------------

         else if( ipm .eq. 11 ) then

               ict = min( ic + 199, i2 )

               cxtxt = chin(ic:ict)

               lxtxt = ict - ic + 1

*-----------------------------------------------------------------------
*        y-txt
*-----------------------------------------------------------------------

         else if( ipm .eq. 12 ) then

               ict = min( ic + 199, i2 )

               cytxt = chin(ic:ict)

               lytxt = ict - ic + 1

*-----------------------------------------------------------------------
*        z-txt
*-----------------------------------------------------------------------

         else if( ipm .eq. 13 ) then

               ict = min( ic + 199, i2 )

               cztxt = chin(ic:ict)

               lztxt = ict - ic + 1

*-----------------------------------------------------------------------
*        gshow
*-----------------------------------------------------------------------

         else if( ipm .eq. 14 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               lgshow = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        gslat
*-----------------------------------------------------------------------

         else if( ipm .eq. 29 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               igslt = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        rshow
*-----------------------------------------------------------------------

         else if( ipm .eq. 15 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               lrshow = nint( cvvv )

               if( lrshow .le. 0 ) then

                  lrshow = 0

                  icl = jnumc(chlw,icl+2,i3)
                  if( icl .le. i3 ) goto 200

               end if

               if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

               call txymesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ixtp,inx,xmin,xmax,xdel,istxg,
     &                      iytp,iny,ymin,ymax,ydel,istyg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ixtp .lt. 0 ) goto 996
                  if( iytp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

                  goto 150

*-----------------------------------------------------------------------
*        reg echo length
*-----------------------------------------------------------------------

         else if( ipm .eq. 16 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               iechrl = nint( cvvv )

               if( iechrl .lt. 40 ) goto 997

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        2d-type
*-----------------------------------------------------------------------

         else if( ipm .eq. 9 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               idtyp = nint( cvvv )

               if( idtyp .lt. 1 .or. idtyp .gt. 7 ) goto 983

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

         else if( ipm .eq. 10 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               rfact = cvvv

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

         else if( ipm .eq. 18 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               ieps = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

         else if( ipm .eq. 25 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               ireso = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

         else if( ipm .eq. 26 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               width = cvvv

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        counter
*-----------------------------------------------------------------------

         else if( ipm .ge. 19 .and. ipm .le. 24 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               icount((ipm-19+2)/2) = 1
               icount( ipm-19+4)    = nint( cvvv )

               if( abs( nint(cvvv) ) .gt. 9999 ) goto 978

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        letmat
*-----------------------------------------------------------------------

         else if( ipm .eq. 30 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               letmat = nint( cvvv )


               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        volmat
*-----------------------------------------------------------------------

         else if( ipm .eq. 31 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               matvol = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

         else if( ipm .eq. 33 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               infog = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        stdcut
*-----------------------------------------------------------------------

         else if( ipm .eq. 34 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               stdcut = cvvv

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        history counter
*-----------------------------------------------------------------------
         else if( ipm .ge. 36 .and. ipm .le. 41 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               icounth((ipm-36+2)/2) = 1
               icounth( ipm-36+4)    = nint( cvvv )

               if( abs( nint(cvvv) ) .gt. 9999 ) goto 978

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        maxangel
*-----------------------------------------------------------------------
         else if( ipm .eq. 42 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               imxang = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        samepage       nais 2023/01/6
*-----------------------------------------------------------------------

         else if( ipm .eq. 43 ) then

            call setsamepage(inpgi,ipgis,ic,chlw,icl, ierr)

            if( ierr .eq. 1 ) goto 1045
            if( ierr .eq. 2 ) goto 1046

            icl = jnumc(chlw,icl+2,i3)

            if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------

         end if

            goto 140

*-----------------------------------------------------------------------
*     check
*-----------------------------------------------------------------------

  800 continue

      if( ischn(7) .eq. 0 ) then

         if( imesh .eq. 1 ) then

            title = '[t-let] in region mesh'
            titll = 22

         else if( imesh .eq. 2 ) then

            title = '[t-let] in r-z mesh'
            titll = 19

         else if( imesh .eq. 3 ) then

            title = '[t-let] in xyz mesh'
            titll = 19

         end if

      end if

      if( ischn(1) .eq. 0 ) then

         m_err = 'Mesh is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:14719/R:anatal_tlet/F:anatally.f'
         goto 999

      else if( ischn(3) .eq. 0 ) then

         m_err = 'L-type is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:14726/R:anatal_tlet/F:anatally.f'
         goto 999

      else if( inaxi .eq. 0 ) then

         m_err = 'Axis is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:14733/R:anatal_tlet/F:anatally.f'
         goto 999

      else if( infil .eq. 0 ) then

         m_err = 'File is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:14740/R:anatal_tlet/F:anatally.f'
         goto 999

      else if( inaxi .ne. infil ) then

         m_err = 'Number of Axis and File is different in tally '//tname
         ErrCha = ''
         ErrID = 'L:14747/R:anatal_tlet/F:anatally.f'
         goto 999

      else if( itsanf > 1 ) then

         m_err = 'Double definition of sangel is found in tally '//tname
         ErrCha = ''
         ErrID = 'L:14754/R:anatal_tlet/F:anatally.f'
         goto 999

      end if

      do i = 1, inaxi

         if( lrshow .eq. 0 ) then

            if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 8 .or.
     &            iaxis(i) .eq. 9 ) .and. imesh .ne. 3 ) then

               m_err = 'Axis is xy, yz, or zx, '//
     &                 'but mesh is not xyz in tally '//tname
               ErrCha = ''
               ErrID = 'L:14769/R:anatal_tlet/F:anatally.f'
               goto 999

            end if

         end if

         if( iaxis(i) .eq. 2 .and. imesh .ne. 1 ) then

            m_err = 'Axis is reg but mesh is not reg in tally '//tname
            ErrCha = ''
            ErrID = 'L:14780/R:anatal_tlet/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 3 .and. imesh .ne. 3 ) then

            m_err = 'Axis is x but mesh is not xyz in tally '//tname
            ErrCha = ''
            ErrID = 'L:14787/R:anatal_tlet/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 4 .and. imesh .ne. 3 ) then

            m_err = 'Axis is y but mesh is not xyz in tally '//tname
            ErrCha = ''
            ErrID = 'L:14794/R:anatal_tlet/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 5 .and. imesh .eq. 1 ) then

            m_err = 'Axis is z but mesh is reg in tally '//tname
            ErrCha = ''
            ErrID = 'L:14801/R:anatal_tlet/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 6 .and. imesh .ne. 2 ) then

            m_err = 'Axis is r but mesh is not r-z in tally '//tname
            ErrCha = ''
            ErrID = 'L:14808/R:anatal_tlet/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 10 .and. imesh .ne. 2 ) then

            m_err = 'Axis is rz but mesh is not r-z in tally '//tname
            ErrCha = ''
            ErrID = 'L:14815/R:anatal_tlet/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 10 .and.
     &           ( irtp .ne. 2 .and. irtp .ne. 4 ) ) then

            m_err = 'Axis is rz,'//
     &              ' but r mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:14824/R:anatal_tlet/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 10 .and.
     &           ( iztp .ne. 2 .and. iztp .ne. 4 ) ) then

            m_err = 'Axis is rz,'//
     &              ' but z mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:14833/R:anatal_tlet/F:anatally.f'
            goto 999

         else if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 9 ) .and.
     &           ( ixtp .ne. 2 .and. ixtp .ne. 4 ) ) then

            m_err = 'Axis is xy or zx,'//
     &              ' but x mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:14842/R:anatal_tlet/F:anatally.f'
            goto 999

         else if( ( iaxis(i) .eq. 8 .or. iaxis(i) .eq. 9 ) .and.
     &           ( iztp .ne. 2 .and. iztp .ne. 4 ) ) then

            m_err = 'Axis is yz or zx,'//
     &              ' but z mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:14851/R:anatal_tlet/F:anatally.f'
            goto 999

         else if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 8 ) .and.
     &           ( iytp .ne. 2 .and. iytp .ne. 4 ) ) then

            m_err = 'Axis is xy or yz,'//
     &              ' but y mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:14860/R:anatal_tlet/F:anatally.f'
            goto 999

         end if

      end do

*-----------------------------------------------------------------------
*     summary
*-----------------------------------------------------------------------

                  itnm = itnm + 1

                  if( itnm .gt. itlmax ) goto 986

                  ital( itnm ) = 12

                  itsmn(itnm) = 0
                  itstm(itnm) = 0

                  itxnm(itnm) = 0
                  itynm(itnm) = 0
                  itznm(itnm) = 0

*-----------------------------------------------------------------------
*        title
*-----------------------------------------------------------------------

                  ittll(itnm) = titll
                  ittle(itnm) = title

*-----------------------------------------------------------------------
*        angel parameter
*-----------------------------------------------------------------------

               if( langel .gt. 0 ) then

                  itanl(itnm) = langel
                  itang(itnm) = angelp

               else

                  itanl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        x-txt parameter
*-----------------------------------------------------------------------

               if( lxtxt .gt. 0 ) then

                  itaxl(itnm) = lxtxt
                  itaxt(itnm) = cxtxt

               else

                  itaxl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        y-txt parameter
*-----------------------------------------------------------------------

               if( lytxt .gt. 0 ) then

                  itayl(itnm) = lytxt
                  itayt(itnm) = cytxt

               else

                  itayl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        z-txt parameter
*-----------------------------------------------------------------------

               if( lztxt .gt. 0 ) then

                  itazl(itnm) = lztxt
                  itazt(itnm) = cztxt

               else

                  itazl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        gshow parameter
*-----------------------------------------------------------------------

               if( lgshow .gt. 0 ) then

                  itgsh(itnm) = min(5,lgshow)  ! T.Sato 2019/02/20

               else

                  itgsh(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        gslat parameter
*-----------------------------------------------------------------------
                  itglt(itnm) = igslt

*-----------------------------------------------------------------------
*        rshow parameter
*-----------------------------------------------------------------------

                  itrsh(itnm) = min(4,lrshow)

*-----------------------------------------------------------------------
*        mesh
*-----------------------------------------------------------------------

                  itmsh(itnm) = imesh

         if( imesh .eq. 1 ) then

                  itrgn(itnm) = ntrn
                  itrgm(itnm) = mtrn
                  itrnv(itnm) = nvol

            if( ntrn .gt. 0 ) then

                  call moddas_reallocate_int(
     &                    itlmax, itnm, mtrn, itreg, idas_itreg)
                  idas_itreg(itreg(itnm):itreg(itnm)+mtrn-1)
     &                      = idas_itreg_temporary(1:mtrn)
                  call moddas_deallocate_int(idas_itreg_temporary)

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( mtrn + mod(mtrn,2) ) / 2

            end if

            if( nvol .gt. 0 ) then

                  itriv(itnm) = ivl
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( nvol + mod(nvol,2) ) / 2

                  itrrv(itnm) = irvl
                  itsmn(itnm) = itsmn(itnm) + nvol

            end if

         end if

         if( imesh .eq. 2 ) then

                  rtrx0(itnm) = rzx0
                  rtry0(itnm) = rzy0

                  itrty(itnm) = irtp
                  itrnm(itnm) = inr
                  rtrdl(itnm) = rdel
                  rtrmi(itnm) = rmin
                  rtrma(itnm) = rmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inr+1, itrrg, das_itrrg)
                  das_itrrg(itrrg(itnm):itrrg(itnm)+inr)
     &                     = gmsh(istrg:istrg+inr)

                  itsmn(itnm) = itsmn(itnm) + inr + 1


                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)

                  itsmn(itnm) = itsmn(itnm) + inz + 1

         else if( imesh .eq. 3 .or. lrshow .gt. 0 ) then

                  itxty(itnm) = ixtp
                  itxnm(itnm) = inx
                  rtxdl(itnm) = xdel
                  rtxmi(itnm) = xmin
                  rtxma(itnm) = xmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inx+1, itxrg, das_itxrg)
                  das_itxrg(itxrg(itnm):itxrg(itnm)+inx)
     &                     = gmsh(istxg:istxg+inx)
                  itsmn(itnm) = itsmn(itnm) + inx + 1

                  ityty(itnm) = iytp
                  itynm(itnm) = iny
                  rtydl(itnm) = ydel
                  rtymi(itnm) = ymin
                  rtyma(itnm) = ymax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, iny+1, ityrg, das_ityrg)
                  das_ityrg(ityrg(itnm):ityrg(itnm)+iny)
     &                     = gmsh(istyg:istyg+iny)
                  itsmn(itnm) = itsmn(itnm) + iny + 1


                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)
                  itsmn(itnm) = itsmn(itnm) + inz + 1

         end if

*-----------------------------------------------------------------------
*        material
*-----------------------------------------------------------------------

                  itmtn(itnm) = imate
                  itmcn(itnm) = jmate

            if( imate .gt. 0 ) then

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( imate + mod(imate,2) ) / 2

            end if

*-----------------------------------------------------------------------
*        particles
*-----------------------------------------------------------------------

            itmxptt = inpat
            itmxgpt = 1
            do i = 1, inpat
              if ( iptyp(i).lt.0 .and. -iptyp(i).gt.itmxgpt ) then
                itmxgpt = -iptyp(i)
              end if
            end do
            call ALLOCATE_PART_TEMP

            if( inpat .gt. 0 ) then

                  itpan(itnm) = inpat

               do i = 1, inpat

                  itpat(itnm,i,1) = iptyp(i)
                  itpat(itnm,i,2) = ipnkf(i)
                  itpat(itnm,i,3) = ipsub(i)  ! kitamura22/03/31

                  if( itpat(itnm,i,1) .lt. 0 ) then

                     do k = 1, -itpat(itnm,i,1)

                        jtpat(itnm,i,k,1) = imtyp(i,k)
                        jtpat(itnm,i,k,2) = imnkf(i,k)

                     end do

                  end if

               end do

            else if( inpat .eq. 0 ) then

                  itpan(itnm) = 1
                  itpat(itnm,1,1) = 20
                  itpat(itnm,1,2) = 0

            end if

*-----------------------------------------------------------------------
*        LET mesh
*-----------------------------------------------------------------------

                  itety(itnm) = ietp
                  itenm(itnm) = ine
                  rtedl(itnm) = edel
                  rtemi(itnm) = emin
                  rtema(itnm) = emax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, ine+1, iterg, das_iterg)
                  das_iterg(iterg(itnm):iterg(itnm)+ine)
     &                     = gmsh(isteg:isteg+ine)
                  itsmn(itnm) = itsmn(itnm) + ine + 1

               if( emin .le. 0.0d0 .and.
     &           ( iunt .eq. 3 .or. iunt .eq. 4 .or.
     &             iunt .eq. 9 .or. iunt .eq. 10 ) ) goto 976

*-----------------------------------------------------------------------
*        transformation
*-----------------------------------------------------------------------

                     itmtr(itnm,1) = igkst
                     itmtr(itnm,2) = ktrs
                     itmtr(itnm,3) = idtt
                     itmtr(itnm,4) = 0

               if( igkst .gt. 1 ) then

                  do k = 1, 13

                     rtmtr(itnm,k) = vtrs(k)

                  end do

               end if

*-----------------------------------------------------------------------
*        reg echo length
*-----------------------------------------------------------------------

                  iterl(itnm) = iechrl

*-----------------------------------------------------------------------
*        unit
*-----------------------------------------------------------------------

                  itunt(itnm) = iunt

*-----------------------------------------------------------------------
*        2d-type
*-----------------------------------------------------------------------

                  ittwo(itnm) = idtyp

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

                  rtfac(itnm) = rfact

*-----------------------------------------------------------------------
*        volmat  ( unit = 4 -> vol = 1.0 then volmat = 0 )
*-----------------------------------------------------------------------

                  itvm(itnm) = matvol

                  if( iunt .ge. 1 .and. iunt .le. 6 ) itvm(itnm) = 0

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

                  iteps(itnm) = ieps

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

                  itres(itnm) = max( 1, ireso )

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

                  rtwid(itnm) = width

*-----------------------------------------------------------------------
*        letmat
*-----------------------------------------------------------------------

                  itlmt(itnm) = letmat

*-----------------------------------------------------------------------
*        counter
*-----------------------------------------------------------------------

               do i = 1, 9

                  itcnt(i,itnm) = icount(i)
                  itcnth(i,itnm) = icounth(i) !frtati 2021/04/06

               end do

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

                  itaxn(itnm) = inaxi

               do i = 1, inaxi

                  itaxs(itnm,i) = iaxis(i)

               end do

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

                  itger(itnm) = infog

*-----------------------------------------------------------------------
*        stdcut
*-----------------------------------------------------------------------
                  rtstd(itnm) = stdcut

*-----------------------------------------------------------------------
*        maxangel
*-----------------------------------------------------------------------
                  itmxang(itnm) = imxang

*-----------------------------------------------------------------------
*        samepage
*-----------------------------------------------------------------------
                  itpgn(itnm) = inpgi

               do i = 1, inpgi

                  itpgs(itnm,i) = ipgis(i)

               end do

*-----------------------------------------------------------------------
*        file
*-----------------------------------------------------------------------

                  itfln(itnm) = infil

               do i = 1, infil

                  itfll(itnm,i) = lfile(i)

                  ctfln(itnm,i)(1:lfile(i)) = ifile(i)(1:lfile(i))

                  do k = lfile(i) + 1, 100

                     ctfln(itnm,i)(k:k) = ' '

                  end do

               end do

*-----------------------------------------------------------------------
*       restart file
*-----------------------------------------------------------------------
               call summary_param_resfile(itnm,irfflg,lrfile,irfile)

*-----------------------------------------------------------------------

      return

*-----------------------------------------------------------------------
*     errors
*-----------------------------------------------------------------------

  950    write(dkam,'(i9)') mdas
         m_err = 'Total tally storage number exceeds mdas ='//dkam
         ErrCha = ''
         ErrID = 'L:15321/R:anatal_tlet/F:anatally.f'
         goto 999

  973  m_err = 'material ID used in LETMAT is not defined in [material]'
       ErrCha = ''
       ErrID = 'L:15326/R:anatal_tlet/F:anatally.f'
         goto 999

  976    m_err = 'LET mesh is Lethergy but emin is zero'
         ErrCha = ''
         ErrID = 'L:15331/R:anatal_tlet/F:anatally.f'
         goto 999

  978    m_err = 'counter should be from -9999 to 9999'
         ErrCha = ''
         ErrID = 'L:15336/R:anatal_tlet/F:anatally.f'
         goto 999

  979    m_err = 'Description of material parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:15342/R:anatal_tlet/F:anatally.f'
         goto 999

  983    m_err = '2D-type should be 1-7 in tally '//tname
         ErrCha = ''
         ErrID = 'L:15347/R:anatal_tlet/F:anatally.f'
         goto 999

  986    write(dkam,'(i5)') itlmax
         m_err = 'Total tally number exceeds itlmax = '//dkam
         ErrCha = ''
         ErrID = 'L:15353/R:anatal_tlet/F:anatally.f'
         goto 999

  987    m_err = 'Unknown parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:15358/R:anatal_tlet/F:anatally.f'
         goto 999

  988    m_err = 'Unit should be 1 - 14 in tally '//tname  ! T.Sato 2017/11/21
         ErrCha = ''
         ErrID = 'L:15363/R:anatal_tlet/F:anatally.f'
         goto 999

  989    m_err = 'Double definition of the parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:15368/R:anatal_tlet/F:anatally.f'
         goto 999

  990    m_err = 'Too many file name in tally '//tname
         ErrCha = ''
         ErrID = 'L:15373/R:anatal_tlet/F:anatally.f'
         goto 999

  991    m_err = 'Too many axis in tally '//tname
         ErrCha = ''
         ErrID = 'L:15378/R:anatal_tlet/F:anatally.f'
         goto 999

  992    m_err = 'Unknown axis name in tally '//tname
         ErrCha = ''
         ErrID = 'L:15383/R:anatal_tlet/F:anatally.f'
         goto 999

  993    m_err = 'In this line, [ ; ] cannot be used.'
         ErrCha = ''
         ErrID = 'L:15388/R:anatal_tlet/F:anatally.f'
         goto 999

  994    m_err = 'Name of particle is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:15393/R:anatal_tlet/F:anatally.f'
         goto 999

cfrtati 2021/10/05 6 -> mxpart
  995    m_err = 'Number of particles is larger than mxpart in '//tname
         ErrCha = ''
         ErrID = 'L:15399/R:anatal_tlet/F:anatally.f'
         goto 999

  996    m_err = 'Description of mesh is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:15404/R:anatal_tlet/F:anatally.f'
         goto 999

  997    m_err = 'Description of parameter is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:15409/R:anatal_tlet/F:anatally.f'
         goto 999

  998    m_err = 'Unknown mesh parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:15414/R:anatal_tlet/F:anatally.f'
         goto 999

 1045    m_err = 'Too many samepage in tally '//tname
         ErrCha = ''
         ErrID = 'L:15419/R:anatal_tlet/F:anatally.f'
         goto 999

 1046    m_err = 'samepage should be wwg, reg,eng,t,xy,yz,zx,x,y,z'
     &           //' in tally '//tname
         ErrCha = ''
         ErrID = 'L:15425/R:anatal_tlet/F:anatally.f'
         goto 999

*-----------------------------------------------------------------------

  999 continue

         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1

*-----------------------------------------------------------------------

      return
      end subroutine anatal_tlet


************************************************************************
*                                                                      *
      subroutine anatal_ttrack(jsn,jsi,dsin,idsi,ill,ilf,
     &                         jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)
*                                                                      *
*       read [t-track] section of tally files                          *
*       modified by K.Niita on 2014/12/04                              *
*                                                                      *
************************************************************************
      use sangelmod, only: itsanf
      use anatallymod, only: nanatalRead
      use partmod ! frtati 2021/10/05
      use moddas
      use moddas_mesh
      use moddas_region
      use moddas_tally

      implicit real*8 (a-h,o-z)

      parameter(icsu=49) ! nais 2023/01/06

      include 'param.inc'
      include 'param01.inc'
      include 'err.inc'

*-----------------------------------------------------------------------

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)

      common /tall02/ itrgn(itlmax), itrgm(itlmax), itreg(itlmax)
      common /tall25/ itrnv(itlmax), itriv(itlmax), itrrv(itlmax)

      common /tall03/ itrty(itlmax), itrnm(itlmax), itrrg(itlmax),
     &                rtrmi(itlmax), rtrma(itlmax), rtrdl(itlmax)
      common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &                rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)
      common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &                rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)

      common /tall08/ rtrx0(itlmax), rtry0(itlmax)

      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80

      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall19/ itsmn(itlmax), itstm(itlmax)

      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                rttmi(itlmax), rttma(itlmax), rttdl(itlmax)
      common /tall21/ rtfac(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)

      common /tall23/ itaty(itlmax), itanm(itlmax), itarg(itlmax),
     &                rtami(itlmax), rtama(itlmax), rtadl(itlmax)

      common /tall28/ itgsh(itlmax)
      common /tall29/ itrsh(itlmax)
      common /tall31/ iterl(itlmax)
      common /tall34/ itvm(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall37/ itcnt(9,itlmax)

      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)

      common /tall45/ itmlp(itlmax), itmln(itlmax,6), itmst(itlmax),
     &                itmli(itlmax,6), rtmme(itlmax,6), itmnt(itlmax,6),
     &                itmpn(itlmax,6), itmpt(itlmax,6,6,2)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

      common /tall49/ itglt(itlmax)

!OBINATA: for resfile
      common /tall59/ irfll(itlmax), crfln(itlmax), itrff(itlmax)
      character crfln*100
      character irfile*100

      common /tall60/ itger(itlmax)
      common /tall63/ itbmp(itlmax)
      common /tall64/ itvtk(itlmax),itvtkfmt(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)

      common /paraj/  mstz(300), parz(300) ! S.H. 2020.2.25

*-----------------------------------------------------------------------
      common /tall78/ itism(itlmax), itist(10,itlmax), itjst(10,itlmax),
     &                itkst(10,itlmax), itstt(itlmax), itsdd(itlmax)

      parameter ( npanatal = 12 ) ! S.H. 2020.3.27
      dimension ist_nm(npanatal), isd_nm(npanatal,kvlmax),
     &     jst_nm(npanatal), kst_nm(npanatal)

      dimension idas(mdas*2)
      equivalence ( das, idas )


*-----------------------------------------------------------------------
      integer :: itfoam
      common /tall76/ itfoam(itlmax)


*-----------------------------------------------------------------------
      common /tall82/ itcnth(9,itlmax)
      dimension icounth(9)

! 20230106 nais samepage
      common /tall90/ itpgn(itlmax), itpgs(itlmax,6)

*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

*-----------------------------------------------------------------------

      character title*80
      character angelp*200
      character cxtxt*200
      character cytxt*200
      character cztxt*200

*-----------------------------------------------------------------------

      dimension lschn(icsu), ischn(icsu)
      character schan(icsu)*8


      data ( schan(i), i = 1, icsu ) /
     &    'mesh    ','part    ','e-type  ','unit    ','axis    ',
     &    'file    ','title   ','angel   ','2d-type ','factor  ',
     &    'x-txt   ','y-txt   ','z-txt   ','gshow   ','rshow   ',
     &    'iechrl  ','material','volmat  ','epsout  ','ctmin(1)',
     &    'ctmax(1)','ctmin(2)','ctmax(2)','ctmin(3)','ctmax(3)',
     &    'resol   ','width   ','multipli','t-type  ','trcl    ',
     &    '*trcl   ','gslat   ','resfile ','ginfo   ','a-type  ',
     &    'bmpout  ','vtkout  ','vtkfmt  ','stdcut  ','sangel  ',
     &    'foamout ','chmin(1)','chmax(1)','chmin(2)','chmax(2)',
     &    'chmin(3)','chmax(3)','maxangel','samepage'/

      data ( lschn(i), i = 1, icsu ) /
     &     4,         4,         6,         4,         4,
     &     4,         5,         5,         7,         6,
     &     5,         5,         5,         5,         5,
     &     6,         8,         6,         6,         8,
     &     8,         8,         8,         8,         8,
     &     5,         5,         8,         6,         4,
     &     5,         5,         7,         5,         6,
     &     6,         6,         6,         6,         6,
     &     7,         8,         8,         8,         8,
     &     8,         8,         8,         8/

*-----------------------------------------------------------------------

cfrtati 2021/10/05 6 -> mxpart
      dimension iptyp(mxpart), ipnkf(mxpart)
      dimension imtyp(mxpart,mxpart), imnkf(mxpart,mxpart)
      dimension jstyp(mxpart), jnkf0(mxpart)
      dimension icount(9)

      common /subtra/ isubt, ipsub(mxpart)  ! kitamura22/03/31

      dimension iaxis(6)
      character ifile(6)*100
      dimension lfile(6)

      dimension ipgis(6)   ! samepage nais 2023/01/06


*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200
      character chlc*200

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

      character dkam*9

      character tname*9
      data      tname /'[t-track]'/

      logical deqn4

      integer isumtalRead

*-----------------------------------------------------------------------

      dimension jptyp(6), jpnkf(6)
      dimension kptyp(6,6), kpnkf(6,6)
      dimension ktln(6), ktli(6), ktls(6), kmst(6), knpat(6)
      dimension dkmax(6)
      dimension imst(6), kimst(6,6)
      dimension vtrs(13)
      dimension imtinf(4) ! frtati 2023/12/07

*-----------------------------------------------------------------------

            ierr  = 0

            iunt  = 1
            imate = 0
            jmate = 1
            inpat = 0
            inaxi = 0
            infil = 0
            idtyp = 3
            jmul  = 0

            langel = 0
            itsanf = 0
            lxtxt  = 0
            lytxt  = 0
            lztxt  = 0
            lgshow = 0
            lrshow = 0
            iechrl = 72
            matvol = 9
            ieps   = 0
            ibmp   = 0
            ivtk   = 0
            ivtkfmt= 0
            ittp   = 0
            igkst  = 0
            idtt   = 0
            ktrs   = 0
            igslt  = -1
            lrfile = 0 !OBINATA
            irfflg = 0 !OBINATA
            ifoam  = 0 !FURUTA20190208
            imxang = 0 ! frtati 2021/10/05

            iatp   = 0
            jatp   = 0

            amin = 0.0
            amax = 0.0
            adel = 0.0

            icount(1) = 0
            icount(2) = 0
            icount(3) = 0
            icount(4) = -9999
            icount(5) =  9999
            icount(6) = -9999
            icount(7) =  9999
            icount(8) = -9999
            icount(9) =  9999
            icounth(1) = 0
            icounth(2) = 0
            icounth(3) = 0
            icounth(4) = -9999
            icounth(5) =  9999
            icounth(6) = -9999
            icounth(7) =  9999
            icounth(8) = -9999
            icounth(9) =  9999

            rfact = 1.0

            ireso = 1
            width = 0.5

         do i = 1, icsu

            ischn(i) = 0

         end do

            infog = 0

         inpgi = 0   ! samepage 2023/01/06

       isumtalRead = 0

            stdcut = -1.0

            istbat = 0
         do i = 1, npanatal
            ist_nm(i) = 0
            jst_nm(i) = 0
         end do

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140 continue

            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*.......................................................................
*        end of reading header info. (from tally file)
*.......................................................................
            if( i1 .ne. 0 ) then !20221004frtati fbounds-check
              if( mstz(1) .eq. 17 .and.
     &         chin(i1:i1+25) .eq. '#-------------------------' ) then
                 jpn = 1
                 goto 800
              end if
            end if

               if( iskip .ne. 0 ) goto 140

  150 continue

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*-----------------------------------------------------------------------
*        end of the section
*-----------------------------------------------------------------------

            if( chlw(i1:i1) .eq. '[' ) then

               jpn = 1
               goto 800

            end if

*-----------------------------------------------------------------------
*        identify the parameters
*-----------------------------------------------------------------------

            icl = i1


!-----------------------------------------------------------------------
!        sumtally sub section
!-----------------------------------------------------------------------

      if ( chlw(i1:i3) .eq. 'sumtally start' ) then

          isumtalRead = 1
          call read_sumtal(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

          if( ierr .ne. 0 ) return

          if( jpn == 3 ) goto 800   ! 'q:'
          if( jpn == 1 ) goto 800   ! end of the section

          go to 140

      end if

*-----------------------------------------------------------------------
*        anatally
*-----------------------------------------------------------------------

      if ( chlw(i1:i3) .eq. 'anatally start' ) then

         if (  mstz(1) .eq. 17 ) then
            nanatalRead(1+itnm) = 1
            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &           jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
            if ( chlw(i1:i3) .ne. 'anatally end' ) then
               ierr = 1
            end if
         else

            istbat = 1

            call stbatm(jsn,jsi,dsin,idsi,ill,ilf,
     &                  jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                  ist_nm,isd_nm,kst_nm)

            if( ierr .ne. 0 ) return
            if( jpn == 3 ) goto 800   ! 'q:'
            if( jpn == 1 ) goto 800   ! end of the section

         end if ! S.H. (2020.2.25)
            goto 140

      end if

*-----------------------------------------------------------------------

  200    continue

            chlc = chlw
            call chcomp(chlc,icl,i3,i5)

         do i = 1, icsu

            il = icl + lschn(i) - 1

            if( chlc(icl:il) .eq. schan(i)(1:lschn(i)) ) goto 100

         end do

               goto 987

*-----------------------------------------------------------------------
*        read value of parameters
*-----------------------------------------------------------------------

  100    continue

               ipm = i

               ischn( ipm ) = ischn( ipm ) + 1

            if( ipm .ne.  5 .and. ipm .ne. 6 .and.
     &          ipm .ne.  2 .and. ipm .ne. 28 .and.
     &          ipm .ne. 33 .and.
     &          ischn( ipm ) .gt. 1 ) goto 989

               ic = inumc(chlw,il+1,i3,'=') + 1
               ic = jnumc(chlw,ic,i3)

               if( ic .gt. i3 ) goto 997

               icl = inumc(chlw,ic,i3,';') - 1

*-----------------------------------------------------------------------
*        mesh = region, r-z, xyz, or tet
*-----------------------------------------------------------------------

         if( ipm .eq. 1 ) then

            if( chlw(ic:ic+2) .eq. 'reg' ) then

               imesh = 1

            else if( chlw(ic:ic+2) .eq. 'r-z' ) then

               imesh = 2

            else if( chlw(ic:ic+2) .eq. 'xyz' ) then

               imesh = 3

            else if( chlw(ic:ic+2) .eq. 'tet' ) then
               imesh = 4

            else

               goto 998

            end if

            if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

            if( imesh .eq. 1 ) then

               call moddas_allocate_int(
     &                 MAX_NUM_ITREG, idas_itreg_temporary)

               ndsm = 1
               call tregion(1,jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ntrn,mtrn,ndsm,nvol,ivl,irvl,0
     &                      ,MAX_NUM_ITREG,idas_itreg_temporary)

               if( mtrn > MAX_NUM_ITREG ) then
                  write(ErrCha,'(a,a,i5,a,a,i5,a)')
     &                 'sub.ttrack@tallsm2.f'
     &                    //' ?dimension over idas_itreg_temporary?'
     &                    //' mtrn > MAX_NUM_ITREG'
     &                 ,' (mtrn=',mtrn,')'
     &                 ,' (MAX_NUM_ITREG@moddas.f=',MAX_NUM_ITREG,')'
                  ErrID = 'L:15927/R:anatal_ttrack/F:anatally.f'
                  call ErrWrite(ErrID,ErrCha)
               endif


                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ntrn .lt. -1 ) goto 996

            else if( imesh .eq. 2 ) then

               call trzmesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      rzx0,rzy0,
     &                      irtp,inr,rmin,rmax,rdel,istrg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( irtp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            else if( imesh .eq. 3 ) then

               call txymesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ixtp,inx,xmin,xmax,xdel,istxg,
     &                      iytp,iny,ymin,ymax,ydel,istyg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ixtp .lt. 0 ) goto 996
                  if( iytp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            else if( imesh .eq. 4 ) then

               call moddas_allocate_int(
     &                 MAX_NUM_ITREG, idas_itreg_temporary)

               call ttetmesh(jsn,jsi,dsin,idsi,ill,ilf,
     &              jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &              mtrn,ntrn,
     &              MAX_NUM_ITREG,idas_itreg_temporary)

               if( mtrn > MAX_NUM_ITREG ) then
                  write(ErrCha,'(a,a,i5,a,a,i5,a)')
     &                 'sub.ttrack@tallsm2.f'
     &                    //' ?dimension over idas_itreg_temporary?'
     &                    //' mtrn > MAX_NUM_ITREG'
     &                 ,' (mtrn=',mtrn,')'
     &                 ,' (MAX_NUM_ITREG@moddas.f=',MAX_NUM_ITREG,')'
                  ErrID = 'L:15980/R:anatal_ttrack/F:anatally.f'
                  call ErrWrite(ErrID,ErrCha)
               endif

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800

            end if

                  goto 150

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

         else if( ipm .eq. 2 ) then

  400       continue

               ic = jnumc(chlw,ic,icl)

               if( ic .gt. icl ) then

                  icl = jnumc(chlw,icl+2,i3)

                  if( icl .le. i3 ) goto 200

                  goto 140

               end if

*-----------------------------------------------------------------------

            call rdpname(ic,icl,chlw,istyp,inkf0,jstyp,jnkf0,ierr)

               if( ierr .eq. 994 ) goto 994
               if( ierr .eq. 998 ) goto 997

*-----------------------------------------------------------------------

               inpat = inpat + 1

               if( inpat .gt. mxpart ) goto 995

                  iptyp(inpat) = istyp
                  ipnkf(inpat) = inkf0
                  ipsub(inpat) = isubt  ! kitamura22/03/31

               if( istyp .lt. 0 ) then

                  do i = 1, -istyp

                     imtyp(inpat,i) = jstyp(i)
                     imnkf(inpat,i) = jnkf0(i)

                  end do

               end if

               goto 400

*-----------------------------------------------------------------------
*        material
*-----------------------------------------------------------------------

         else if( ipm .eq. 17 ) then

            if( chlw(ic:ic+2) .eq. 'all' ) then

                  imate = 0

            else if( deqn4( chlw(ic:ic) ) ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 979

                  imate = nint( cvvv )

               if( imate .lt. 0 ) then

                  imate = -imate
                  jmate = -1

               end if

               if( imate .eq. 0 ) goto 979

                  nsmte = itmtt(itnm+1)
                  call moddas_reallocate_int(
     &                    itlmax, itnm+1, imate, itmtt, ismte)
                  if( mmmax .gt. mdas ) goto 950

  151                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                        if( ierr .ne. 0 ) return
                        if( jpn  .eq. 3 ) goto 979

                        if( iskip .ne. 0 ) goto 151

                  ic = i1

               do k = 1, imate

                  if( ic .gt. i3 ) then

  152                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                     if( ierr .ne. 0 ) return
                     if( jpn  .eq. 3 ) goto 979

                     if( iskip .ne. 0 ) goto 152

                     ic = i1

                  end if

                     ic = jnumc(chlw,ic,i3)

                     call snum(chlw,ic,i3,ic2,cvvv,ierr)

                     if( ierr .ne. 0 ) goto 979

                     matei = nint( cvvv )

                     ic = ic2

                     ismte(nsmte-1+k) = matei

               end do

            else

               goto 979

            end if

*-----------------------------------------------------------------------
*        energy mesh
*-----------------------------------------------------------------------

         else if( ipm .eq. 3 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

               ietp = nint( cvvv )

               call getmsh(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     'e',ietp,ine,emin,emax,edel,isteg)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        time mesh
*-----------------------------------------------------------------------

         else if( ipm .eq. 29 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

               ittp = nint( cvvv )

               call getmsh(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     't',ittp,int,tmin,tmax,tdel,isttg)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        angle mesh
*-----------------------------------------------------------------------

         else if( ipm .eq. 35 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

               iatp = nint( cvvv )
               jatp = abs( iatp )

               call getmsh(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     'a',jatp,ina,amin,amax,adel,istag)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        transform
*-----------------------------------------------------------------------

         else if( ipm .eq. 30 .or. ipm .eq. 31 ) then

                  if( ipm .eq. 31 ) ktrs = 1

               call ttrans(jsn,jsi,dsin,idsi,ill,ilf,
     &                     jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                     ic,ktrs,igkst,idtt,vtrs)

               if( ierr .ne. 0 ) return

               goto 150

*-----------------------------------------------------------------------
*        unit
*-----------------------------------------------------------------------

         else if( ipm .eq. 4 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               iunt = nint( cvvv )

               if( iunt .lt. 1 .or.
     &           ( iunt .gt. 5 .and. iunt .lt. 11 ) .or.
     &             iunt .gt. 14 ) goto 988

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

         else if( ipm .eq. 5 ) then

  600       inaxi = inaxi + 1

            if( inaxi .gt. 6 ) goto 991

            if( chlw(ic:ic+2) .eq. 'eng' ) then

               iaxis(inaxi) = 1
               ic =jnumc(chlw,ic+4,icl)

            else if( chlw(ic:ic+2) .eq. 'reg' ) then

               iaxis(inaxi) = 2
               ic =jnumc(chlw,ic+4,icl)

