                     iaddress_gmsh(2) = iaddress_gmsh(3)
                     icurrent_gmsh = 2

                     call moddas_reallocate_dbl(
     &                       itlmax, itnm, 2, iterg, das_iterg)
                     itsmn(itnm) = itsmn(itnm) + 2
                  end if

                  gmsh(isteg-1+1) = 0.0
                  gmsh(isteg-1+2) = 1.0d+10
                  das_iterg(iterg(itnm)-1+1) = 0.0
                  das_iterg(iterg(itnm)-1+2) = 1.0d+10

               end if

               if( ( iunt .eq.  3 .or. iunt .eq.  6 .or.
