*-----------------------------------------------------------------------

         else if( ipm .eq. 28 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               ireso = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

         else if( ipm .eq. 29 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               width = cvvv

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        counter
*-----------------------------------------------------------------------

         else if( ipm .ge. 22 .and. ipm .le. 27 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               icount((ipm-22+2)/2) = 1
               icount( ipm-22+4)    = nint( cvvv )

               if( abs( nint(cvvv) ) .gt. 9999 ) goto 978

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        dump
*-----------------------------------------------------------------------

         else if( ipm .eq. 34 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               idump = nint( cvvv )

            if( idump .ne. 0 ) then

  251                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                        if( ierr .ne. 0 ) return
                        if( jpn  .eq. 3 ) goto 976

                        if( iskip .ne. 0 ) goto 251

                  ic = i1

               do k = 1, abs( idump )

                  if( ic .gt. i3 ) then

  252                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                     if( ierr .ne. 0 ) return
                     if( jpn  .eq. 3 ) goto 976

                     if( iskip .ne. 0 ) goto 252

                     ic = i1

                  end if

                     ic = jnumc(chlw,ic,i3)

                     call snum(chlw,ic,i3,ic2,cvvv,ierr)

                     if( ierr .ne. 0 ) goto 976

                     jdump(k) = nint( cvvv )

                     if( jdump(k) .gt. 20 .or.
     &                   jdump(k) .le.  0 ) goto 977

                     ic = ic2

               end do

            end if

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

         else if( ipm .eq. 36 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               infog = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        stdcut
*-----------------------------------------------------------------------

         else if( ipm .eq. 40 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               stdcut = cvvv

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        MorP (Mean or Probability)
*-----------------------------------------------------------------------

         else if( ipm .eq. 42 ) then

               if( chlw(ic:ic+3) .eq. 'mean' ) then

                  morp = 0

               elseif( chlw(ic:ic+3) .eq. 'prob' ) then

                  morp = 1

               else

                  m_err = 'Description of MorP parameter is wrong '//
     &                    'in tally '//tname
                  ErrCha = ''
                  ErrID = 'L:25164/R:anatal_tstar/F:anatally.f'
                  goto 999

               end if

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        maxact
*-----------------------------------------------------------------------

         else if( ipm .eq. 43 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               maxact = nint(cvvv)

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        history counter
*-----------------------------------------------------------------------
         else if( ipm .ge. 44 .and. ipm .le. 49 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               icounth((ipm-44+2)/2) = 1
               icounth( ipm-44+4)    = nint( cvvv )

               if( abs( nint(cvvv) ) .gt. 9999 ) goto 978

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        maxangel
*-----------------------------------------------------------------------
         else if( ipm .eq. 50 ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               imxang = nint( cvvv )

               icl = jnumc(chlw,icl+2,i3)

               if( icl .le. i3 ) goto 200

*-----------------------------------------------------------------------
*        samepage       nais 2023/01/6
*-----------------------------------------------------------------------

         else if( ipm .eq. 51 ) then

            call setsamepage(inpgi,ipgis,ic,chlw,icl, ierr)

            if( ierr .eq. 1 ) goto 1045
            if( ierr .eq. 2 ) goto 1046

            icl = jnumc(chlw,icl+2,i3)

            if( icl .le. i3 ) goto 200
*-----------------------------------------------------------------------
*        nlatcel
*-----------------------------------------------------------------------

         else if( ipm .eq. 52 ) then

