*-----------------------------------------------------------------------

  800 continue

      if( ischn(6) .eq. 0 ) then

         if( imesh .eq. 1 ) then

            title = '[t-star] in region mesh'
            titll = 23

         else if( imesh .eq. 2 ) then

            if( morp .ne. 0 ) then
               m_err = 'morp=prob is not allowed for r-z mesh in tally '
     &                 //tname
               ErrCha = ''
               ErrID = 'L:25292/R:anatal_tstar/F:anatally.f'
               goto 999
            endif

            title = '[t-star] in r-z mesh'
            titll = 20

         else if( imesh .eq. 3 ) then

            if( morp .ne. 0 ) then
               m_err = 'morp=prob is not allowed for xyz mesh in tally '
     &                 //tname
               ErrCha = ''
               ErrID = 'L:25305/R:anatal_tstar/F:anatally.f'
               goto 999
            endif

            title = '[t-star] in xyz mesh'
            titll = 20

         end if

      end if

      if( ischn(1) .eq. 0 ) then

         m_err = 'Mesh is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:25320/R:anatal_tstar/F:anatally.f'
         goto 999

      else if( ischn(10) .eq. 0 ) then

         m_err = 'E-type is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:25327/R:anatal_tstar/F:anatally.f'
         goto 999

      else if( inaxi .eq. 0 ) then

         m_err = 'Axis is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:25334/R:anatal_tstar/F:anatally.f'
         goto 999

      else if( infil .eq. 0 ) then

         m_err = 'File is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:25341/R:anatal_tstar/F:anatally.f'
         goto 999

      else if( inaxi .ne. infil ) then

         m_err = 'Number of Axis and File is different in tally '//tname
         ErrCha = ''
         ErrID = 'L:25348/R:anatal_tstar/F:anatally.f'
         goto 999

      else if( ischn(30) .eq. 0 .and. iunt .gt. 10 ) then

         m_err = 'T-type is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:25355/R:anatal_tstar/F:anatally.f'
         goto 999

      else if( itsanf > 1 ) then

         m_err = 'Double definition of sangel is found in tally '//tname
         ErrCha = ''
         ErrID = 'L:25362/R:anatal_tstar/F:anatally.f'
         goto 999

      end if

      do i = 1, inaxi

         if( lrshow .eq. 0 ) then

            if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 8 .or.
     &            iaxis(i) .eq. 9 ) .and. imesh .ne. 3 ) then

               m_err = 'Axis is xy, yz, or zx, '//
     &                 'but mesh is not xyz in tally '//tname
               ErrCha = ''
               ErrID = 'L:25377/R:anatal_tstar/F:anatally.f'
               goto 999

            end if

         end if

         if( iaxis(i) .eq. 11 .and. ittp .eq. 0 ) then

            m_err = 'T-type is not defined in tally '//tname
            ErrCha = ''
            ErrID = 'L:25388/R:anatal_tstar/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 2 .and. imesh .ne. 1 ) then

            m_err = 'Axis is reg but mesh is not reg in tally '//tname
            ErrCha = ''
            ErrID = 'L:25395/R:anatal_tstar/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 3 .and. imesh .ne. 3 ) then

            m_err = 'Axis is x but mesh is not xyz in tally '//tname
            ErrCha = ''
            ErrID = 'L:25402/R:anatal_tstar/F:anatally.f'
            goto 999

