            ErrCha = ''
            ErrID = 'L:25476/R:anatal_tstar/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 12 .and. morp .eq. 0 ) then

            m_err = 'Axis is act, but morp=mean in tally '//tname
            ErrCha = ''
            ErrID = 'L:25483/R:anatal_tstar/F:anatally.f'
            goto 999

         else if( iaxis(i) .ne. 12 .and. morp .ne. 0 ) then

            m_err = 'morp=prob, but axis is not act in tally '//tname
            ErrCha = ''
            ErrID = 'L:25490/R:anatal_tstar/F:anatally.f'
            goto 999

         end if

      end do

*-----------------------------------------------------------------------

      if ( ibmp .ne. 0 ) then

         if ( imesh .ne. 3 ) then

            m_err = 'Mesh should be xyz on bmpout in tally '//tname
            ErrCha = ''
            ErrID = 'L:25505/R:anatal_tstar/F:anatally.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 7 .and.
     &           iaxis(i) .ne. 8 .and.
     &           iaxis(i) .ne. 9 ) then

               m_err = 'Axis should be xy, yz or xz on bmpout'//
