      if ( ivtk .ne. 0 ) then

         if ( imesh .ne. 3 ) then

            m_err = 'Mesh should be xyz on bmpout in tally '//tname
            ErrCha = ''
            ErrID = 'L:25536/R:anatal_tstar/F:anatally.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 7 .and.
     &           iaxis(i) .ne. 8 .and.
     &           iaxis(i) .ne. 9 ) then

               m_err = 'Axis should be xy, yz or xz on bmpout'//
