                  itrnm(itnm) = inr
                  rtrdl(itnm) = rdel
                  rtrmi(itnm) = rmin
                  rtrma(itnm) = rmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inr+1, itrrg, das_itrrg)
                  das_itrrg(itrrg(itnm):itrrg(itnm)+inr)
     &                     = gmsh(istrg:istrg+inr)
                  itsmn(itnm) = itsmn(itnm) + inr + 1

                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)

                  itsmn(itnm) = itsmn(itnm) + inz + 1

         else if( imesh .eq. 3 .or. lrshow .gt. 0 ) then

                  itxty(itnm) = ixtp
                  itxnm(itnm) = inx
                  rtxdl(itnm) = xdel
                  rtxmi(itnm) = xmin
                  rtxma(itnm) = xmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inx+1, itxrg, das_itxrg)
                  das_itxrg(itxrg(itnm):itxrg(itnm)+inx)
     &                     = gmsh(istxg:istxg+inx)
                  itsmn(itnm) = itsmn(itnm) + inx + 1

                  ityty(itnm) = iytp
                  itynm(itnm) = iny
                  rtydl(itnm) = ydel
                  rtymi(itnm) = ymin
                  rtyma(itnm) = ymax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, iny+1, ityrg, das_ityrg)
                  das_ityrg(ityrg(itnm):ityrg(itnm)+iny)
     &                     = gmsh(istyg:istyg+iny)
                  itsmn(itnm) = itsmn(itnm) + iny + 1

                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)
                  itsmn(itnm) = itsmn(itnm) + inz + 1

         end if

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

                  itaxn(itnm) = inaxi

               do i = 1, inaxi

                  itaxs(itnm,i) = iaxis(i)

               end do

*-----------------------------------------------------------------------
*        file
*-----------------------------------------------------------------------

                  itfln(itnm) = infil

               do i = 1, infil

                  itfll(itnm,i) = lfile(i)

                  ctfln(itnm,i)(1:lfile(i)) = ifile(i)(1:lfile(i))

                  do k = lfile(i) + 1, 100

                     ctfln(itnm,i)(k:k) = ' '

                  end do

               end do

*-----------------------------------------------------------------------
*       restart file
*-----------------------------------------------------------------------
               call summary_param_resfile(itnm,irfflg,lrfile,irfile)

*-----------------------------------------------------------------------
*        particles
*-----------------------------------------------------------------------

            itmxptt = inpat
            itmxgpt = 1
            do i = 1, inpat
              if ( iptyp(i).lt.0 .and. -iptyp(i).gt.itmxgpt ) then
                itmxgpt = -iptyp(i)
              end if
            end do
            call ALLOCATE_PART_TEMP

            if( inpat .gt. 0 ) then

                  itpan(itnm) = inpat

               do i = 1, inpat

                  itpat(itnm,i,1) = iptyp(i)
                  itpat(itnm,i,2) = ipnkf(i)
                  itpat(itnm,i,3) = ipsub(i)  ! kitamura22/03/31

                  if( itpat(itnm,i,1) .lt. 0 ) then

                     do k = 1, -itpat(itnm,i,1)

                        jtpat(itnm,i,k,1) = imtyp(i,k)
                        jtpat(itnm,i,k,2) = imnkf(i,k)

                     end do

                  end if

               end do

            else if( inpat .eq. 0 ) then

                  itpan(itnm) = 1
                  itpat(itnm,1,1) = 20
                  itpat(itnm,1,2) = 0

            end if

*-----------------------------------------------------------------------
*        energy mesh
*-----------------------------------------------------------------------

                  itety(itnm) = ietp
                  itenm(itnm) = ine
                  rtedl(itnm) = edel
                  rtemi(itnm) = emin
                  rtema(itnm) = emax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, ine+1, iterg, das_iterg)
                  das_iterg(iterg(itnm):iterg(itnm)+ine)
     &                     = gmsh(isteg:isteg+ine)
                  itsmn(itnm) = itsmn(itnm) + ine + 1

*-----------------------------------------------------------------------
*        time mesh
*-----------------------------------------------------------------------

               if( ittp .ne. 0 ) then

                  ittty(itnm) = ittp
                  ittnm(itnm) = int
                  rttdl(itnm) = tdel
                  rttmi(itnm) = tmin
                  rttma(itnm) = tmax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, int+1, ittrg, das_ittrg)
                  das_ittrg(ittrg(itnm):ittrg(itnm)+int)
     &                     = gmsh(isttg:isttg+int)

                  itsmn(itnm) = itsmn(itnm) + int + 1

               else

                  ittty(itnm) = ittp
                  ittnm(itnm) = 1
                  rttdl(itnm) = 0.d0
                  rttmi(itnm) = 0.d0
                  rttma(itnm) = 0.d0

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, 2, ittrg, das_ittrg)
                  itsmn(itnm) = itsmn(itnm) + 2

                  das_ittrg(ittrg(itnm)  ) = -1.d+30
                  das_ittrg(ittrg(itnm)+1) =  1.d+30

                  call moddas_reallocate_dbl(
     &                    3, icurrent_gmsh, 2, iaddress_gmsh, gmsh)
                  gmsh(iaddress_gmsh(icurrent_gmsh)  ) = -1.d+30
                  gmsh(iaddress_gmsh(icurrent_gmsh)+1) =  1.d+30
                  iaddress_gmsh(2) = iaddress_gmsh(3)
                  icurrent_gmsh = 2

               end if

*-----------------------------------------------------------------------
*        nact mesh
*-----------------------------------------------------------------------
               itmorp(itnm) = morp

               itactnm(itnm) = maxact+1
               itactmax(itnm) = 0

               itactrg(itnm) = mmmax
               itsmn(itnm) = itsmn(itnm) + maxact+1 + 1

               do i = 1, maxact+1
                  das(mmmax+i-1) =  dble(i)
               enddo

               mmmax = mmmax + maxact+1

*-----------------------------------------------------------------------
*        transformation
*-----------------------------------------------------------------------

                     itmtr(itnm,1) = igkst
                     itmtr(itnm,2) = ktrs
                     itmtr(itnm,3) = idtt
                     itmtr(itnm,4) = 0

               if( igkst .gt. 1 ) then

                  do k = 1, 13

                     rtmtr(itnm,k) = vtrs(k)

                  end do

               end if

*-----------------------------------------------------------------------
*        output
*-----------------------------------------------------------------------

                  itout(itnm) = iout

*-----------------------------------------------------------------------
*        reg echo length
*-----------------------------------------------------------------------

                  iterl(itnm) = iechrl

*-----------------------------------------------------------------------
*        unit
*-----------------------------------------------------------------------

                  itunt(itnm) = iunt

*-----------------------------------------------------------------------
*        2D-type
*-----------------------------------------------------------------------

                  ittwo(itnm) = idtyp

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

                  rtfac(itnm) = rfact

*-----------------------------------------------------------------------
*        volmat
*-----------------------------------------------------------------------

                  itvm(itnm) = matvol

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

                  iteps(itnm) = ieps

*-----------------------------------------------------------------------
*        bmpout
*-----------------------------------------------------------------------

                  itbmp(itnm) = ibmp

*-----------------------------------------------------------------------
*        vtkout
*-----------------------------------------------------------------------

                  itvtk(itnm) = ivtk

*-----------------------------------------------------------------------
*        vtkfmt
*-----------------------------------------------------------------------

                  itvtkfmt(itnm) = ivtkfmt

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

                  itres(itnm) = max( 1, ireso )

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

                  rtwid(itnm) = width

*-----------------------------------------------------------------------
*        counter
*-----------------------------------------------------------------------

               do i = 1, 9

                  itcnt(i,itnm) = icount(i)
                  itcnth(i,itnm) = icounth(i) !frtati 2021/04/06

               end do

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

                  itger(itnm) = infog

*-----------------------------------------------------------------------
*        stdcut
*-----------------------------------------------------------------------
                  rtstd(itnm) = stdcut

*-----------------------------------------------------------------------
*        maxangel
*-----------------------------------------------------------------------
                  itmxang(itnm) = imxang
! hirata 20230420
*-----------------------------------------------------------------------
*        nlatcel and nlatmem
*-----------------------------------------------------------------------

                  itnlatcel(itnm) = nlatcel

                  if( nlatcel .eq. 0 ) then
                     itnlatmem(itnm) = 1
                  else
                     itnlatmem(itnm) = nlatmem
                  endif

*-----------------------------------------------------------------------
*        samepage
*-----------------------------------------------------------------------
                  itpgn(itnm) = inpgi

               do i = 1, inpgi

                  itpgs(itnm,i) = ipgis(i)

               end do

*-----------------------------------------------------------------------
*        xy, yz, zx, rz storage region
*-----------------------------------------------------------------------

                     mxyz = 1
                     mrzr = 1
                     mrzz = 1

                  do i = 1, inaxi

                     if( iaxis(i) .eq. 7 ) then

                        if( inx .gt. mxyz ) mxyz = inx
                        if( iny .gt. mxyz ) mxyz = iny

                     else if( iaxis(i) .eq. 8 ) then

                        if( iny .gt. mxyz ) mxyz = iny
                        if( inz .gt. mxyz ) mxyz = inz

                     else if( iaxis(i) .eq. 9 ) then

                        if( inx .gt. mxyz ) mxyz = inx
                        if( inz .gt. mxyz ) mxyz = inz

                     else if( iaxis(i) .eq. 10 ) then

                        mrzr = inr
                        mrzz = inz

                     end if

                  end do

                     itnfn(itnm) = mxyz
                     itnfr(itnm) = mrzr
                     itnfz(itnm) = mrzz

*-----------------------------------------------------------------------
*        dump
*-----------------------------------------------------------------------

                  itmdp(itnm,0) = idump

               if( idump .ne. 0 ) then

                  do i = 1, abs( idump )

                     itmdp(itnm,i) = jdump(i)

                  end do

               end if

*-----------------------------------------------------------------------

      return

*-----------------------------------------------------------------------
*     errors
*-----------------------------------------------------------------------

  950    write(dkam,'(i9)') mdas
         m_err = 'Total tally storage number exceeds mdas ='//dkam
         ErrCha = ''
         ErrID = 'L:26229/R:anatal_tstar/F:anatally.f'
         goto 999

  976    m_err = 'Description of dump parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:26235/R:anatal_tstar/F:anatally.f'
         goto 999

  977    m_err = 'dump id should be 1 - 20.'
         ErrCha = ''
         ErrID = 'L:26240/R:anatal_tstar/F:anatally.f'
         goto 999

  978    m_err = 'counter should be from -9999 to 9999'
         ErrCha = ''
         ErrID = 'L:26245/R:anatal_tstar/F:anatally.f'
         goto 999

  980    m_err = 'unit should be 1 or 2 in tally '//tname
         ErrCha = ''
         ErrID = 'L:26250/R:anatal_tstar/F:anatally.f'
         goto 999

  981    m_err = 'Description of material parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:26256/R:anatal_tstar/F:anatally.f'
         goto 999

  982    m_err = 'Description of mother parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:26262/R:anatal_tstar/F:anatally.f'
         goto 999

  983    m_err = '2D-type should be 1-7 in tally '//tname
         ErrCha = ''
         ErrID = 'L:26267/R:anatal_tstar/F:anatally.f'
         goto 999

  984    m_err = 'Unknown output parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:26272/R:anatal_tstar/F:anatally.f'
         goto 999

  986    write(dkam,'(i5)') itlmax
         m_err = 'Total tally number exceeds itlmax = '//dkam
         ErrCha = ''
         ErrID = 'L:26278/R:anatal_tstar/F:anatally.f'
         goto 999

  987    m_err = 'Unknown parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:26283/R:anatal_tstar/F:anatally.f'
         goto 999

  989    m_err = 'Double definition of the parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:26288/R:anatal_tstar/F:anatally.f'
         goto 999

  990    m_err = 'Too many file name in tally '//tname
         ErrCha = ''
         ErrID = 'L:26293/R:anatal_tstar/F:anatally.f'
         goto 999

  991    m_err = 'Too many axis in tally '//tname
         ErrCha = ''
         ErrID = 'L:26298/R:anatal_tstar/F:anatally.f'
         goto 999

  992    m_err = 'Unknown axis name in tally '//tname
         ErrCha = ''
         ErrID = 'L:26303/R:anatal_tstar/F:anatally.f'
         goto 999

  993    m_err = 'In this line, [ ; ] cannot be used.'
         ErrCha = ''
         ErrID = 'L:26308/R:anatal_tstar/F:anatally.f'
         goto 999

  994    m_err = 'Name of particle is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:26313/R:anatal_tstar/F:anatally.f'
         goto 999

cfrtati 2021/10/05 6 -> mxpart
  995    m_err = 'Number of particles is larger than mxpart in '//tname
         ErrCha = ''
         ErrID = 'L:26319/R:anatal_tstar/F:anatally.f'
         goto 999

  996    m_err = 'Description of mesh is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:26324/R:anatal_tstar/F:anatally.f'
         goto 999

  997    m_err = 'Description of parameter is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:26329/R:anatal_tstar/F:anatally.f'
         goto 999

  998    m_err = 'Unknown mesh parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:26334/R:anatal_tstar/F:anatally.f'
         goto 999

 1045    m_err = 'Too many samepage in tally '//tname
         ErrCha = ''
         ErrID = 'L:26339/R:anatal_tstar/F:anatally.f'
         goto 999

 1046    m_err = 'samepage should be wwg, reg,eng,t,xy,yz,zx,x,y,z'
     &           //' in tally '//tname
         ErrCha = ''
         ErrID = 'L:26345/R:anatal_tstar/F:anatally.f'
         goto 999

*-----------------------------------------------------------------------

  999 continue

         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1

*-----------------------------------------------------------------------

      return
      end subroutine anatal_tstar


************************************************************************
*                                                                      *
      subroutine anatal_ttime(jsn,jsi,dsin,idsi,ill,ilf,
     &                        jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)
*                                                                      *
*       read [t-time] section of tally files                           *
*       modified by K.Niita on 2014/09/02                              *
*                                                                      *
************************************************************************
      use sangelmod, only: itsanf
      use anatallymod, only: nanatalRead
      use partmod ! frtati 2021/10/05
      use moddas
      use moddas_mesh
      use moddas_region
      use moddas_tally

      implicit real*8 (a-h,o-z)

      parameter(icsu=48) ! nais 2023/01/06

      include 'param.inc'
      include 'param01.inc'
      include 'err.inc'

*-----------------------------------------------------------------------

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)

      common /tall02/ itrgn(itlmax), itrgm(itlmax), itreg(itlmax)
      common /tall25/ itrnv(itlmax), itriv(itlmax), itrrv(itlmax)

      common /tall03/ itrty(itlmax), itrnm(itlmax), itrrg(itlmax),
     &                rtrmi(itlmax), rtrma(itlmax), rtrdl(itlmax)
      common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &                rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)
      common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &                rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)
      common /tall07/ itety(itlmax), itenm(itlmax), iterg(itlmax),
     &                rtemi(itlmax), rtema(itlmax), rtedl(itlmax)

      common /tall20/ ittty(itlmax), ittnm(itlmax), ittrg(itlmax),
     &                rttmi(itlmax), rttma(itlmax), rttdl(itlmax)

      common /tall08/ rtrx0(itlmax), rtry0(itlmax)

      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall16/ itnfr(itlmax), itnfz(itlmax), itnfn(itlmax)

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80

      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall19/ itsmn(itlmax), itstm(itlmax)

      common /tall21/ rtfac(itlmax)

      common /tall28/ itgsh(itlmax)
      common /tall29/ itrsh(itlmax)
      common /tall31/ iterl(itlmax)

      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)
      common /tall34/ itvm(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall37/ itcnt(9,itlmax)

      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)
      common /tall48/ itmdp(itlmax,0:30), itmdf(itlmax)

      common /tall49/ itglt(itlmax)

!OBINATA: for resfile
      common /tall59/ irfll(itlmax), crfln(itlmax), itrff(itlmax)
      character crfln*100
      character irfile*100

      common /tall60/ itger(itlmax)
      common /tall63/ itbmp(itlmax)
      common /tall64/ itvtk(itlmax),itvtkfmt(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)
      common /paraj/  mstz(300), parz(300) ! S.H. 2022.1.21

      common /tall82/ itcnth(9,itlmax)
      dimension icounth(9)

! 20230106 nais samepage
      common /tall90/ itpgn(itlmax), itpgs(itlmax,6)

      dimension idas(mdas*2)
      equivalence ( das, idas )


*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

*-----------------------------------------------------------------------

      character title*80
      character angelp*200
      character cxtxt*200
      character cytxt*200
      character cztxt*200

*-----------------------------------------------------------------------

      dimension lschn(icsu), ischn(icsu)
      character schan(icsu)*8


      data ( schan(i), i = 1, icsu ) /
     &    'mesh    ','part    ','t-type  ','axis    ','file    ',
     &    'title   ','angel   ','unit    ','2d-type ','e-type  ',
     &    'output  ','factor  ','x-txt   ','y-txt   ','z-txt   ',
     &    'gshow   ','rshow   ','iechrl  ','material','volmat  ',
     &    'epsout  ','ctmin(1)','ctmax(1)','ctmin(2)','ctmax(2)',
     &    'ctmin(3)','ctmax(3)','resol   ','width   ','trcl    ',
     &    '*trcl   ','dump    ','gslat   ','resfile ','ginfo   ',
     &    'bmpout  ','vtkout  ','vtkfmt  ','stdcut  ','sangel  ',
     &    'chmin(1)','chmax(1)','chmin(2)','chmax(2)','chmin(3)',
     &    'chmax(3)','maxangel','samepage'/

      data ( lschn(i), i = 1, icsu ) /
     &     4,         4,         6,         4,         4,
     &     5,         5,         4,         7,         6,
     &     6,         6,         5,         5,         5,
     &     5,         5,         6,         8,         6,
     &     6,         8,         8,         8,         8,
     &     8,         8,         5,         5,         4,
     &     5,         4,         5,         7,         5,
     &     6,         6,         6,         6,         6,
     &     8,         8,         8,         8,         8,
     &     8,         8,         8/

*-----------------------------------------------------------------------

cfrtati 2021/10/05 6 -> mxpart
      dimension iptyp(mxpart), ipnkf(mxpart)
      dimension imtyp(mxpart,mxpart), imnkf(mxpart,mxpart)
      dimension jstyp(mxpart), jnkf0(mxpart)

      common /subtra/ isubt, ipsub(mxpart)  ! kitamura22/03/31

      dimension iaxis(6)
      character ifile(6)*100
      dimension lfile(6)

      dimension ipgis(6)   ! samepage nais 2023/01/06

*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200
      character chlc*200

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

      character dkam*9

      character tname*8
      data      tname /'[t-time]'/

      logical deqn4

      dimension icount(9)
      dimension vtrs(13)

      dimension jdump(30)

      integer isumtalRead

*-----------------------------------------------------------------------

            ierr  = 0

            imate = 0
            jmate = 1
            inpat = 0
            inaxi = 0
            infil = 0
            iunt  = 2
            iout  = 1
            idtyp = 3

            langel = 0
            itsanf = 0
            lxtxt  = 0
            lytxt  = 0
            lztxt  = 0
            lgshow = 0
            lrshow = 0
            iechrl = 72
            matvol = 9
            ieps   = 0
            ibmp   = 0
            ivtk   = 0
            ivtkfmt= 0
            igkst  = 0
            idtt   = 0
            ktrs   = 0
            idump  = 0
            igslt  = -1
            lrfile = 0 !OBINATA
            irfflg = 0 !OBINATA
            imxang = 0 ! frtati 2021/10/05

            icount(1) = 0
            icount(2) = 0
            icount(3) = 0
            icount(4) = -9999
            icount(5) =  9999
            icount(6) = -9999
            icount(7) =  9999
            icount(8) = -9999
            icount(9) =  9999
            icounth(1) = 0
            icounth(2) = 0
            icounth(3) = 0
            icounth(4) = -9999
            icounth(5) =  9999
            icounth(6) = -9999
            icounth(7) =  9999
            icounth(8) = -9999
            icounth(9) =  9999

            ireso = 1
            width = 0.5

            rfact = 1.0

         do i = 1, icsu

            ischn(i) = 0

         end do

         do i = 1, 30
            jdump(i) = 0
         end do

            infog = 0

         inpgi = 0   ! samepage 2023/01/06

       isumtalRead = 0

            stdcut = -1.0

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140 continue

            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*.......................................................................
*        end of reading header info. (from tally file)
*.......................................................................
            if( i1 .ne. 0 ) then !20221004frtati fbounds-check
              if( mstz(1) .eq. 17 .and.
     &           chin(i1:i1+25) .eq. '#-------------------------' ) then
                 jpn = 1
                 goto 800
              end if
            end if

               if( iskip .ne. 0 ) goto 140

  150 continue

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*-----------------------------------------------------------------------
*        end of the section
*-----------------------------------------------------------------------

            if( chlw(i1:i1) .eq. '[' ) then

               jpn = 1
               goto 800

            end if

*-----------------------------------------------------------------------
*        identify the parameters
*-----------------------------------------------------------------------

            icl = i1

!-----------------------------------------------------------------------
!        sumtally sub section
!-----------------------------------------------------------------------
      if ( chlw(i1:i3) .eq. 'sumtally start' ) then
       isumtalRead = 1
       call read_sumtal(jsn,jsi,dsin,idsi,ill,ilf,
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
       if( ierr .ne. 0 ) return
       if( jpn == 3 ) goto 800   ! 'q:'
       if( jpn == 1 ) goto 800   ! end of the section
       go to 140
      end if

*-----------------------------------------------------------------------
*        anatally
*-----------------------------------------------------------------------

      if ( chlw(i1:i3) .eq. 'anatally start' ) then

         if (  mstz(1) .eq. 17 ) then
            nanatalRead(1+itnm) = 1
            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &           jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
            if ( chlw(i1:i3) .ne. 'anatally end' ) then
               ierr = 1
            end if
         else

            istbat = 1

            call stbatm(jsn,jsi,dsin,idsi,ill,ilf,
     &                  jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                  ist_nm,isd_nm,kst_nm)

            if( ierr .ne. 0 ) return
            if( jpn == 3 ) goto 800   ! 'q:'
            if( jpn == 1 ) goto 800   ! end of the section

         end if ! S.H. (2020.2.25)
