         m_err = 'Mesh is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:27692/R:anatal_ttime/F:anatally.f'
         goto 999

      else if( ischn(3) .eq. 0 ) then

         m_err = 'T-type is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:27699/R:anatal_ttime/F:anatally.f'
         goto 999

      else if( ischn(10) .eq. 0 ) then

         m_err = 'E-type is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:27706/R:anatal_ttime/F:anatally.f'
         goto 999

      else if( inaxi .eq. 0 ) then

         m_err = 'Axis is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:27713/R:anatal_ttime/F:anatally.f'
         goto 999

      else if( infil .eq. 0 ) then

         m_err = 'File is not defined in tally '//tname
         ErrCha = ''
         ErrID = 'L:27720/R:anatal_ttime/F:anatally.f'
         goto 999

      else if( inaxi .ne. infil ) then

         m_err = 'Number of Axis and File is different in tally '//tname
         ErrCha = ''
         ErrID = 'L:27727/R:anatal_ttime/F:anatally.f'
         goto 999

      else if( itsanf > 1 ) then

         m_err = 'Double definition of sangel is found in tally '//tname
         ErrCha = ''
         ErrID = 'L:27734/R:anatal_ttime/F:anatally.f'
         goto 999

      end if

      do i = 1, inaxi

         if( lrshow .eq. 0 ) then

            if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 8 .or.
     &            iaxis(i) .eq. 9 ) .and. imesh .ne. 3 ) then

               m_err = 'Axis is xy, yz, or zx, '//
     &                 'but mesh is not xyz in tally '//tname
               ErrCha = ''
               ErrID = 'L:27749/R:anatal_ttime/F:anatally.f'
               goto 999

            end if

         end if

         if( iaxis(i) .eq. 2 .and. imesh .ne. 1 ) then

            m_err = 'Axis is reg but mesh is not reg in tally '//tname
            ErrCha = ''
            ErrID = 'L:27760/R:anatal_ttime/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 3 .and. imesh .ne. 3 ) then

            m_err = 'Axis is x but mesh is not xyz in tally '//tname
            ErrCha = ''
            ErrID = 'L:27767/R:anatal_ttime/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 4 .and. imesh .ne. 3 ) then

            m_err = 'Axis is y but mesh is not xyz in tally '//tname
            ErrCha = ''
            ErrID = 'L:27774/R:anatal_ttime/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 5 .and. imesh .eq. 1 ) then

            m_err = 'Axis is z but mesh is reg in tally '//tname
            ErrCha = ''
            ErrID = 'L:27781/R:anatal_ttime/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 6 .and. imesh .ne. 2 ) then

            m_err = 'Axis is r but mesh is not r-z in tally '//tname
            ErrCha = ''
            ErrID = 'L:27788/R:anatal_ttime/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 10 .and. imesh .ne. 2 ) then

            m_err = 'Axis is rz,'//
     &              ' but mesh is not r-z in tally '//tname
            ErrCha = ''
            ErrID = 'L:27796/R:anatal_ttime/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 10 .and.
     &           ( irtp .ne. 2 .and. irtp .ne. 4 ) ) then

            m_err = 'Axis is rz,'//
     &              ' but r mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:27805/R:anatal_ttime/F:anatally.f'
            goto 999

         else if( iaxis(i) .eq. 10 .and.
     &           ( iztp .ne. 2 .and. iztp .ne. 4 ) ) then

            m_err = 'Axis is rz,'//
     &              ' but z mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:27814/R:anatal_ttime/F:anatally.f'
            goto 999

         else if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 9 ) .and.
     &           ( ixtp .ne. 2 .and. ixtp .ne. 4 ) ) then

            m_err = 'Axis is xy or zx,'//
     &              ' but x mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:27823/R:anatal_ttime/F:anatally.f'
            goto 999

         else if( ( iaxis(i) .eq. 8 .or. iaxis(i) .eq. 9 ) .and.
     &           ( iztp .ne. 2 .and. iztp .ne. 4 ) ) then

            m_err = 'Axis is yz or zx,'//
     &              ' but z mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:27832/R:anatal_ttime/F:anatally.f'
            goto 999

         else if( ( iaxis(i) .eq. 7 .or. iaxis(i) .eq. 8 ) .and.
     &           ( iytp .ne. 2 .and. iytp .ne. 4 ) ) then

            m_err = 'Axis is xy or yz,'//
     &              ' but y mesh type is not 2 or 4 in tally '//tname
            ErrCha = ''
            ErrID = 'L:27841/R:anatal_ttime/F:anatally.f'
            goto 999

         end if

      end do

*-----------------------------------------------------------------------

      if ( ibmp .ne. 0 ) then

         if ( imesh .ne. 3 ) then

            m_err = 'Mesh should be xyz on bmpout in tally '//tname
            ErrCha = ''
            ErrID = 'L:27856/R:anatal_ttime/F:anatally.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 7 .and.
     &           iaxis(i) .ne. 8 .and.
     &           iaxis(i) .ne. 9 ) then

               m_err = 'Axis should be xy, yz or xz on bmpout'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:27870/R:anatal_ttime/F:anatally.f'
               goto 999

            end if

         end do

      end if

*-----------------------------------------------------------------------

      if ( ivtk .ne. 0 ) then

         if ( imesh .ne. 3 ) then

            m_err = 'Mesh should be xyz on bmpout in tally '//tname
            ErrCha = ''
            ErrID = 'L:27887/R:anatal_ttime/F:anatally.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 7 .and.
     &           iaxis(i) .ne. 8 .and.
     &           iaxis(i) .ne. 9 ) then

               m_err = 'Axis should be xy, yz or xz on bmpout'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:27901/R:anatal_ttime/F:anatally.f'
               goto 999

            end if

         end do

      end if

*-----------------------------------------------------------------------
*        for dump
*-----------------------------------------------------------------------

         if( idump .ne. 0 ) then

            iout = 2

            infil = 1
            inaxi = 1
            iunt  = 1

         end if

*-----------------------------------------------------------------------
*     summary
*-----------------------------------------------------------------------

                  itnm = itnm + 1

                  if( itnm .gt. itlmax ) goto 986

                  ital( itnm ) = 6

                  itsmn(itnm) = 0
                  itstm(itnm) = 0

                  itxnm(itnm) = 0
                  itynm(itnm) = 0
                  itznm(itnm) = 0

*-----------------------------------------------------------------------
*        title
*-----------------------------------------------------------------------

                  ittll(itnm) = titll
                  ittle(itnm) = title

*-----------------------------------------------------------------------
*        angel parameter
*-----------------------------------------------------------------------

               if( langel .gt. 0 ) then

                  itanl(itnm) = langel
                  itang(itnm) = angelp

               else

                  itanl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        x-txt parameter
*-----------------------------------------------------------------------

               if( lxtxt .gt. 0 ) then

                  itaxl(itnm) = lxtxt
                  itaxt(itnm) = cxtxt

               else

                  itaxl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        y-txt parameter
*-----------------------------------------------------------------------

               if( lytxt .gt. 0 ) then

                  itayl(itnm) = lytxt
                  itayt(itnm) = cytxt

               else

                  itayl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        z-txt parameter
*-----------------------------------------------------------------------

               if( lztxt .gt. 0 ) then

                  itazl(itnm) = lztxt
                  itazt(itnm) = cztxt

               else

                  itazl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        gshow parameter
*-----------------------------------------------------------------------

               if( lgshow .gt. 0 ) then

                  itgsh(itnm) = min(5,lgshow)  ! T.Sato 2019/02/20

               else

                  itgsh(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        gslat parameter
*-----------------------------------------------------------------------
                  itglt(itnm) = igslt

*-----------------------------------------------------------------------
*        rshow parameter
*-----------------------------------------------------------------------

                  itrsh(itnm) = min(4,lrshow)

*-----------------------------------------------------------------------
*        mesh
*-----------------------------------------------------------------------

                  itmsh(itnm) = imesh

         if( imesh .eq. 1 ) then

                  itrgn(itnm) = ntrn
                  itrgm(itnm) = mtrn
                  itrnv(itnm) = nvol

            if( ntrn .gt. 0 ) then

                  call moddas_reallocate_int(
     &                    itlmax, itnm, mtrn, itreg, idas_itreg)
                  idas_itreg(itreg(itnm):itreg(itnm)+mtrn-1)
     &                      = idas_itreg_temporary(1:mtrn)
                  call moddas_deallocate_int(idas_itreg_temporary)
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( mtrn + mod(mtrn,2) ) / 2

            end if

            if( nvol .gt. 0 ) then

                  itriv(itnm) = ivl
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( nvol + mod(nvol,2) ) / 2

                  itrrv(itnm) = irvl
                  itsmn(itnm) = itsmn(itnm) + nvol

            end if

         end if

         if( imesh .eq. 2 ) then

                  rtrx0(itnm) = rzx0
                  rtry0(itnm) = rzy0

                  itrty(itnm) = irtp
                  itrnm(itnm) = inr
                  rtrdl(itnm) = rdel
                  rtrmi(itnm) = rmin
                  rtrma(itnm) = rmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inr+1, itrrg, das_itrrg)
                  das_itrrg(itrrg(itnm):itrrg(itnm)+inr)
     &                     = gmsh(istrg:istrg+inr)
                  itsmn(itnm) = itsmn(itnm) + inr + 1

                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)
                  itsmn(itnm) = itsmn(itnm) + inz + 1

         else if( imesh .eq. 3 .or. lrshow .gt. 0 ) then

                  itxty(itnm) = ixtp
                  itxnm(itnm) = inx
                  rtxdl(itnm) = xdel
                  rtxmi(itnm) = xmin
                  rtxma(itnm) = xmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inx+1, itxrg, das_itxrg)
                  das_itxrg(itxrg(itnm):itxrg(itnm)+inx)
     &                     = gmsh(istxg:istxg+inx)
                  itsmn(itnm) = itsmn(itnm) + inx + 1

                  ityty(itnm) = iytp
                  itynm(itnm) = iny
                  rtydl(itnm) = ydel
                  rtymi(itnm) = ymin
                  rtyma(itnm) = ymax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, iny+1, ityrg, das_ityrg)
                  das_ityrg(ityrg(itnm):ityrg(itnm)+iny)
     &                     = gmsh(istyg:istyg+iny)
                  itsmn(itnm) = itsmn(itnm) + iny + 1

                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)
                  itsmn(itnm) = itsmn(itnm) + inz + 1

         end if

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

                  itaxn(itnm) = inaxi

               do i = 1, inaxi

                  itaxs(itnm,i) = iaxis(i)

               end do

*-----------------------------------------------------------------------
*        file
*-----------------------------------------------------------------------

                  itfln(itnm) = infil

               do i = 1, infil

                  itfll(itnm,i) = lfile(i)

                  ctfln(itnm,i)(1:lfile(i)) = ifile(i)(1:lfile(i))

                  do k = lfile(i) + 1, 100

                     ctfln(itnm,i)(k:k) = ' '

                  end do

               end do

*-----------------------------------------------------------------------
*       restart file
*-----------------------------------------------------------------------
               call summary_param_resfile(itnm,irfflg,lrfile,irfile)

*-----------------------------------------------------------------------
*        material
*-----------------------------------------------------------------------

                  itmtn(itnm) = imate
                  itmcn(itnm) = jmate

            if( imate .gt. 0 ) then

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( imate + mod(imate,2) ) / 2

            end if

*-----------------------------------------------------------------------
*        particles
*-----------------------------------------------------------------------

            itmxptt = inpat
            itmxgpt = 1
            do i = 1, inpat
              if ( iptyp(i).lt.0 .and. -iptyp(i).gt.itmxgpt ) then
                itmxgpt = -iptyp(i)
              end if
            end do
            call ALLOCATE_PART_TEMP

            if( inpat .gt. 0 ) then

                  itpan(itnm) = inpat

               do i = 1, inpat

                  itpat(itnm,i,1) = iptyp(i)
                  itpat(itnm,i,2) = ipnkf(i)
                  itpat(itnm,i,3) = ipsub(i)  ! kitamura22/03/31

                  if( itpat(itnm,i,1) .lt. 0 ) then

                     do k = 1, -itpat(itnm,i,1)

                        jtpat(itnm,i,k,1) = imtyp(i,k)
                        jtpat(itnm,i,k,2) = imnkf(i,k)

                     end do

                  end if

               end do

            else if( inpat .eq. 0 ) then

                  itpan(itnm) = 1
                  itpat(itnm,1,1) = 20
                  itpat(itnm,1,2) = 0

            end if

*-----------------------------------------------------------------------
*        energy mesh
*-----------------------------------------------------------------------

                  itety(itnm) = ietp
                  itenm(itnm) = ine
                  rtedl(itnm) = edel
                  rtemi(itnm) = emin
                  rtema(itnm) = emax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, ine+1, iterg, das_iterg)
                  das_iterg(iterg(itnm):iterg(itnm)+ine)
     &                     = gmsh(isteg:isteg+ine)
                  itsmn(itnm) = itsmn(itnm) + ine + 1

*-----------------------------------------------------------------------
*        time mesh
*-----------------------------------------------------------------------

                  ittty(itnm) = ittp
                  ittnm(itnm) = int
                  rttdl(itnm) = tdel
                  rttmi(itnm) = tmin
                  rttma(itnm) = tmax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, int+1, ittrg, das_ittrg)
                  das_ittrg(ittrg(itnm):ittrg(itnm)+int)
     &                     = gmsh(isttg:isttg+int)
                  itsmn(itnm) = itsmn(itnm) + int + 1

*-----------------------------------------------------------------------
*        transformation
*-----------------------------------------------------------------------

                     itmtr(itnm,1) = igkst
                     itmtr(itnm,2) = ktrs
                     itmtr(itnm,3) = idtt
                     itmtr(itnm,4) = 0

               if( igkst .gt. 1 ) then

                  do k = 1, 13

                     rtmtr(itnm,k) = vtrs(k)

                  end do

               end if

*-----------------------------------------------------------------------
*        output
*-----------------------------------------------------------------------

                  itout(itnm) = iout

*-----------------------------------------------------------------------
*        reg echo length
*-----------------------------------------------------------------------

                  iterl(itnm) = iechrl

*-----------------------------------------------------------------------
*        unit
*-----------------------------------------------------------------------

                  itunt(itnm) = iunt

*-----------------------------------------------------------------------
*        2D-type
*-----------------------------------------------------------------------

                  ittwo(itnm) = idtyp

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

                  rtfac(itnm) = rfact

*-----------------------------------------------------------------------
*        volmat
*-----------------------------------------------------------------------

                  itvm(itnm) = matvol

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

                  iteps(itnm) = ieps

*-----------------------------------------------------------------------
*        bmpout
*-----------------------------------------------------------------------

                  itbmp(itnm) = ibmp

*-----------------------------------------------------------------------
*        vtkout
*-----------------------------------------------------------------------

                  itvtk(itnm) = ivtk

*-----------------------------------------------------------------------
*        vtkfmt
*-----------------------------------------------------------------------

                  itvtkfmt(itnm) = ivtkfmt

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

                  itres(itnm) = max( 1, ireso )

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

                  rtwid(itnm) = width

*-----------------------------------------------------------------------
*        counter
*-----------------------------------------------------------------------

               do i = 1, 9

                  itcnt(i,itnm) = icount(i)
                  itcnth(i,itnm) = icounth(i) !frtati 2021/04/06

               end do

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

                  itger(itnm) = infog

*-----------------------------------------------------------------------
*        stdcut
*-----------------------------------------------------------------------
                  rtstd(itnm) = stdcut

*-----------------------------------------------------------------------
*        maxangel
*-----------------------------------------------------------------------
                  itmxang(itnm) = imxang

*-----------------------------------------------------------------------
*        samepage
*-----------------------------------------------------------------------
                  itpgn(itnm) = inpgi

               do i = 1, inpgi

                  itpgs(itnm,i) = ipgis(i)

               end do

*-----------------------------------------------------------------------
*        xy, yz, zx, rz storage region
*-----------------------------------------------------------------------

                     mxyz = 1
                     mrzr = 1
                     mrzz = 1

                  do i = 1, inaxi

                     if( iaxis(i) .eq. 7 ) then

                        if( inx .gt. mxyz ) mxyz = inx
                        if( iny .gt. mxyz ) mxyz = iny

                     else if( iaxis(i) .eq. 8 ) then

                        if( iny .gt. mxyz ) mxyz = iny
                        if( inz .gt. mxyz ) mxyz = inz

                     else if( iaxis(i) .eq. 9 ) then

                        if( inx .gt. mxyz ) mxyz = inx
                        if( inz .gt. mxyz ) mxyz = inz

                     else if( iaxis(i) .eq. 10 ) then

                        mrzr = inr
                        mrzz = inz

                     end if

                  end do

                     itnfn(itnm) = mxyz
                     itnfr(itnm) = mrzr
                     itnfz(itnm) = mrzz

*-----------------------------------------------------------------------
*        dump
*-----------------------------------------------------------------------

                  itmdp(itnm,0) = idump

               if( idump .ne. 0 ) then

                  do i = 1, abs( idump )

                     itmdp(itnm,i) = jdump(i)

                  end do

               end if

*-----------------------------------------------------------------------

      return

*-----------------------------------------------------------------------
*     errors
*-----------------------------------------------------------------------

  950    write(dkam,'(i9)') mdas
         m_err = 'Total tally storage number exceeds mdas ='//dkam
         ErrCha = ''
         ErrID = 'L:28455/R:anatal_ttime/F:anatally.f'
         goto 999

  977    m_err = 'dump id should be 1 - 20.'
         ErrCha = ''
         ErrID = 'L:28460/R:anatal_ttime/F:anatally.f'
         goto 999

  976    m_err = 'Description of dump parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:28466/R:anatal_ttime/F:anatally.f'
         goto 999

  978    m_err = 'counter should be from -9999 to 9999'
         ErrCha = ''
         ErrID = 'L:28471/R:anatal_ttime/F:anatally.f'
         goto 999

  979    m_err = 'Description of material parameter is wrong in tally '
     &            //tname
         ErrCha = ''
         ErrID = 'L:28477/R:anatal_ttime/F:anatally.f'
         goto 999

  980    m_err = 'unit should be 1, 2, 3 or 4 in tally '//tname
         ErrCha = ''
         ErrID = 'L:28482/R:anatal_ttime/F:anatally.f'
         goto 999

  983    m_err = '2D-type should be 1-7 in tally '//tname
         ErrCha = ''
         ErrID = 'L:28487/R:anatal_ttime/F:anatally.f'
         goto 999

  984    m_err = 'Unknown output parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:28492/R:anatal_ttime/F:anatally.f'
         goto 999

  986    write(dkam,'(i5)') itlmax
         m_err = 'Total tally number exceeds itlmax = '//dkam
         ErrCha = ''
         ErrID = 'L:28498/R:anatal_ttime/F:anatally.f'
         goto 999

  987    m_err = 'Unknown parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:28503/R:anatal_ttime/F:anatally.f'
         goto 999

  989    m_err = 'Double definition of the parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:28508/R:anatal_ttime/F:anatally.f'
         goto 999

  990    m_err = 'Too many file name in tally '//tname
         ErrCha = ''
         ErrID = 'L:28513/R:anatal_ttime/F:anatally.f'
         goto 999

  991    m_err = 'Too many axis in tally '//tname
         ErrCha = ''
         ErrID = 'L:28518/R:anatal_ttime/F:anatally.f'
         goto 999

  992    m_err = 'Unknown axis name in tally '//tname
         ErrCha = ''
         ErrID = 'L:28523/R:anatal_ttime/F:anatally.f'
         goto 999

  993    m_err = 'In this line, [ ; ] cannot be used.'
         ErrCha = ''
         ErrID = 'L:28528/R:anatal_ttime/F:anatally.f'
         goto 999

  994    m_err = 'Name of particle is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:28533/R:anatal_ttime/F:anatally.f'
         goto 999

cfrtati 2021/10/05 6 -> mxpart
  995    m_err = 'Number of particles is larger than mxpart in '//tname
         ErrCha = ''
         ErrID = 'L:28539/R:anatal_ttime/F:anatally.f'
         goto 999

  996    m_err = 'Description of mesh is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:28544/R:anatal_ttime/F:anatally.f'
         goto 999

  997    m_err = 'Description of parameter is wrong in tally '//tname
         ErrCha = ''
         ErrID = 'L:28549/R:anatal_ttime/F:anatally.f'
         goto 999

  998    m_err = 'Unknown mesh parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:28554/R:anatal_ttime/F:anatally.f'
         goto 999

 1045    m_err = 'Too many samepage in tally '//tname
         ErrCha = ''
         ErrID = 'L:28559/R:anatal_ttime/F:anatally.f'
         goto 999

 1046    m_err = 'samepage should be wwg, reg,eng,t,xy,yz,zx,x,y,z'
     &           //' in tally '//tname
         ErrCha = ''
         ErrID = 'L:28565/R:anatal_ttime/F:anatally.f'
         goto 999

*-----------------------------------------------------------------------

  999 continue

         l_err = ill(jsn)
         k_err = jsn
         ierr  = 1

*-----------------------------------------------------------------------

      return
      end subroutine anatal_ttime


************************************************************************
*                                                                      *
      subroutine anatal_tdpa(jsn,jsi,dsin,idsi,ill,ilf,
     &                       jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr)
*                                                                      *
*       read [t-dpa] section of tally files                            *
*       modified by K.Niita on 2004/09/15                              *
*       last modified by Y. Iwamoto on 2020/12/22                      *
*                                                                      *
************************************************************************
      use sangelmod, only: itsanf
      use anatallymod, only: nanatalRead
      use partmod ! frtati 2021/10/05
      use moddas
      use moddas_mesh
      use moddas_region
      use moddas_tally

      implicit real*8 (a-h,o-z)

      parameter(icsu=50) ! nais 2023/01/06

      include 'param.inc'
      include 'param01.inc'
      include 'err.inc'

*-----------------------------------------------------------------------

      common /tall00/ itnm, ital(itlmax), itals(itlmax), italm(itlmax)
      common /tall01/ itmsh(itlmax), itunt(itlmax), itspc(itlmax),
     &                itout(itlmax), ittwo(itlmax)

      common /tall02/ itrgn(itlmax), itrgm(itlmax), itreg(itlmax)
      common /tall25/ itrnv(itlmax), itriv(itlmax), itrrv(itlmax)

      common /tall03/ itrty(itlmax), itrnm(itlmax), itrrg(itlmax),
     &                rtrmi(itlmax), rtrma(itlmax), rtrdl(itlmax)
      common /tall04/ itxty(itlmax), itxnm(itlmax), itxrg(itlmax),
     &                rtxmi(itlmax), rtxma(itlmax), rtxdl(itlmax)
      common /tall05/ ityty(itlmax), itynm(itlmax), ityrg(itlmax),
     &                rtymi(itlmax), rtyma(itlmax), rtydl(itlmax)
      common /tall06/ itzty(itlmax), itznm(itlmax), itzrg(itlmax),
     &                rtzmi(itlmax), rtzma(itlmax), rtzdl(itlmax)


      common /tall08/ rtrx0(itlmax), rtry0(itlmax)

      common /tall10/ itaxn(itlmax), itaxs(itlmax,6)
      common /tall11/ itfln(itlmax), itfll(itlmax,6), ctfln(itlmax,6)
      character ctfln*100

      common /tall12/ itman(itlmax), itmat(itlmax), itmct(itlmax),
     &                itnun(itlmax), itnuc(itlmax),
     &                itndz(itlmax), itndn(itlmax),
     &                itnkz(itlmax), itnkn(itlmax)

      common /tall16/ itnfr(itlmax), itnfz(itlmax), itnfn(itlmax)

      common /tall14/ ittll(itlmax), ittle(itlmax)
      character ittle*80

      common /tall15/ itanl(itlmax), itang(itlmax)
      character itang*200

      common /tall27/ itaxl(itlmax), itaxt(itlmax),
     &                itayl(itlmax), itayt(itlmax),
     &                itazl(itlmax), itazt(itlmax)
      character itaxt*200, itayt*200, itazt*200

      common /tall17/ itndy(itlmax)

      common /tall19/ itsmn(itlmax), itstm(itlmax)

      common /tall21/ rtfac(itlmax)
      common /tall22/ itmcn(itlmax), itmtn(itlmax), itmtt(itlmax)

      common /tall28/ itgsh(itlmax)
      common /tall29/ itrsh(itlmax)
      common /tall31/ iterl(itlmax)

      common /tall33/ itln(itlmax,2), itli(itlmax,2), itlr(itlmax,2),
     &                rtdm(itlmax,2)
      common /tall34/ itvm(itlmax)
      common /tall35/ iteps(itlmax)
      common /tall37/ itcnt(9,itlmax)

      common /tall38/ itres(itlmax)
      common /tall39/ rtwid(itlmax)
      common /tall46/ itmtr(itlmax,4), rtmtr(itlmax,13)

      common /tall49/ itglt(itlmax)

!OBINATA: for resfile
      common /tall59/ irfll(itlmax), crfln(itlmax), itrff(itlmax)
      character crfln*100
      character irfile*100

      common /tall60/ itger(itlmax)
      common /tall63/ itbmp(itlmax)
      common /tall64/ itvtk(itlmax),itvtkfmt(itlmax)

      common /tall67/ itstd(itlmax), rtstd(itlmax)
      common /paraj/  mstz(300), parz(300) ! S.H. 2022.1.21

      integer :: itfoam
      common /tall76/ itfoam(itlmax)

      integer :: itdpa
      integer :: iteth
      common /tall80/ itdpa(itlmax)
      common /tall81/ iteth(itlmax)

      common /tall82/ itcnth(9,itlmax)
      dimension icounth(9)

! 20230106 nais samepage
      common /tall90/ itpgn(itlmax), itpgs(itlmax,6)

      dimension idas(mdas*2)
      equivalence ( das, idas )

*-----------------------------------------------------------------------

      character m_err*200
      common /error/ m_err, l_err, k_err

      common /kmat1d/ idmn(0:kvlmax), idnm(kvmmax)

*-----------------------------------------------------------------------

      character title*80
      character angelp*200
      character cxtxt*200
      character cytxt*200
      character cztxt*200

*-----------------------------------------------------------------------
      dimension lschn(icsu), ischn(icsu)
      character schan(icsu)*8


      data ( schan(i), i = 1, icsu ) /
     &    'mesh    ','part    ','mother  ','axis    ','file    ',
     &    'title   ','angel   ','unit    ','2d-type ','output  ',
     &    'factor  ','material','x-txt   ','y-txt   ','z-txt   ',
     &    'gshow   ','rshow   ','iechrl  ','library ','volmat  ',
     &    'epsout  ','ctmin(1)','ctmax(1)','ctmin(2)','ctmax(2)',
     &    'ctmin(3)','ctmax(3)','resol   ','width   ','trcl    ',
     &    '*trcl   ','gslat   ','resfile ','ginfo   ','bmpout  ',
     &    'vtkout  ','vtkfmt  ','stdcut  ','sangel  ','foamout ',
     &    'idpa    ','ieth    ','chmin(1)','chmax(1)','chmin(2)',
     &    'chmax(2)','chmin(3)','chmax(3)','maxangel','samepage'/

      data ( lschn(i), i = 1, icsu ) /
     &     4,         4,         6,         4,         4,
     &     5,         5,         4,         7,         6,
     &     6,         8,         5,         5,         5,
     &     5,         5,         6,         7,         6,
     &     6,         8,         8,         8,         8,
     &     8,         8,         5,         5,         4,
     &     5,         5,         7,         5,         6,
     &     6,         6,         6,         6,         7,
     &     4,         4,         8,         8,         8,
     &     8,         8,         8,         8,         8/

*-----------------------------------------------------------------------


*-----------------------------------------------------------------------

cfrtati 2021/10/05 6 -> mxpart
      dimension iptyp(mxpart), ipnkf(mxpart)
      dimension imtyp(mxpart,mxpart), imnkf(mxpart,mxpart)
      dimension jstyp(mxpart), jnkf0(mxpart)

      common /subtra/ isubt, ipsub(mxpart)  ! kitamura22/03/31

      dimension iaxis(6)
      character ifile(6)*100
      dimension lfile(6)

      dimension ipgis(6)   ! samepage nais 2023/01/06

*-----------------------------------------------------------------------

      character chin*200, chlw*200, chcm*200
      character chlc*200

      character dsin(0:9)*200
      dimension idsi(0:9)

      dimension ill(0:9), ilf(0:9)

      character dkam*9

      character tname*7
      data      tname /'[t-dpa]'/

      logical deqn1
      logical deqn4
      logical dcom2

      dimension icount(9)
      dimension vtrs(13)

      integer isumtalRead

*-----------------------------------------------------------------------

      character element(104)*3,cnuc*3

      data element/
     & 'h  ','he ','li ','be ','b  ','c  ','n  ','o  ',
     & 'f  ','ne ','na ','mg ','al ','si ','p  ','s  ',
     & 'cl ','ar ','k  ','ca ','sc ','ti ','v  ','cr ',
     & 'mn ','fe ','co ','ni ','cu ','zn ','ga ','ge ',
     & 'as ','se ','br ','kr ','rb ','sr ','y  ','zr ',
     & 'nb ','mo ','tc ','ru ','rh ','pd ','ag ','cd ',
     & 'in ','sn ','sb ','te ','i  ','xe ','cs ','ba ',
     & 'la ','ce ','pr ','nd ','pm ','sm ','eu ','gd ',
     & 'tb ','dy ','ho ','er ','tm ','yb ','lu ','hf ',
     & 'ta ','w  ','re ','os ','ir ','pt ','au ','hg ',
     & 'tl ','pb ','bi ','po ','at ','rn ','fr ','ra ',
     & 'ac ','th ','pa ','u  ','np ','pu ','am ','cm ',
     & 'bk ','cf ','es ','fm ','md ','no ','lr ','ku '/

*-----------------------------------------------------------------------

            ierr  = 0

            inmat = 0
            inpat = 0
            inaxi = 0
            infil = 0
            imoth = 0
            jmoth = 1
            imate = 0
            jmate = 1
            iunt  = 1
            iout  = 1
            idtyp = 3

            jtlnn = 0
            jtlin = 0
            jtlrn = 0
            jtlnp = 0
            jtlip = 0
            jtlrp = 0
            dlmxn = -1.0
            dlmxp = -1.0

            langel = 0
            itsanf = 0
            lxtxt  = 0
            lytxt  = 0
            lztxt  = 0
            lgshow = 0
            lrshow = 0
            iechrl = 72
            matvol = 9
            ieps   = 0
            ibmp   = 0
            ivtk   = 0
            ivtkfmt= 0
            igkst  = 0
            idtt   = 0
            ktrs   = 0
            igslt  = -1

            lrfile = 0 !OBINATA
            irfflg = 0 !OBINATA
            ifoam  = 0 !FURUTA20190208
            imxang = 0 ! frtati 2021/10/05

            icount(1) = 0
            icount(2) = 0
            icount(3) = 0
            icount(4) = -9999
            icount(5) =  9999
            icount(6) = -9999
            icount(7) =  9999
            icount(8) = -9999
            icount(9) =  9999
            icounth(1) = 0
            icounth(2) = 0
            icounth(3) = 0
            icounth(4) = -9999
            icounth(5) =  9999
            icounth(6) = -9999
            icounth(7) =  9999
            icounth(8) = -9999
            icounth(9) =  9999

            ireso = 1
            width = 0.5

            rfact = 1.0

         do i = 1, icsu

            ischn(i) = 0

         end do

            infog = 0

         inpgi = 0   ! samepage 2023/01/06

       isumtalRead = 0

            stdcut = -1.0

            iidpa = 0
	    iieth = 0

*-----------------------------------------------------------------------
*     read one line from jsi
*-----------------------------------------------------------------------

  140 continue

            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*.......................................................................
*        end of reading header info. (from tally file)
*.......................................................................
            if( i1 .ne. 0 ) then !20221004frtati fbounds-check
              if( mstz(1) .eq. 17 .and.
     &           chin(i1:i1+25) .eq. '#-------------------------' ) then
                 jpn = 1
                 goto 800
              end if
            end if

               if( iskip .ne. 0 ) goto 140

  150 continue

               if( ierr .ne. 0 ) return
               if( jpn  .eq. 3 ) goto 800

*-----------------------------------------------------------------------
*        end of the section
*-----------------------------------------------------------------------

            if( chlw(i1:i1) .eq. '[' ) then

               jpn = 1
               goto 800

            end if

*-----------------------------------------------------------------------
*        identify the parameters
*-----------------------------------------------------------------------

            icl = i1

!-----------------------------------------------------------------------
!        sumtally sub section
!-----------------------------------------------------------------------
      if ( chlw(i1:i3) .eq. 'sumtally start' ) then
       isumtalRead = 1
       call read_sumtal(jsn,jsi,dsin,idsi,ill,ilf,
     &                 jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
       if( ierr .ne. 0 ) return
       if( jpn == 3 ) goto 800   ! 'q:'
       if( jpn == 1 ) goto 800   ! end of the section
       go to 140
      end if

*-----------------------------------------------------------------------
*        anatally
*-----------------------------------------------------------------------

      if ( chlw(i1:i3) .eq. 'anatally start' ) then

         if (  mstz(1) .eq. 17 ) then
            nanatalRead(1+itnm) = 1
            call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &           jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)
            if ( chlw(i1:i3) .ne. 'anatally end' ) then
               ierr = 1
            end if
         else

            istbat = 1

            call stbatm(jsn,jsi,dsin,idsi,ill,ilf,
     &                  jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                  ist_nm,isd_nm,kst_nm)

            if( ierr .ne. 0 ) return
            if( jpn == 3 ) goto 800   ! 'q:'
            if( jpn == 1 ) goto 800   ! end of the section

         end if ! S.H. (2020.2.25)
            goto 140

      end if

*-----------------------------------------------------------------------

  200    continue

            chlc = chlw
            call chcomp(chlc,icl,i3,i5)

         do i = 1, icsu

            il = icl + lschn(i) - 1

            if( chlc(icl:il) .eq. schan(i)(1:lschn(i)) ) goto 100

         end do

               goto 987

*-----------------------------------------------------------------------
*        read value of parameters
*-----------------------------------------------------------------------

  100    continue

               ipm = i

               ischn( ipm ) = ischn( ipm ) + 1

            if( ipm .ne. 4 .and. ipm .ne. 5 .and. ipm .ne. 19 .and.
     &          ipm .ne. 2 .and.
     &          ipm .ne. 33 .and.
     &          ischn( ipm ) .gt. 1 ) goto 989 ! frtati 2021/10/05

               ic = inumc(chlw,il+1,i3,'=') + 1
               ic = jnumc(chlw,ic,i3)

               if( ic .gt. i3 ) goto 997

               icl = inumc(chlw,ic,i3,';') - 1

*-----------------------------------------------------------------------
*        mesh = region, r-z, xyz, or tet
*-----------------------------------------------------------------------

         if( ipm .eq. 1 ) then

            if( chlw(ic:ic+2) .eq. 'reg' ) then

               imesh = 1

            else if( chlw(ic:ic+2) .eq. 'r-z' ) then

               imesh = 2

            else if( chlw(ic:ic+2) .eq. 'xyz' ) then

               imesh = 3

            else if( chlw(ic:ic+2) .eq. 'tet' ) then
               imesh = 4

            else

               goto 998

            end if

            if( chlw(icl+1:icl+1) .eq. ';' ) goto 993

            if( imesh .eq. 1 ) then

               call moddas_allocate_int(
     &                 MAX_NUM_ITREG, idas_itreg_temporary)

               ndsm = 1
               call tregion(1,jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ntrn,mtrn,ndsm,nvol,ivl,irvl,0
     &                      ,MAX_NUM_ITREG,idas_itreg_temporary)

               if( mtrn > MAX_NUM_ITREG ) then
                  write(ErrCha,'(a,a,i5,a,a,i5,a)')
     &                 'sub.tdpa@tallsm2.f'
     &                    //' ?dimension over idas_itreg_temporary?'
     &                    //' mtrn > MAX_NUM_ITREG'
     &                 ,' (mtrn=',mtrn,')'
     &                 ,' (MAX_NUM_ITREG@moddas.f=',MAX_NUM_ITREG,')'
                  ErrID = 'L:29073/R:anatal_tdpa/F:anatally.f'
                  call ErrWrite(ErrID,ErrCha)
               endif

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ntrn .lt. -1 ) goto 996

            else if( imesh .eq. 2 ) then

               call trzmesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      rzx0,rzy0,
     &                      irtp,inr,rmin,rmax,rdel,istrg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( irtp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            else if( imesh .eq. 3 ) then

               call txymesh(jsn,jsi,dsin,idsi,ill,ilf,
     &                      jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &                      ixtp,inx,xmin,xmax,xdel,istxg,
     &                      iytp,iny,ymin,ymax,ydel,istyg,
     &                      iztp,inz,zmin,zmax,zdel,istzg)

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800
                  if( ixtp .lt. 0 ) goto 996
                  if( iytp .lt. 0 ) goto 996
                  if( iztp .lt. 0 ) goto 996

            else if( imesh .eq. 4 ) then

               call moddas_allocate_int(
     &                 MAX_NUM_ITREG, idas_itreg_temporary)

               call ttetmesh(jsn,jsi,dsin,idsi,ill,ilf,
     &              jpn,chin,chlw,chcm,i1,i2,i3,i4,ierr,
     &              mtrn,ntrn,
     &              MAX_NUM_ITREG,idas_itreg_temporary)

               if( mtrn > MAX_NUM_ITREG ) then
                  write(ErrCha,'(a,a,i5,a,a,i5,a)')
     &                 'sub.ttrack@tallsm2.f'
     &                    //' ?dimension over idas_itreg_temporary?'
     &                    //' mtrn > MAX_NUM_ITREG'
     &                 ,' (mtrn=',mtrn,')'
     &                 ,' (MAX_NUM_ITREG@moddas.f=',MAX_NUM_ITREG,')'
                  ErrID = 'L:29125/R:anatal_tdpa/F:anatally.f'
                  call ErrWrite(ErrID,ErrCha)
               endif

                  if( ierr .ne. 0 ) return
                  if( jpn  .eq. 3 ) goto 800

            end if

                  goto 150

*-----------------------------------------------------------------------
*        particle name
*-----------------------------------------------------------------------

         else if( ipm .eq. 2 ) then

  400       continue

               ic = jnumc(chlw,ic,icl)

               if( ic .gt. icl ) then

                  icl = jnumc(chlw,icl+2,i3)

                  if( icl .le. i3 ) goto 200

                  goto 140

               end if

*-----------------------------------------------------------------------

            call rdpname(ic,icl,chlw,istyp,inkf0,jstyp,jnkf0,ierr)

               if( ierr .eq. 994 ) goto 994
               if( ierr .eq. 998 ) goto 997

*-----------------------------------------------------------------------

               inpat = inpat + 1

               if( inpat .gt. mxpart ) goto 995

                  iptyp(inpat) = istyp
                  ipnkf(inpat) = inkf0
                  ipsub(inpat) = isubt  ! kitamura22/03/31

               if( istyp .lt. 0 ) then

                  do i = 1, -istyp

                     imtyp(inpat,i) = jstyp(i)
                     imnkf(inpat,i) = jnkf0(i)

                  end do

               end if

               goto 400

*-----------------------------------------------------------------------
*        material
*-----------------------------------------------------------------------

         else if( ipm .eq. 12 ) then

            if( chlw(ic:ic+2) .eq. 'all' ) then

                  imate = 0

            else if( deqn4( chlw(ic:ic) ) ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 981

                  imate = nint( cvvv )

               if( imate .lt. 0 ) then

                  imate = -imate
                  jmate = -1

               end if

               if( imate .eq. 0 ) goto 981

                  nsmte = itmtt(itnm+1)
                  call moddas_reallocate_int(
     &                    itlmax, itnm+1, imate, itmtt, ismte)
                  if( mmmax .gt. mdas ) goto 950

  151                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                        if( ierr .ne. 0 ) return
                        if( jpn  .eq. 3 ) goto 981

                        if( iskip .ne. 0 ) goto 151

                  ic = i1

               do k = 1, imate

                  if( ic .gt. i3 ) then

  152                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                     if( ierr .ne. 0 ) return
                     if( jpn  .eq. 3 ) goto 981

                     if( iskip .ne. 0 ) goto 152

                     ic = i1

                  end if

                     ic = jnumc(chlw,ic,i3)

                     call snum(chlw,ic,i3,ic2,cvvv,ierr)

                     if( ierr .ne. 0 ) goto 981

                     matei = nint( cvvv )

                     ic = ic2

                     ismte(nsmte-1+k) = matei

               end do

            else

               goto 981

            end if

*-----------------------------------------------------------------------
*        mother
*-----------------------------------------------------------------------

         else if( ipm .eq. 3 ) then

            if( chlw(ic:ic+2) .eq. 'all' ) then

               imoth = 0

            else if( deqn4( chlw(ic:ic) ) ) then

               call onum(chlw,ic,icl,cvvv,ierr)

               if( ierr .ne. 0 ) goto 997

               imoth = nint( cvvv )

               if( imoth .lt. 0 ) then

                  imoth = -imoth
                  jmoth = -1

               end if

               if( imoth .eq. 0 ) goto 982

                  nsmat = itmat(itnm+1)
                  call moddas_reallocate_int(
     &                    itlmax, itnm+1, imoth, itmat, ismat)
                  if( mmmax .gt. mdas ) goto 950

  145                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                        if( ierr .ne. 0 ) return
                        if( jpn  .eq. 3 ) goto 982

                        if( iskip .ne. 0 ) goto 145

                  ic = i1

               do k = 1, imoth

                  if( ic .gt. i3 ) then

  146                call readl(jsn,jsi,dsin,idsi,ill,ilf,'#!$',
     &                    jpn,chin,chlw,chcm,i1,i2,i3,i4,iskip,ierr)

                     if( ierr .ne. 0 ) return
                     if( jpn  .eq. 3 ) goto 982

                     if( iskip .ne. 0 ) goto 146

                     ic = i1

                  end if

                        ic = jnumc(chlw,ic,i3)

                        isa = 0
                        isn = 0

                        ica = 0
                        icb = 0
                        icm = 0
                        icn = 0

                     do i = ic, i3

                        if( chlw(i:i) .ge. 'a' .and.
     &                      chlw(i:i) .le. 'z' ) then

                           isa = isa + 1

                           if( isa .eq. 1 ) ica = i

                           icb = i

                        else if( deqn1( chlw(i:i) ) ) then

                           isn = isn + 1

                           if( isn .eq. 1 ) icm = i

                           icn = i

                        else if( dcom2( chlw(i:i) ) .or.
     &                           i .eq. i3 ) then

                           icd = i
                           goto 502

                        else

                           goto 982

                        end if

                     end do

                        icd = i3

  502                continue

                     if( ica .eq. 0 .or. icb .eq. 0 ) goto 982
                     if( icb-ica .lt. 0 .or. icb-ica .gt. 1 ) goto 982

                     cnuc = chlw(ica:icb)//'  '

                     do j = 1, 104

                        if( cnuc(1:3) .eq. element(j)(1:3) ) then

                           icha = j

                           goto 452

                        end if

                     end do

                           goto 982

  452                continue

                     if( icha .gt. 104 )  goto 982

                  if( icm .eq. 0 .or. icn .eq. 0 ) then

                     ismat(nsmat-1+k) = icha * 1000

                  else

                     if( isn .gt. 3 ) goto 982

                     read(chlw(icm:icn),'(i5)') masi

                     if( masi .lt. icha ) goto 982
                     if( masi-icha .gt. maxnt ) goto 982

