     &              ' in tally '//tname
            ErrCha = ''
            ErrID = 'L:32994/R:anatal_tprodct/F:anatally.f'
            goto 999

CCSE added for LET parameter (2022.12.09) >>>>>
         else if ( ieng2let.eq.1 .and. iaxis(inaxi).eq.1 ) then  ! if axis=eng
            write(6,'(a73)') 'Warning: axis of eng in '// tname //
     &                         ' is changed to let because eng2let = 1'
            iaxis(inaxi) = 15

         else if ( ieng2let.eq.0 .and. iaxis(inaxi).eq.15 ) then ! if axis=let
            write(6,'(a73)') 'Warning: axis of let in '// tname //
     &                         ' is changed to eng because eng2let = 0'
            iaxis(inaxi) = 1

         end if

      end do

*-----------------------------------------------------------------------

      if ( ibmp .ne. 0 ) then

         if ( imesh .ne. 3 ) then

            m_err = 'Mesh should be xyz on bmpout in tally '//tname
            ErrCha = ''
            ErrID = 'L:33020/R:anatal_tprodct/F:anatally.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 7 .and.
     &           iaxis(i) .ne. 8 .and.
     &           iaxis(i) .ne. 9 ) then

               m_err = 'Axis should be xy, yz or xz on bmpout'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:33034/R:anatal_tprodct/F:anatally.f'
               goto 999

            end if

         end do

      end if

*-----------------------------------------------------------------------

      if ( ivtk .ne. 0 ) then

         if ( imesh .ne. 3 ) then

            m_err = 'Mesh should be xyz on bmpout in tally '//tname
            ErrCha = ''
            ErrID = 'L:33051/R:anatal_tprodct/F:anatally.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 7 .and.
     &           iaxis(i) .ne. 8 .and.
     &           iaxis(i) .ne. 9 ) then

               m_err = 'Axis should be xy, yz or xz on bmpout'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:33065/R:anatal_tprodct/F:anatally.f'
               goto 999

            end if

         end do

      end if

*-----------------------------------------------------------------------

      if( iout .eq. 9 ) then

         if( imoth .ne. 0 ) then

               m_err = 'Only mother=all is allowed for output=atomic'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:33083/R:anatal_tprodct/F:anatally.f'
               goto 999

         endif

      endif

*-----------------------------------------------------------------------
      if ( ifoam .ne. 0 ) then

         if ( imesh .ne. 4 ) then

            m_err = 'Mesh should be tet on foamout in tally '//tname
            ErrCha = ''
            ErrID = 'L:33097/R:anatal_tprodct/F:anatally.f'
            goto 999

         end if

         do i = 1, inaxi

            if ( iaxis(i) .ne. 14 ) then

               m_err = 'Axis should be tet on foamout'//
     &                 ' in tally '//tname
               ErrCha = ''
               ErrID = 'L:33109/R:anatal_tprodct/F:anatally.f'
               goto 999

            end if

         end do

      end if

*-----------------------------------------------------------------------
*        for dump
*-----------------------------------------------------------------------

         if( idump .ne. 0 ) then

            infil = 1
            inaxi = 1
            iunt  = 1

         end if

*-----------------------------------------------------------------------
*     summary
*-----------------------------------------------------------------------

                  itnm = itnm + 1

                  if( itnm .gt. itlmax ) goto 986

                  ital( itnm ) = 8

                  itsmn(itnm) = 0
                  itstm(itnm) = 0

                  itxnm(itnm) = 0
                  itynm(itnm) = 0
                  itznm(itnm) = 0

*-----------------------------------------------------------------------
*        title
*-----------------------------------------------------------------------

                  ittll(itnm) = titll
                  ittle(itnm) = title

*-----------------------------------------------------------------------
*        angel parameter
*-----------------------------------------------------------------------

               if( langel .gt. 0 ) then

                  itanl(itnm) = langel
                  itang(itnm) = angelp

               else

                  itanl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        x-txt parameter
*-----------------------------------------------------------------------

               if( lxtxt .gt. 0 ) then

                  itaxl(itnm) = lxtxt
                  itaxt(itnm) = cxtxt

               else

                  itaxl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        y-txt parameter
*-----------------------------------------------------------------------

               if( lytxt .gt. 0 ) then

                  itayl(itnm) = lytxt
                  itayt(itnm) = cytxt

               else

                  itayl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        z-txt parameter
*-----------------------------------------------------------------------

               if( lztxt .gt. 0 ) then

                  itazl(itnm) = lztxt
                  itazt(itnm) = cztxt

               else

                  itazl(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        gshow parameter
*-----------------------------------------------------------------------

               if( lgshow .gt. 0 ) then

                  itgsh(itnm) = min(5,lgshow)  ! T.Sato 2019/02/20

               else

                  itgsh(itnm) = 0

               end if

*-----------------------------------------------------------------------
*        gslat parameter
*-----------------------------------------------------------------------
                  itglt(itnm) = igslt

*-----------------------------------------------------------------------
*        rshow parameter
*-----------------------------------------------------------------------

                  itrsh(itnm) = min(4,lrshow)

*-----------------------------------------------------------------------
*        material
*-----------------------------------------------------------------------

                  itmtn(itnm) = imate
                  itmcn(itnm) = jmate

            if( imate .gt. 0 ) then

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( imate + mod(imate,2) ) / 2

            end if

*-----------------------------------------------------------------------
*        mother
*-----------------------------------------------------------------------

                  itman(itnm) = imoth
                  itmct(itnm) = jmoth

               if( imoth .gt. 0 ) then

                  itsmn(itnm) = itsmn(itnm)
     &                        + ( imoth + mod(imoth,2) ) / 2

               end if

*-----------------------------------------------------------------------
*        mesh
*-----------------------------------------------------------------------

                  itmsh(itnm) = imesh

         if( imesh .eq. 1 ) then

                  itrgn(itnm) = ntrn
                  itrgm(itnm) = mtrn
                  itrnv(itnm) = nvol

            if( ntrn .gt. 0 ) then

                  call moddas_reallocate_int(
     &                    itlmax, itnm, mtrn, itreg, idas_itreg)
                  idas_itreg(itreg(itnm):itreg(itnm)+mtrn-1)
     &                      = idas_itreg_temporary(1:mtrn)
                  call moddas_deallocate_int(idas_itreg_temporary)
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( mtrn + mod(mtrn,2) ) / 2

            end if

            if( nvol .gt. 0 ) then

                  itriv(itnm) = ivl
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( nvol + mod(nvol,2) ) / 2

                  itrrv(itnm) = irvl
                  itsmn(itnm) = itsmn(itnm) + nvol

            end if

         else if( imesh .eq. 4 ) then

                  itrgn(itnm) = ntrn
                  itrgm(itnm) = mtrn
                  itrnv(itnm) = 0

            if( ntrn .gt. 0 ) then

                  call moddas_reallocate_int(
     &                    itlmax, itnm, mtrn, itreg, idas_itreg)
                  idas_itreg(itreg(itnm):itreg(itnm)+mtrn-1)
     &                      = idas_itreg_temporary(1:mtrn)

            end if

         end if

         if( imesh .eq. 2 ) then

                  rtrx0(itnm) = rzx0
                  rtry0(itnm) = rzy0

                  itrty(itnm) = irtp
                  itrnm(itnm) = inr
                  rtrdl(itnm) = rdel
                  rtrmi(itnm) = rmin
                  rtrma(itnm) = rmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inr+1, itrrg, das_itrrg)
                  das_itrrg(itrrg(itnm):itrrg(itnm)+inr)
     &                     = gmsh(istrg:istrg+inr)
                  itsmn(itnm) = itsmn(itnm) + inr + 1

                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)
                  itsmn(itnm) = itsmn(itnm) + inz + 1

         else if( imesh .eq. 3 .or. lrshow .gt. 0 ) then

                  itxty(itnm) = ixtp
                  itxnm(itnm) = inx
                  rtxdl(itnm) = xdel
                  rtxmi(itnm) = xmin
                  rtxma(itnm) = xmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inx+1, itxrg, das_itxrg)
                  das_itxrg(itxrg(itnm):itxrg(itnm)+inx)
     &                     = gmsh(istxg:istxg+inx)
                  itsmn(itnm) = itsmn(itnm) + inx + 1

                  ityty(itnm) = iytp
                  itynm(itnm) = iny
                  rtydl(itnm) = ydel
                  rtymi(itnm) = ymin
                  rtyma(itnm) = ymax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, iny+1, ityrg, das_ityrg)
                  das_ityrg(ityrg(itnm):ityrg(itnm)+iny)
     &                     = gmsh(istyg:istyg+iny)
                  itsmn(itnm) = itsmn(itnm) + iny + 1

                  itzty(itnm) = iztp
                  itznm(itnm) = inz
                  rtzdl(itnm) = zdel
                  rtzmi(itnm) = zmin
                  rtzma(itnm) = zmax
                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, inz+1, itzrg, das_itzrg)
                  das_itzrg(itzrg(itnm):itzrg(itnm)+inz)
     &                     = gmsh(istzg:istzg+inz)
                  itsmn(itnm) = itsmn(itnm) + inz + 1

         end if

*-----------------------------------------------------------------------
*        axis
*-----------------------------------------------------------------------

                  itaxn(itnm) = inaxi

               do i = 1, inaxi

                  itaxs(itnm,i) = iaxis(i)

               end do

*-----------------------------------------------------------------------
*        file
*-----------------------------------------------------------------------

                  itfln(itnm) = infil

               do i = 1, infil

                  itfll(itnm,i) = lfile(i)

                  ctfln(itnm,i)(1:lfile(i)) = ifile(i)(1:lfile(i))

                  do k = lfile(i) + 1, 100

                     ctfln(itnm,i)(k:k) = ' '

                  end do

               end do

*-----------------------------------------------------------------------
*       restart file
*-----------------------------------------------------------------------
               call summary_param_resfile(itnm,irfflg,lrfile,irfile)

*-----------------------------------------------------------------------
*        particles
*-----------------------------------------------------------------------

            itmxptt = inpat
            itmxgpt = 1
            do i = 1, inpat
              if ( iptyp(i).lt.0 .and. -iptyp(i).gt.itmxgpt ) then
                itmxgpt = -iptyp(i)
              end if
            end do
            call ALLOCATE_PART_TEMP

            if( inpat .gt. 0 ) then

                  itpan(itnm) = inpat

               do i = 1, inpat

                  itpat(itnm,i,1) = iptyp(i)
                  itpat(itnm,i,2) = ipnkf(i)
                  itpat(itnm,i,3) = ipsub(i)  ! kitamura22/03/31

                  if( itpat(itnm,i,1) .lt. 0 ) then

                     do k = 1, -itpat(itnm,i,1)

                        jtpat(itnm,i,k,1) = imtyp(i,k)
                        jtpat(itnm,i,k,2) = imnkf(i,k)

                     end do

                  end if

               end do

            else if( inpat .eq. 0 ) then

                  itpan(itnm) = 1
                  itpat(itnm,1,1) = 20
                  itpat(itnm,1,2) = 0
                  itpat(itnm,1,3) = 0  ! kitamura22/03/31

            end if

*-----------------------------------------------------------------------
*        energy mesh
*-----------------------------------------------------------------------

                  itety(itnm) = ietp
                  itenm(itnm) = ine
                  rtedl(itnm) = edel
                  rtemi(itnm) = emin
                  rtema(itnm) = emax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, ine+1, iterg, das_iterg)
                  das_iterg(iterg(itnm):iterg(itnm)+ine)
     &                     = gmsh(isteg:isteg+ine)
                  itsmn(itnm) = itsmn(itnm) + ine + 1

*-----------------------------------------------------------------------
*        angle mesh
*        and for without angle mesh
*-----------------------------------------------------------------------

               if( ischn(35) .ne. 0 ) then

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, ina+1, itarg, das_itarg)
                  das_itarg(itarg(itnm):itarg(itnm)+ina)
     &                     = gmsh(istag:istag+ina)
                  itsmn(itnm) = itsmn(itnm) + ina + 1

               else

                  iatp = 0
                  ina  = 1

                  istag = iaddress_gmsh(icurrent_gmsh)
                  call moddas_reallocate_dbl(
     &                    3, icurrent_gmsh, 2, iaddress_gmsh, gmsh)
                  iaddress_gmsh(2) = iaddress_gmsh(3)
                  icurrent_gmsh = 2

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, 2, itarg, das_itarg)
                  itsmn(itnm) = itsmn(itnm) + 2

                  gmsh(istag-1+1) = -1.0
                  gmsh(istag-1+2) =  1.0
                  das_itarg(itarg(itnm)-1+1) = -1.0
                  das_itarg(itarg(itnm)-1+2) =  1.0

               end if

                  itaty(itnm) = iatp
                  itanm(itnm) = ina
                  rtadl(itnm) = adel
                  rtami(itnm) = amin
                  rtama(itnm) = amax

*-----------------------------------------------------------------------
*        time mesh
*-----------------------------------------------------------------------

               if( ittp .ne. 0 ) then

                  ittty(itnm) = ittp
                  ittnm(itnm) = int
                  rttdl(itnm) = tdel
                  rttmi(itnm) = tmin
                  rttma(itnm) = tmax

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, int+1, ittrg, das_ittrg)
                  das_ittrg(ittrg(itnm):ittrg(itnm)+int)
     &                     = gmsh(isttg:isttg+int)
                  itsmn(itnm) = itsmn(itnm) + int + 1

               else

                  ittty(itnm) = ittp
                  ittnm(itnm) = 1
                  rttdl(itnm) = 0.d0
                  rttmi(itnm) = 0.d0
                  rttma(itnm) = 0.d0

                  call moddas_reallocate_dbl(
     &                    itlmax, itnm, 2, ittrg, das_ittrg)
                  itsmn(itnm) = itsmn(itnm) + 2

                  das_ittrg(ittrg(itnm)  ) = -1.d+30
                  das_ittrg(ittrg(itnm)+1) =  1.d+30

                  call moddas_reallocate_dbl(
     &                    3, icurrent_gmsh, 2, iaddress_gmsh, gmsh)
                  gmsh(iaddress_gmsh(icurrent_gmsh)  ) = -1.d+30
                  gmsh(iaddress_gmsh(icurrent_gmsh)+1) =  1.d+30
                  iaddress_gmsh(2) = iaddress_gmsh(3)
                  icurrent_gmsh = 2

               end if

*-----------------------------------------------------------------------
*        transformation
*-----------------------------------------------------------------------

                     itmtr(itnm,1) = igkst
                     itmtr(itnm,2) = ktrs
                     itmtr(itnm,3) = idtt
                     itmtr(itnm,4) = 0

               if( igkst .gt. 1 ) then

                  do k = 1, 13

                     rtmtr(itnm,k) = vtrs(k)

                  end do

               end if

*-----------------------------------------------------------------------
*        output
*-----------------------------------------------------------------------

                  itout(itnm) = iout

*-----------------------------------------------------------------------
*        reg echo length
*-----------------------------------------------------------------------

                  iterl(itnm) = iechrl

*-----------------------------------------------------------------------
*        unit
*-----------------------------------------------------------------------

                  itunt(itnm) = iunt

*-----------------------------------------------------------------------
*        2D-type
*-----------------------------------------------------------------------

                  ittwo(itnm) = idtyp

*-----------------------------------------------------------------------
*        factor
*-----------------------------------------------------------------------

                  rtfac(itnm) = rfact

*-----------------------------------------------------------------------
*        volmat
*-----------------------------------------------------------------------

                  itvm(itnm) = matvol

*-----------------------------------------------------------------------
*        epsout
*-----------------------------------------------------------------------

                  iteps(itnm) = ieps

*-----------------------------------------------------------------------
*        bmpout
*-----------------------------------------------------------------------

                  itbmp(itnm) = ibmp

*-----------------------------------------------------------------------
*        vtkout
*-----------------------------------------------------------------------

                  itvtk(itnm) = ivtk

*-----------------------------------------------------------------------
*        vtkfmt
*-----------------------------------------------------------------------

                  itvtkfmt(itnm) = ivtkfmt

*-----------------------------------------------------------------------
*        resolution
*-----------------------------------------------------------------------

                  itres(itnm) = max( 1, ireso )

*-----------------------------------------------------------------------
*        width
*-----------------------------------------------------------------------

                  rtwid(itnm) = width

*-----------------------------------------------------------------------
*        letmat
*-----------------------------------------------------------------------

                  itlmt(itnm) = letmat

*-----------------------------------------------------------------------
*        eng2let
*-----------------------------------------------------------------------

                  ite2l(itnm) = ieng2let

*-----------------------------------------------------------------------
*        counter
*-----------------------------------------------------------------------

               do i = 1, 9

                  itcnt(i,itnm) = icount(i)
                  itcnth(i,itnm) = icounth(i) !frtati 2021/04/06

               end do

*-----------------------------------------------------------------------
*        infog
*-----------------------------------------------------------------------

                  itger(itnm) = infog

*-----------------------------------------------------------------------
*        stdcut
*-----------------------------------------------------------------------
                  rtstd(itnm) = stdcut

*-----------------------------------------------------------------------
*        bmpout
*-----------------------------------------------------------------------
                  itfoam(itnm) = ifoam

*-----------------------------------------------------------------------
*        maxangel
*-----------------------------------------------------------------------
                  itmxang(itnm) = imxang

*-----------------------------------------------------------------------
*        samepage
*-----------------------------------------------------------------------
                  itpgn(itnm) = inpgi

               do i = 1, inpgi

                  itpgs(itnm,i) = ipgis(i)

               end do

*-----------------------------------------------------------------------
*        xy, yz, zx, rz storage region
*-----------------------------------------------------------------------

                     mxyz = 1
                     mrzr = 1
                     mrzz = 1

                  do i = 1, inaxi

                     if( iaxis(i) .eq. 7 ) then

                        if( inx .gt. mxyz ) mxyz = inx
                        if( iny .gt. mxyz ) mxyz = iny

                     else if( iaxis(i) .eq. 8 ) then

                        if( iny .gt. mxyz ) mxyz = iny
                        if( inz .gt. mxyz ) mxyz = inz

                     else if( iaxis(i) .eq. 9 ) then

                        if( inx .gt. mxyz ) mxyz = inx
                        if( inz .gt. mxyz ) mxyz = inz

                     else if( iaxis(i) .eq. 10 ) then

                        mrzr = inr
                        mrzz = inz

                     end if

                  end do

                     itnfn(itnm) = mxyz
                     itnfr(itnm) = mrzr
                     itnfz(itnm) = mrzz

*-----------------------------------------------------------------------
*        dump
*-----------------------------------------------------------------------

                  itmdp(itnm,0) = idump

               if( idump .ne. 0 ) then

                  do i = 1, abs( idump )

                     itmdp(itnm,i) = jdump(i)

                  end do

               end if

*-----------------------------------------------------------------------
*     summary for anatally
*-----------------------------------------------------------------------

         if ( mstz(26) .ne. 3 ) istbat = 0 ! S.H. 2021.8.31
         if( istbat .eq. 0 ) then

                  itism(itnm) = istbat

         else if( istbat .gt. 0 ) then

            if( imesh .eq. 1 ) then
               if( ist_nm(1) .gt. 1 ) then
                  if( ist_nm(1) .gt. ntrn ) goto 967
               else if( ist_nm(1) .le. 0 ) then
                     ist_nm(1) = ntrn
                  do j = 1, ntrn
                     isd_nm(1,j) = j
                  end do
               end if
                     ist_nm(2) = 1
                     isd_nm(2,1) = 1
                     ist_nm(3) = 1
                     isd_nm(3,1) = 1
                     ist_nm(4) = 1
                     isd_nm(4,1) = 1
                     ist_nm(5) = 1
                     isd_nm(5,1) = 1
            else if( imesh .eq. 2 ) then
               if( ist_nm(4) .gt. 1 ) then
                  if( ist_nm(1) .gt. inz ) goto 967
               else if( ist_nm(4) .le. 0 ) then
                     ist_nm(4) = inz
                  do j = 1, inz
                     isd_nm(4,j) = j
                  end do
               end if
               if( ist_nm(5) .gt. 1 ) then
                  if( ist_nm(5) .gt. inr ) goto 967
               else if( ist_nm(5) .le. 0 ) then
                     ist_nm(5) = inr
                  do j = 1, inz
                     isd_nm(5,j) = j
                  end do
               end if
                     ist_nm(1) = 1
                     isd_nm(1,1) = 1
                     ist_nm(2) = 1
                     isd_nm(2,1) = 1
                     ist_nm(3) = 1
                     isd_nm(3,1) = 1
            else if( imesh .eq. 3 ) then
               if( ist_nm(2) .gt. 1 ) then
                  if( ist_nm(2) .gt. inx ) goto 967
               else if( ist_nm(2) .le. 0 ) then
                     ist_nm(2) = inx
                  do j = 1, inx
                     isd_nm(2,j) = j
                  end do
               end if
               if( ist_nm(3) .gt. 1 ) then
                  if( ist_nm(3) .gt. iny ) goto 967
               else if( ist_nm(3) .le. 0 ) then
                     ist_nm(3) = iny
                  do j = 1, iny
                     isd_nm(3,j) = j
                  end do
               end if
               if( ist_nm(4) .gt. 1 ) then
                  if( ist_nm(4) .gt. inz ) goto 967
               else if( ist_nm(4) .le. 0 ) then
                     ist_nm(4) = inz
                  do j = 1, inz
                     isd_nm(4,j) = j
                  end do
               end if
                     ist_nm(1) = 1
                     isd_nm(1,1) = 1
                     ist_nm(5) = 1
                     isd_nm(5,1) = 1
            end if

*-----------------------------------------------------------------------

               if( ist_nm(6) .gt. 1 ) then
                  if( ist_nm(6) .gt. ine ) goto 967
               else if( ist_nm(6) .le. 0 ) then
                     ist_nm(6) = ine
                  do j = 1, ine
                     isd_nm(6,j) = j
                  end do
               end if

               if( ist_nm(7) .gt. 1 ) then
                  if( ist_nm(7) .gt. ittnm(itnm) ) goto 967
               else if( ist_nm(7) .le. 0 ) then
                     ist_nm(7) = ittnm(itnm)
                  do j = 1, ittnm(itnm)
                     isd_nm(7,j) = j
                  end do
               end if

               if( ist_nm(8) .gt. 1 ) then
                  if( ist_nm(8) .gt. ina ) goto 967
               else if( ist_nm(8) .le. 0 ) then
                     ist_nm(8) = ina
                  do j = 1, ina
                     isd_nm(8,j) = j
                  end do
               end if

               if( ist_nm(9) .gt. 1 ) then
                  if( ist_nm(9) .gt. itpan(itnm) ) goto 967
               else if( ist_nm(9) .le. 0 ) then
                     ist_nm(9) = itpan(itnm)
                  do j = 1, itpan(itnm)
                     isd_nm(9,j) = j
                  end do
               end if

               if( ist_nm(10) .gt. 1 ) then
                  if( ist_nm(10) .gt. kmst(1) ) goto 967
               else if( ist_nm(10) .le. 0 ) then
                     if( kmst(1) .le. 0 ) then
                        ist_nm(10) = 1
                     else
                        ist_nm(10) = kmst(1)
                     end if
                  do j = 1, ist_nm(10)
                     isd_nm(10,j) = j
                  end do
               end if

*-----------------------------------------------------------------------

                iall = 1
            do i = 1, 10
                iall = iall * ist_nm(i)
            end do

                istbat = iall

            if( istbat .gt. kvlmax ) goto 966

*-----------------------------------------------------------------------

                jst_nm(1)  = 0
                jst_nm(2)  = jst_nm(1) + ist_nm(1)
                jst_nm(3)  = jst_nm(2) + ist_nm(2)
                jst_nm(4)  = jst_nm(3) + ist_nm(3)
                jst_nm(5)  = jst_nm(4) + ist_nm(4)
                jst_nm(6)  = jst_nm(5) + ist_nm(5)
                jst_nm(7)  = jst_nm(6) + ist_nm(6)
                jst_nm(8)  = jst_nm(7) + ist_nm(7)
                jst_nm(9)  = jst_nm(8) + ist_nm(8)
                jst_nm(10) = jst_nm(9) + ist_nm(9)
                jst_al     = jst_nm(10) + ist_nm(10)

*-----------------------------------------------------------------------

                  istbmm = ( mmmax - 1 ) * 2 + 1
                  mmmax = mmmax + ( jst_al + mod(jst_al,2) ) / 2
                  if( mmmax .gt. mdas ) goto 950

                  itstt(itnm) = istbmm
                  itsmn(itnm) = itsmn(itnm)
     &                        + ( jst_al + mod(jst_al,2) ) / 2

                  itism(itnm) = istbat

            do i = 1, 10
                  itist(i,itnm) = ist_nm(i)
                  itjst(i,itnm) = jst_nm(i)
                  itkst(i,itnm) = kst_nm(i)
            end do

            do i = 1, 10
               do k = 1, itist(i,itnm)
                  idas( itstt(itnm) + itjst(i,itnm) + k ) = isd_nm(i,k)
               end do
            end do

         end if

*-----------------------------------------------------------------------

      return

