         ErrID = 'L:34007/R:anatal_tprodct/F:anatally.f'
         goto 999

  984    m_err = 'Unknown output parameter in tally '//tname
         ErrCha = ''
         ErrID = 'L:34012/R:anatal_tprodct/F:anatally.f'
         goto 999

  985    m_err = 'primary is 0 or 1 '//tname
